local config = {
  ui_story_5022_50220101_1_dialog_content = "Nng... Vice...",
  ui_story_5022_50220101_2_dialog_content = "Vice... Preciso de você aqui...",
  ui_story_5022_50220101_3_dialog_content = "(Se ao menos eu pedisse desculpas a ela naquela época...)",
  ui_story_5022_50220101_4_dialog_content = "<color=#e8d9bb>Alguns dias atrás...</color>",
  ui_story_5022_50220101_5_dialog_content = "<size=45>Pegue isso!</size>",
  ui_story_5022_50220101_6_dialog_content = "Uau, quando você...?! Caramba, que técnica de curva é essa?!",
  ui_story_5022_50220101_7_dialog_content = "Heh, eu ainda tenho muito mais na manga! Estamos a meio caminho da linha de chegada agora... Esta corrida é tão boa quanto a minha!",
  ui_story_5022_50220101_8_dialog_content = "Eu tenho que admitir que você é bom em jogos de corrida, mas ainda é muito cedo para você comemorar!",
  ui_story_5022_50220101_9_dialog_content = "Direita! Hora de mostrar a você a técnica de corrida secreta da Rediesel Wrench—",
  ui_story_5022_50220101_10_dialog_content = "...Ei!",
  ui_story_5022_50220101_11_dialog_content = "V-Vice? Por que você desligou o terminal?! Eu também estava prestes a ganhar...",
  ui_story_5022_50220101_12_dialog_content = "Você realmente precisa que eu explique?",
  ui_story_5022_50220101_13_dialog_content = "Deixando de lado o fato de que você está jogando com os programas de treinamento do Colossus como se fossem videogames... Você se esqueceu completamente dessa lista?!",
  ui_story_5022_50220101_14_dialog_content = "Que lista? Deixe-me dar uma olhada... \"Regimento de auto-treinamento\"?",
  ui_story_5022_50220101_15_dialog_content = "\"Manhãs: 100 flexões. Tardes: 100 abdominais. Noites: 100 agachamentos. Corridas de longa distância diárias...\"",
  ui_story_5022_50220101_16_dialog_content = "Caramba, esse é um plano ambicioso que você tem aí, garoto...",
  ui_story_5022_50220101_17_dialog_content = "Agora me diga, PlayerName, quantos deles você já fez?",
  ui_story_5022_50220101_18_dialog_content = "Uh… B-Bem, eu fiz abdominais esta tarde! Quer dizer, tecnicamente eu estava deitada por um longo tempo e me sentei uma vez, mas…",
  ui_story_5022_50220101_19_dialog_content = "Acordar da soneca da tarde não conta!!",
  ui_story_5022_50220101_20_dialog_content = "Você fez um plano tão ambicioso para si mesmo, mas toda vez que eu verifico você, não passa de jogos, jogos e mais jogos...",
  ui_story_5022_50220101_21_dialog_content = "De manhã à noite, isso é tudo que você tem feito ultimamente!",
  ui_story_5022_50220101_22_dialog_content = "S-Sim, mas... Videogames são como treinamento, se você pensar bem! Minhas mãos estão firmes agora, e meus reflexos nunca foram melhores!",
  ui_story_5022_50220101_23_dialog_content = "Certo, Sinsa?",
  ui_story_5022_50220101_24_dialog_content = "R-Certo! Essa técnica de curva agora foi insana!",
  ui_story_5022_50220101_25_dialog_content = "Ugh... Quer saber?",
  ui_story_5022_50220101_26_dialog_content = "Você pode esquecer de mim ajudando você com qualquer coisa novamente! A partir de agora, você está por sua conta!",
  ui_story_5022_50220101_27_dialog_content = "Estou acabado... O que devo fazer se ela não estiver lá para me lembrar dos meus deveres? Eu posso ser realmente esquecido sobre as coisas às vezes!",
  ui_story_5022_50220101_28_dialog_content = "Quem diabos inventou um plano de treino tão louco?!",
  ui_story_5022_50220101_29_dialog_content = "... Tudo bem, sim, era eu.",
  ui_story_5022_50220101_30_dialog_content = "Eu me pergunto se é tarde demais para se desculpar?",
  ui_story_5022_50220101_31_dialog_content = "E se ela tentar me fazer terminar todos os meus treinos do dia como minha punição?",
  ui_story_5022_50220101_32_dialog_content = "Eu seria um caso perdido, isso é certo...",
  ui_story_5022_50220101_33_dialog_content = "Sim, sem brincadeira.",
  ui_story_5022_50220101_34_dialog_content = "Olhar, Vice está realmente irritado agora. Por que não esperar até que ela esfrie um pouco antes de tentar fazer as pazes? Quem sabe? Ela pode até deixá-lo totalmente fora de perigo!",
  ui_story_5022_50220101_35_dialog_content = "Você tem razão... Espere, por que você parece tão familiarizado com esse tipo de coisa?",
  ui_story_5022_50220101_36_dialog_content = "Heh, ter uma irmãzinha te ensina uma coisa ou duas... De qualquer forma, por enquanto, tente não mostrar seu rosto perto dela.",
  ui_story_5022_50220101_37_dialog_content = "Mas estamos no Colossus... Para onde devo ir?",
  ui_story_5022_50220101_38_dialog_content = "Calma, acabei de lembrar! Já estamos quase nessa época do ano!",
  ui_story_5022_50220101_39_dialog_content = "Ei, PlayerName... Quer ver como é uma corrida de verdade?",
  ui_story_5022_50220101_40_dialog_content = "Nunca esperei ver algo assim no deserto... Que lugar é esse?",
  ui_story_5022_50220101_41_dialog_content = "Bem-vindo ao <color=#FFB400>Oásis</color>, uma das principais fortalezas da Chave Inglesa Rediesel!",
  ui_story_5022_50220101_42_dialog_content = "A visibilidade por aqui é bem ruim, né? Mesmo com Lepidoz, não conseguimos ver mais de dois metros por causa de toda a areia e vento... Que é exatamente o que queremos.",
  ui_story_5022_50220101_43_dialog_content = "O terreno por aqui é bastante complexo, e o clima é igualmente imprevisível. Nós somos os únicos que sabem como encontrar este lugar.",
  ui_story_5022_50220101_44_dialog_content = "Bem, para ser justo, às vezes temos dificuldade em encontrá-lo também...",
  ui_story_5022_50220101_45_dialog_content = "\"Oásis\"...",
  ui_story_5022_50220101_46_dialog_content = "Vê aquela oficina ali? Consertamos nossos veículos e armas lá quando uma ou duas pancadas não resolvem mais.",
  ui_story_5022_50220101_47_dialog_content = "E aquela casa na árvore ali é perfeita para uma boa noite de sono. As paredes impedem que a areia entre em suas roupas, mas todo o lugar tende a balançar para frente e para trás quando o vento está particularmente forte.",
  ui_story_5022_50220101_48_dialog_content = "Você pode comprar bolos de tâmaras de areia neste lugar, e sua torta de escorpião vermelho é bastante decente.",
  ui_story_5022_50220101_49_dialog_content = "E apenas vinte ou trinta pessoas ficam doentes todos os meses por comê-los! Isso é tão seguro quanto ele ganha! Você pode tentar a sua sorte também, se quiser? Ah, e ali...",
  ui_story_5022_50220101_50_dialog_content = "Ei, Sinsa! Bem vindo de volta!",
  ui_story_5022_50220101_51_dialog_content = "Acabamos de descarregar as últimas mercadorias do lagarto gigante.",
  ui_story_5022_50220101_52_dialog_content = "Ouvi dizer que foi Azure quem liderou o caminho desta vez. Não é um mau lance!",
  ui_story_5022_50220101_53_dialog_content = "Estamos indo entregá-lo no depósito, agora que terminaram de fazer o estoque. Cuidado para dar uma olhada, Sinsa?",
  ui_story_5022_50220101_54_dialog_content = "Nah, você pode deixar todas essas coisas de número para Roy. Falando nisso, vocês já o viram por aí?",
  ui_story_5022_50220101_55_dialog_content = "— Ó, poderoso aventureiro de uma terra distante! Eu posso ver o peso do destino pesando sobre seus ombros...",
  ui_story_5022_50220101_56_dialog_content = "Você também precisa da orientação do vento?",
  ui_story_5022_50220101_57_dialog_content = "Aventureiro...?",
  ui_story_5022_50220101_58_dialog_content = "Oi, Zeta! Já faz um tempo, hein? Ainda brincando de faz de conta, eu vejo!",
  ui_story_5022_50220101_59_dialog_content = "M... Faz de conta...?!",
  ui_story_5022_50220101_60_dialog_content = "Ahhh agora entendi...",
  ui_story_5022_50220101_61_dialog_content = "Depois que a mão cruel do destino nos forçou a nos separar, a reação do poder do deus do mal fez com que você perdesse suas memórias e esquecesse seu destino...",
  ui_story_5022_50220101_62_dialog_content = "Mas não se preocupe, pois estou aqui. Não há nada a temer agora.",
  ui_story_5022_50220101_63_dialog_content = "Desperte, ó guerreiro amaldiçoado! Desperte, ó berserker solitário e três vezes divorciado, condenado a vagar pelas terras sem lugar para chamar de lar!",
  ui_story_5022_50220101_64_dialog_content = "Huh...? Ah sim, acho que parte disso faz sentido...",
  ui_story_5022_50220101_65_option_content = "\"Guerreiro amaldiçoado\"?",
  ui_story_5022_50220101_66_dialog_content = "Ah, é apenas parte do jogo de faz de conta do Zeta. Ela fez uma persona inteira só para mim.",
  ui_story_5022_50220101_67_dialog_content = "Agora, como foi...? Eu estava vagando pela terra em busca de poder, e então... algo sobre minha alma...",
  ui_story_5022_50220101_68_dialog_content = "Você foi às ruínas de Ishradi e ofereceu sua alma ao antigo deus do mal, Y'noth-raz!",
  ui_story_5022_50220101_69_option_content = "Você já se divorciou três vezes?",
  ui_story_5022_50220101_70_dialog_content = "De jeito nenhum!",
  ui_story_5022_50220101_71_dialog_content = "É tudo parte de... Como se chama? ...Oh sim! Um \"jogo de role-playing\"! Zeta fez um personagem inteiro só para mim.",
  ui_story_5022_50220101_72_dialog_content = "O problema é que ela continua mudando partes da história, então não tenho certeza de onde estamos agora...",
  ui_story_5022_50220101_73_dialog_content = "Você estava vagando pela terra em busca de maior poder, e depois de chegar às ruínas de Ishradi, você ofereceu sua alma ao antigo deus do mal, Y'noth-raz!",
  ui_story_5022_50220101_74_dialog_content = "Mas logo depois, você percebeu que era um poder amaldiçoado, e então... Você começou sua jornada para derrotar o rei demônio...",
  ui_story_5022_50220101_75_dialog_content = "Oh sim! Eu me lembro agora!",
  ui_story_5022_50220101_76_dialog_content = "Graças a Deus você caiu em si. Agora, oh poderoso berserker, posso gentilmente perguntar... Quem é aquele ao seu lado?",
  ui_story_5022_50220101_77_option_content = "N-Prazer em conhecê-lo! Meu nome é PlayerName!",
  ui_story_5022_50220101_78_dialog_content = "PlayerName, você diz? Hmm... eu posso sentir um poder antigo e misterioso adormecido dentro de você...",
  ui_story_5022_50220101_79_dialog_content = "Pode ser porque eu sou um celestita... Você já ouviu falar de nós? Uma raça de pessoas que podem ver Lumina, além de pilotar os grandes Colossos!",
  ui_story_5022_50220101_80_option_content = "Eu sou o último dos celestitas! O Navegador do Colosso e o guia da luz!",
  ui_story_5022_50220101_81_dialog_content = "<size=45>O... O Último dos Caelestitas!!!</size>",
  ui_story_5022_50220101_82_dialog_content = "Esse título... Esse título é a coisa mais legal que eu já ouvi!",
  ui_story_5022_50220101_83_dialog_content = "Não diga isso! Você está me envergonhando...",
  ui_story_5022_50220101_84_dialog_content = "Ahem... Peço desculpas pela explosão desnecessária agora.",
  ui_story_5022_50220101_85_dialog_content = "Parece que ainda tenho muito treinamento a fazer se quiser me tornar um guerreiro de Astra.",
  ui_story_5022_50220101_86_dialog_content = "Por favor, permita-me mostrar o caminho até a princesa. May os ventos nos guiam...",
  ui_story_5022_50220101_87_dialog_content = "... E é aí que as coisas estão no momento. Enviarei uma mensagem pelo Sindicato dos Correios imediatamente se algo mudar.",
  ui_story_5022_50220101_88_dialog_content = "Claro, mas... tem certeza que não precisa de mais pessoas, Azure?",
  ui_story_5022_50220101_89_dialog_content = "Aqueles camaradas em Umbraton causaram uma verdadeira confusão com aquelas drogas ilícitas da última vez.",
  ui_story_5022_50220101_90_dialog_content = "Isso de novo não... Já te disse antes, prefiro trabalhar sozinho. Qualquer outra pessoa simplesmente entraria no meu caminho.",
  ui_story_5022_50220101_91_dialog_content = "Pare de me tratar como uma criança.",
  ui_story_5022_50220101_92_dialog_content = "Eu sei eu sei! É apenas...",
  ui_story_5022_50220101_93_dialog_content = "Ajuda! Acho que algo está errado com minha bomba de alarme! Não está explodindo como antes...",
  ui_story_5022_50220101_94_dialog_content = "Deixe-me dar uma olhada... Basta puxar o fusível assim, e dar-lhe um tapinha ou dois, e... Pronto, como novo.",
  ui_story_5022_50220101_95_dialog_content = "Já chegaram os petiscos para o Lepidoz?",
  ui_story_5022_50220101_96_dialog_content = "Brock e Fleur estavam ajudando a entregá-los. Se ainda não o fizeram... Provavelmente, Brock comeu enquanto ninguém estava olhando.",
  ui_story_5022_50220101_97_dialog_content = "Se for esse o caso, apenas alimente Brock para Lepidoz. Tenho certeza de que não vai se importar.",
  ui_story_5022_50220101_98_dialog_content = "Precisamos expandir o armazém aqui no Oasis! Quase não tenho espaço para guardar as peças da minha máquina!",
  ui_story_5022_50220101_99_dialog_content = "Por que não tentar pendurar algumas de suas peças no teto? Temos uma corda bonita e resistente, bem ali.",
  ui_story_5022_50220101_100_dialog_content = "Ou, você pode usá-lo para amarrar Jomu por alguns dias, até que ele concorde em abrir espaço para você.",
  ui_story_5022_50220101_101_dialog_content = "Sobre aquela remessa de dois dias atrás...",
  ui_story_5022_50220101_102_dialog_content = "Armazém 6, em um caixote coberto por uma lona. Tente ser cuidadoso, sim? Esses pequenos insetos mordem, e seu veneno também não é brincadeira.",
  ui_story_5022_50220101_103_dialog_content = "Quanto ao material de hoje...",
  ui_story_5022_50220101_104_dialog_content = "A lista está na parede ali. Vou dar uma olhada depois.",
  ui_story_5022_50220101_105_dialog_content = "Uh... Desculpe Azure, Quase não tenho chance de falar com você e aqui estou... Sobre o que estávamos conversando agora?",
  ui_story_5022_50220101_106_dialog_content = "Princesa! Seu guerreiro mais estimado voltou!",
  ui_story_5022_50220101_107_dialog_content = "E agora eu sou uma princesa, hein... Este dia não está ficando mais fácil...",
  ui_story_5022_50220101_108_dialog_content = "Ahem... Louvado seja a orientação do vento por levá-lo de volta ao meu lado, nobre guerreiro. E o conflito nas fronteiras do nosso reino?",
  ui_story_5022_50220101_109_dialog_content = "As forças demoníacas foram descaradas em seus ataques às aldeias fronteiriças, mas não se preocupe, Alteza. Meus companheiros de confiança e eu acabamos com os demônios vis!",
  ui_story_5022_50220101_110_dialog_content = "Como sinal de gratidão, muitas das donzelas da aldeia nos ofereceram doces para protegê-las do mal.",
  ui_story_5022_50220101_111_dialog_content = "Entendo... Entăo os Eclipsites foram derrotados por enquanto.",
  ui_story_5022_50220101_112_dialog_content = "Várias aldeias surgiram na área desde que concordamos em ajudar a proteger a fonte de água local. Os ataques do Eclipsite poderiam ter algo a ver com isso...?",
  ui_story_5022_50220101_113_dialog_content = "Você parece perturbado, Sua Alteza. Como posso ser útil?",
  ui_story_5022_50220101_114_dialog_content = "Parte meu coração ver um rosto tão bonito manchado de angústia...",
  ui_story_5022_50220101_115_dialog_content = "F-Feira...? Er... Você já fez mais do que o suficiente, meu bravo herói.",
  ui_story_5022_50220101_116_dialog_content = "A mão do destino recomenda que você se livre do cansaço de suas viagens e desfrute de um merecido descanso. Minha ajuda está sempre disponível se você precisar de alguém para trançar seu cabelo.",
  ui_story_5022_50220101_117_dialog_content = "Bem, olhe para você. Com certeza você ganhou a aprovação da mamãe hoje, Zeta! Nada mal nada mal!",
  ui_story_5022_50220101_X117_dialog_content = "Mãe... Você quer dizer eu?",
  ui_story_5022_50220101_118_dialog_content = "—Pffff!",
  ui_story_5022_50220101_119_dialog_content = "Suspiro... Toda vez que vocês dois se encontram...",
  ui_story_5022_50220101_120_dialog_content = "Certo, quem mais precisa da ajuda da mamãe hoje? Hum? Isso é um novo rosto que eu vejo?",
  ui_story_5022_50220101_121_dialog_content = "Sim! Permita-me apresentá-lo a um jovem amigo com poderes místicos—PlayerName, o último dos celestitas!",
  ui_story_5022_50220101_122_dialog_content = "Entendo... Prazer em conhecê-lo. Nomes Roy. Apenas um cara normal gerenciando logística e reparos para a Chave Rediesel.",
  ui_story_5022_50220101_123_dialog_content = "Sinsa raramente traz amigos... O último dos celestitas, hein?",
  ui_story_5022_50220101_124_dialog_content = "Bem, qualquer amigo do líder é um amigo nosso, assim como um estimado convidado da Chave Rediesel. Receber, PlayerName.",
  ui_story_5022_50220101_125_dialog_content = "Se você está aqui nesta época do ano, só pode ser para o Blazing Rally, certo? Agora que penso nisso, é hora de decidir sobre um local.",
  ui_story_5022_50220101_126_dialog_content = "Quer dizer que ainda nem decidiu onde realizar a corrida?!",
  ui_story_5022_50220101_127_dialog_content = "Sim, há muitas pistas, mas só escolhemos qual delas realizar a corrida com um dia de antecedência.",
  ui_story_5022_50220101_128_dialog_content = "Mesmo assim, as forças de Lumopolis têm essa tendência de aparecer em busca de criminosos procurados e veículos perdidos.",
  ui_story_5022_50220101_129_dialog_content = "Claro, também é divertido estar cercado.",
  ui_story_5022_50220101_130_dialog_content = "Th-Isso parece emocionante…",
  ui_story_5022_50220101_131_dialog_content = "(... estou muito familiarizado com todos, então às vezes esqueço que eles são um grupo de bandidos errantes...)",
  ui_story_5022_50220101_132_dialog_content = "Ahaha! Mas eu não deveria continuar com isso. Temos convidados. Devemos nos comportar. Você tem alguma ideia, líder?",
  ui_story_5022_50220101_133_dialog_content = "Bem, se queremos que o nosso amigo celestita expanda os seus horizontes, há sempre o <color=#FFB400>Dente Ardente</color>.",
  ui_story_5022_50220101_134_dialog_content = "Aposto que esses nobres moles, soldados envelhecidos e mercenários não têm coragem de nos seguir até o deserto.",
  ui_story_5022_50220101_135_dialog_content = "Não! Esse lugar fica perto da minha área de patrulha. Ninguém pode me vencer lá, vai ser chato!",
  ui_story_5022_50220101_136_dialog_content = "O tempo está ótimo, então por que não vamos ao Pesadelo Ouroboro pelo Rio Dourado?",
  ui_story_5022_50220101_137_dialog_content = "Ou podemos ir para o Inferno Verde ao lado do Corredor Sussurrante e irritar alguns idiotas Umbraton!",
  ui_story_5022_50220101_138_dialog_content = "(Então esse garoto pode falar normalmente depois de tudo!)",
  ui_story_5022_50220101_139_dialog_content = "Hm… The Blazing Tooth é uma rota clássica.",
  ui_story_5022_50220101_140_dialog_content = "Mas a pista é muito difícil, e a equipe de logística costuma reclamar das consequências. Além do mais, ainda há Eclipsites aparecendo, mesmo com varreduras regulares.",
  ui_story_5022_50220101_141_dialog_content = "De acordo com o relatório de Zeta, os Eclipsites têm estado extraordinariamente ativos recentemente, o que exigirá algumas investigações.",
  ui_story_5022_50220101_142_dialog_content = "Tenho a sensação de que pode haver um grande na área, mas posso estar pensando demais...",
  ui_story_5022_50220101_143_dialog_content = "...!",
  ui_story_5022_50220101_144_dialog_content = "Um grande? Poderia ser o lendário <color=#FFB400>Dragão Malvado Hakudoma</color>?",
  ui_story_5022_50220101_145_dialog_content = "Hum, era assim que se chamava?",
  ui_story_5022_50220101_146_dialog_content = "Eu inventei! É legal, certo? Direita?",
  ui_story_5022_50220101_147_dialog_content = "Eu pensei que era um bom ajuste depois de ouvir a história que você me contou sobre isso.",
  ui_story_5022_50220101_148_dialog_content = "Uma história, hein... Que despreocupação...",
  ui_story_5022_50220101_149_dialog_content = "Ei, Roy, Vou verificar a área sozinho amanhã.",
  ui_story_5022_50220101_150_dialog_content = "Você apenas relaxa e joga jogos de corrida com as crianças.",
  ui_story_5022_50220101_151_dialog_content = "Você… Você está dizendo que eu sou uma criança?",
  ui_story_5022_50220101_152_dialog_content = "E que o Blazing Rally é um jogo?!",
  ui_story_5022_50220101_153_dialog_content = "Não apenas isso, você quer se divertir desafiando o dragão malvado por conta própria?!",
  ui_story_5022_50220101_154_dialog_content = "Isso não vai ficar. Eu desafio você para um duelo de corrida!",
  ui_story_5022_50220101_155_dialog_content = "Tsk, pirralho problemático...",
  ui_story_5022_50220101_156_dialog_content = "Eu vou vencê-lo no rally!",
  ui_story_5022_50220101_157_dialog_content = "E se o dragão aparecer, vou avançar na sua frente e destruí-lo, assim como os heróis das histórias!",
  ui_story_5022_50220101_158_dialog_content = "...Provavelmente.",
  ui_story_5022_50220101_159_dialog_content = "Não tenho tempo para jogar seus joguinhos.",
  ui_story_5022_50220101_160_dialog_content = "D-Não vá! Não finja que não me ouviu. Vou arrastá-lo para a cabine de registro se for preciso!",
  ui_story_5022_50220101_161_dialog_content = "Ei! Não pense que você pode ir embora só porque tem pernas longas! Espere por mim!",
  ui_story_5022_50220101_162_dialog_content = "Ooh. Agora, isso é interessante.",
  ui_story_5022_50220101_163_dialog_content = "Um duelo?",
  ui_story_5022_50220101_164_dialog_content = "Na Chave Rediesel, os duelos são um assunto sério. A pessoa desafiada deve aceitar o desafio.",
  ui_story_5022_50220101_165_dialog_content = "Para proteger sua honra? Na verdade, eu não tinha ideia de que a Rediesel Wrench pudesse ser tão...",
  ui_story_5022_50220101_166_dialog_content = "Não. É para que todos possam se reunir e assistir à diversão.",
  ui_story_5022_50220101_167_dialog_content = "Acho que eu deveria ter previsto isso...",
  ui_story_5022_50220101_168_dialog_content = "Ei, ei, é importante ter um programa para assistir.",
  ui_story_5022_50220101_169_dialog_content = "As regras do duelo são super frouxas, vale tudo. Brock uma vez me desafiou para uma competição de comedores de lagartos assados, e eu venci.",
  ui_story_5022_50220101_170_dialog_content = "Embora nós dois tenhamos sido repreendidos por Roy após...",
  ui_story_5022_50220101_171_dialog_content = "Quantas vezes eu já disse a vocês para não comerem lanches antes de dormir? Depois dessa pequena façanha, nossas reservas de comida—",
  ui_story_5022_50220101_172_dialog_content = "Aham! Então, parece que a pista está decidida e é a Blazing Tooth. Sem objeções? Bom. Roy, ainda tenho que mostrar ao nosso convidado!",
  ui_story_5022_50220101_173_dialog_content = "Bem, se o líder diz isso…",
  ui_story_5022_50220101_174_dialog_content = "Eu deveria ir me preparar para a corrida também.",
  ui_story_5022_50220101_175_dialog_content = "PlayerName, você deve esperar por isso!",
  ui_story_5022_50220201_1_dialog_content = "(Como eu vim parar aqui… E isso é só o começo…)",
  ui_story_5022_50220201_2_dialog_content = "<size=45>-Pegue isso! Tiro Relâmpago!</size>",
  ui_story_5022_50220201_3_dialog_content = "Não é um Blazing Rally adequado sem ele! Ei, perdedores na frente! Você está queimando ainda?!",
  ui_story_5022_50220201_4_dialog_content = "Seu idiota! Eu vou te mostrar como é uma arma de rally clássica! Coma caltrops, seu parasita!",
  ui_story_5022_50220201_5_dialog_content = "Uaaargh! Nós vamos passar por cima deles!",
  ui_story_5022_50220201_6_dialog_content = "Fofa. Os truques deles são tão antigos que estou ficando nostálgico por aqui!",
  ui_story_5022_50220201_7_dialog_content = "(De alguma forma saímos ilesos...)",
  ui_story_5022_50220201_8_dialog_content = "Isso é melhor. Mais silencioso.",
  ui_story_5022_50220201_9_dialog_content = "Então, hora de explicações.",
  ui_story_5022_50220201_S9_dialog_content = "Por que você está no meu banco do passageiro, Caelestite?",
  ui_story_5022_50220201_10_dialog_content = "C-Você não pode chegar tão perto? Azure! Olhos na estrada! A estrada!",
  ui_story_5022_50220201_11_dialog_content = "Sinsa disse-me para sentar aqui e esperar por ele, mas então o tiro de partida disparou e ele ainda não tinha aparecido.",
  ui_story_5022_50220201_12_dialog_content = "Em vez disso, o que apareceu foi...",
  ui_story_5022_50220201_13_dialog_content = "Esqueça. Não me importo de passar algum tempo sozinho com um garoto tão fofo, contanto que você não me dê problemas.",
  ui_story_5022_50220201_14_dialog_content = "T-Para ser honesto, eu não esperava que houvesse uma série de acidentes logo no início... todos os competidores são tão brutais...",
  ui_story_5022_50220201_15_dialog_content = "Que tipo de rali é esse?!",
  ui_story_5022_50220201_16_dialog_content = "Você tem coragem de entrar no meu carro sem saber nada sobre este evento.",
  ui_story_5022_50220201_17_dialog_content = "Sinsa estava muito ocupado me arrastando para comer torta de escorpião para explicar qualquer coisa...",
  ui_story_5022_50220201_18_dialog_content = "Sua direção é impressionante para nos tirar daquele caos.",
  ui_story_5022_50220201_19_dialog_content = "Hm, você é um pouco tonto, mas bem bajulador, não é?",
  ui_story_5022_50220201_20_dialog_content = "De qualquer forma, não é nada. Este é apenas um jogo, e ser sério sobre isso é o que eu deveria estar fazendo.",
  ui_story_5022_50220201_21_dialog_content = "E o duelo?",
  ui_story_5022_50220201_22_dialog_content = "Que pergunta boba. Sim, eu aceitei o desafio, mas e daí se aquele boneco ganhar?",
  ui_story_5022_50220201_23_dialog_content = "O que é mais importante é rastrear os movimentos dos Eclipsites.",
  ui_story_5022_50220201_24_dialog_content = "Para que possamos evitar a repetição desses eventos...",
  ui_story_5022_50220201_25_dialog_content = "Falando nisso, o lendário dragão perverso—",
  ui_story_5022_50220201_26_dialog_content = "Uau!",
  ui_story_5022_50220201_27_dialog_content = "O que foi que aconteceu?",
  ui_story_5022_50220201_28_dialog_content = "Você sempre faz tantas perguntas? Estou começando a me arrepender de deixar você ficar no carro.",
  ui_story_5022_50220201_29_dialog_content = "Acabei de passar por cima de um Eclipse, só isso. Não foi fatal pela sensação, e provavelmente vai se recuperar mais tarde.",
  ui_story_5022_50220201_30_dialog_content = "... Alcançar?",
  ui_story_5022_50220201_31_dialog_content = "Uh-huh, deve haver mais Eclipsites à frente também.",
  ui_story_5022_50220201_32_dialog_content = "Mais...?",
  ui_story_5022_50220201_33_dialog_content = "Quem sabe, talvez eu até encontre aquele Eclipsite que eu estava procurando.",
  ui_story_5022_50220201_34_dialog_content = "Não é tarde demais para você correr por sua vida se estiver com medo.",
  ui_story_5022_50220201_35_dialog_content = "Mesmo alguém como você deve ser capaz de atravessar este pedaço de deserto e voltar ao ponto de partida.",
  ui_story_5022_50220201_36_dialog_content = "Hã...",
  ui_story_5022_50220201_37_dialog_content = "Eh... Brincadeira! Sua expressão agitada é mais divertida do que eu pensava.",
  ui_story_5022_50220201_38_dialog_content = "Que pena, parece que nosso doce tempo sozinho está prestes a ser interrompido.",
  ui_story_5022_50220201_39_dialog_content = "O-o que...?",
  ui_story_5022_50220201_40_dialog_content = "—Yohoo! PlayerName!",
  ui_story_5022_50220201_41_dialog_content = "Yaawn... Parece que dormimos demais e perdemos o início da competição.",
  ui_story_5022_50220201_42_dialog_content = "Isso era você! não perdi nada!",
  ui_story_5022_50220201_43_dialog_content = "Aterrissando em um pneu, passando por entre as fendas passando pelos caras bloqueando a estrada, é assim que a Srta. Azure faz isso!",
  ui_story_5022_50220201_44_dialog_content = "Espere, o carro esteve em movimento o tempo todo. Como vocês chegaram aqui?",
  ui_story_5022_50220201_45_dialog_content = "Do telhado!",
  ui_story_5022_50220201_46_dialog_content = "Legal. E aqui eu pensei que vocês dois teriam se sacudido com o impacto mais cedo e caído de cara na areia.",
  ui_story_5022_50220201_47_dialog_content = "Você estava dormindo tão profundamente no meu carro sem permissão, eu senti que você merecia um tipo especial de chamada de despertar.",
  ui_story_5022_50220201_48_dialog_content = "Não seja tão frio! Eu tive que pegar assentos na primeira fila para o retorno do ex-campeão de rali.",
  ui_story_5022_50220201_49_dialog_content = "PlayerName, eu consegui um bom lugar para você, não foi? Você pode me agradecer mais tarde.",
  ui_story_5022_50220201_50_dialog_content = "Azure é minha sênior, ela se juntou ao Rediesel Wrench antes de mim.",
  ui_story_5022_50220201_51_dialog_content = "Mais importante, ela é uma corredora lendária!",
  ui_story_5022_50220201_52_dialog_content = "Lendário, hein? Isso ficou no passado.",
  ui_story_5022_50220201_53_dialog_content = "A única razão que consigo pensar para sua presença é... Hmph. Intrometidos.",
  ui_story_5022_50220201_54_dialog_content = "Jovem Sinsa aqui não é um júnior adorável, mas ele ainda é o líder.",
  ui_story_5022_50220201_55_dialog_content = "Ele disse a palavra, então vou deixar vocês ficarem.",
  ui_story_5022_50220201_56_dialog_content = "Mas deixe-me esclarecer: estou viajando para a área de Blazing Tooth para investigar os Eclipsites. A minha rota acaba por se sobrepor à pista de corridas.",
  ui_story_5022_50220201_57_dialog_content = "Parece que temos mais caroneiros vindo atrás de nós...",
  ui_story_5022_50220201_58_dialog_content = "Como as crianças desobedientes devem ser punidas?",
  ui_story_5022_50220202_1_dialog_content = "O carro de corrida de Azure acabou de disparar um canhão contra os Eclipsites atrás de nós...?",
  ui_story_5022_50220202_2_dialog_content = "Você sabe o que, neste momento, nada realmente me incomoda mais.",
  ui_story_5022_50220202_3_dialog_content = "<size=45>Olá pessoal-!</size>Este é o seu anfitrião, Jomu! Sente minha falta?",
  ui_story_5022_50220202_4_dialog_content = "Uau! O que é isso?",
  ui_story_5022_50220202_5_dialog_content = "O Blazing Rally faz jus ao seu nome, começando com um estrondo...",
  ui_story_5022_50220202_6_dialog_content = "Isso mesmo, metade dos nossos competidores já foram eliminados em seus pontos de partida!",
  ui_story_5022_50220202_7_dialog_content = "Infelizmente, alguns deles foram danos colaterais nos acidentes de outros. Mas a sorte também faz parte do jogo aqui!",
  ui_story_5022_50220202_8_dialog_content = "Tenha certeza de todos os derrotados que jazem entre os destroços!",
  ui_story_5022_50220202_9_dialog_content = "Rabbie e Chainsaw Rick da Equipe de Logística 6 chegará para retirar todos vocês de seus veículos no devido tempo!",
  ui_story_5022_50220202_10_dialog_content = "Os que ainda estão na corrida estão agora disparando para a primeira etapa, a <color=#FFB400>Deserto de ar quente</color>, na velocidade máxima!",
  ui_story_5022_50220202_11_dialog_content = "Vamos sentar e ver que espetáculos emocionantes estão por vir!",
  ui_story_5022_50220202_12_dialog_content = "Isso é... uma transmissão ao vivo?",
  ui_story_5022_50220202_13_dialog_content = "Como sempre, o Blazing Rally é patrocinado exclusivamente por ninguém menos que Rediesel Wrench.",
  ui_story_5022_50220202_14_dialog_content = "Rediesel Wrench, seu melhor amigo no deserto.",
  ui_story_5022_50220202_15_dialog_content = "Oferecemos segurança da vila, reparos de máquinas, reciclagem, combate e outros serviços para sua conveniência!",
  ui_story_5022_50220202_16_dialog_content = "As taxas... bem, elas são mais baratas que a Illumina de qualquer forma, e nós garantimos transparência!",
  ui_story_5022_50220202_17_dialog_content = "Faça um pedido agora e ganhe uma mini estatueta artesanal do famoso Lepidoz da Rediesel Wrench!",
  ui_story_5022_50220202_X17_dialog_content = "O estoque é limitado, então é por ordem de chegada! Não perca!",
  ui_story_5022_50220202_18_dialog_content = "A seguir, vamos anunciar os resultados da pesquisa de audiência da última corrida...",
  ui_story_5022_50220202_19_dialog_content = "O feedback com mais votos: Podemos nos livrar do locutor barulhento?",
  ui_story_5022_50220202_20_dialog_content = "Obrigada! A sua satisfação é a nossa motivação para melhorar!",
  ui_story_5022_50220202_21_dialog_content = "Infelizmente, todos os outros são muito tímidos ou acham essa tarefa muito difícil, então ainda sou o anfitrião da corrida deste ano!",
  ui_story_5022_50220202_22_dialog_content = "Como compensação, no entanto, convidei comentaristas convidados para você!",
  ui_story_5022_50220202_23_dialog_content = "Estaremos transmitindo da estação de rádio oficial em Lepidoz, compartilhando notícias sobre a corrida e muitas outras mensagens!",
  ui_story_5022_50220202_24_dialog_content = "... O que? Você quer que eu sente aqui? Tenho outras coisas importantes para⁠—",
  ui_story_5022_50220202_25_dialog_content = "Você realmente quer um velho como eu fazendo isso? Não consigo pensar em nada divertido para dizer...",
  ui_story_5022_50220202_26_dialog_content = "(Ele claramente acabou de ser enrolado aleatoriamente para fazer isso!)",
  ui_story_5022_50220202_27_dialog_content = "E agora, vamos ter...",
  ui_story_5022_50220202_28_dialog_content = "Oh, quero dizer, vamos ter nosso comentarista convidado Roy apresentar as regras da competição aos nossos amigos que são novos nisso!",
  ui_story_5022_50220202_29_dialog_content = "Uh... Regras? Nós não fazemos essas coisas chatas.",
  ui_story_5022_50220202_30_dialog_content = "Quem se inscrever pode usar qualquer veículo para completar o curso designado. Tudo o que você precisa fazer é permanecer no veículo o maior tempo possível e concluir o percurso o mais rápido possível.",
  ui_story_5022_50220202_31_dialog_content = "Precisamente! Conquiste a natureza com bravura, empurre-se além das limitações!",
  ui_story_5022_50220202_32_dialog_content = "Deixe o fogo em seus motores e seu coração impulsioná-lo na batalha!",
  ui_story_5022_50220202_33_dialog_content = "Há mais alguma coisa que nosso comentarista convidado gostaria de acrescentar?",
  ui_story_5022_50220202_34_dialog_content = "Há mais alguma coisa a acrescentar? Eu acho... Divirta-se e tente voltar vivo.",
  ui_story_5022_50220202_35_dialog_content = "Sinta-se livre para ir selvagem. Enquanto ainda houver vida em você, não há nada que a equipe de logística não possa fazer.",
  ui_story_5022_50220202_36_dialog_content = "Excelente! Como esperado de Roy, desencadeando uma declaração tão extrema tão casualmente!",
  ui_story_5022_50220202_37_dialog_content = "E esta não é a única surpresa que preparamos este ano.",
  ui_story_5022_50220202_38_dialog_content = "O lendário piloto invicto, conhecido como Sexy Wildcat da Rediesel Race, está de volta às pistas pela primeira vez em uma década!",
  ui_story_5022_50220202_39_dialog_content = "Jomu...!",
  ui_story_5022_50220202_40_dialog_content = "(Há uma aura intensamente perigosa emanando de Azure...)",
  ui_story_5022_50220202_41_dialog_content = "Eu nunca ouvi esse apelido na minha vida... Você estará na linha de visão dela em breve, não é tarde demais para controle de danos.",
  ui_story_5022_50220202_42_dialog_content = "É um pequeno sacrifício a ser feito pelo bem do show.",
  ui_story_5022_50220202_43_dialog_content = "E falando nisso!",
  ui_story_5022_50220202_44_dialog_content = "Dizem que o poderoso Eclipsite que apareceu em Blazing Tooth há mais de dez anos—",
  ui_story_5022_50220202_45_dialog_content = "—O Dragão Malvado Hakudoma, pode aparecer de novo!",
  ui_story_5022_50220202_46_dialog_content = "Quando esse nome se tornou oficial... Bem, Zeta vai adorar.",
  ui_story_5022_50220202_47_dialog_content = "De qualquer forma, vim porque queria discutir os prêmios com você.",
  ui_story_5022_50220202_48_dialog_content = "Quase esqueci! Os prêmios deste ano são os mais luxuosos até agora!",
  ui_story_5022_50220202_49_dialog_content = "Como sempre, é o primeiro a chegar, primeiro a ser servido, e eles incluem um ingresso interativo Lepidoz de um dia, Barbara e a Regina...",
  ui_story_5022_50220202_50_dialog_content = "Os prêmios sumiram.",
  ui_story_5022_50220202_51_dialog_content = "Hein? O que quer dizer com isso?",
  ui_story_5022_50220202_52_dialog_content = "Lepidoz comeu o ingresso interativo de um dia.",
  ui_story_5022_50220202_53_dialog_content = "Barbara e Regina não queriam lançar seus respectivos álbuns juntos, e os amadores explosivos tinham uma seleção anual de seis membros em um...",
  ui_story_5022_50220202_54_dialog_content = "Joanie Boom venceu, mas ela não resistiu à tentação e detonou sua bomba antes mesmo de a corrida começar.",
  ui_story_5022_50220202_55_dialog_content = "Ela disse algo sobre não tê-lo testado depois de fazê-lo, então enviou um arenito afiado explodindo no céu.",
  ui_story_5022_50220202_56_dialog_content = "Achei bem decente, mas ela continuou insistindo que a cor da chama poderia ter mais melhorias estéticas.",
  ui_story_5022_50220202_57_dialog_content = "Ok, deixe-me corrigir-me—",
  ui_story_5022_50220202_58_dialog_content = "Parece que os prêmios para a corrida deste ano serão os mesmos dos anos anteriores: minha própria mistura de proteína em pó ultra-secreta...",
  ui_story_5022_50220202_59_dialog_content = "E uma boneca animal artesanal de um doador anônimo!",
  ui_story_5022_50220202_60_dialog_content = "Além disso, cada piloto recebe um prêmio de participação!",
  ui_story_5022_50220202_61_dialog_content = "Qual seria-",
  ui_story_5022_50220202_62_dialog_content = "A experiência de estar vivo, a paixão quente borbulhando nas veias e a alegria de rir com todos no meio do vento, sob o sol tórrido!",
  ui_story_5022_50220202_63_dialog_content = "(Esta estação de rádio pode ser desligada...?)",
  ui_story_5022_50220202_64_dialog_content = "Aguentar! Para aqueles que estão prestes a desligar o rádio, temos mais um prêmio misterioso a ser revelado mais tarde!",
  ui_story_5022_50220202_65_dialog_content = "As coisas emocionantes começam aqui. Mas primeiro, uma mensagem importante—",
  ui_story_5022_50220202_66_dialog_content = "A Octobro Shaved Ice, a barraca de raspas de gelo em frente ao Tir' Hotel, lançou recentemente um novo produto!",
  ui_story_5022_50220202_67_dialog_content = "Chama-se Lies Taste Like Sweet Honey. Apenas desperta o interesse, não é? Todos que participaram do teste de sabor, seja auroriano ou lobo, disseram...",
  ui_story_5022_50220202_68_dialog_content = "Ufa, finalmente acabou. As pessoas gostam de prêmios assim...",
  ui_story_5022_50220202_69_dialog_content = "Ha, nunca se sabe.",
  ui_story_5022_50220202_70_dialog_content = "Os membros da Rediesel Wrench sempre foram responsáveis pela coleta dos prêmios. Tivemos ainda pior em anos anteriores.",
  ui_story_5022_50220202_71_dialog_content = "A questão é que, mesmo que não houvesse prêmios envolvidos, as pessoas ainda viriam apenas para se divertir.",
  ui_story_5022_50220202_72_dialog_content = "(é a senhorita Azure... sorridente?)",
  ui_story_5022_50220202_73_dialog_content = "...Azure, será que você realmente gosta do Blazing Rally...?",
  ui_story_5022_50220202_74_dialog_content = "Acabamos de nos conhecer e você já está tentando entrar na minha cabeça. Não é uma maneira inteligente de dar em cima de alguém, Caelestite.",
  ui_story_5022_50220202_75_dialog_content = "C-como devo dizer... Este evento é uma loucura. É assim que a Chave Rediesel faz as coisas...?",
  ui_story_5022_50220202_76_dialog_content = "Sobre o que você está murmurando?",
  ui_story_5022_50220202_77_dialog_content = "Zeta?",
  ui_story_5022_50220202_78_dialog_content = "Oh? Eu não posso acreditar que você reconheceu minha voz tão rapidamente.",
  ui_story_5022_50220202_79_dialog_content = "Você realmente não é um fornecedor casual... Mestre do Colosso, guia da luz, último dos celestitas.",
  ui_story_5022_50220202_80_option_content = "Apenas me ligue PlayerName.",
  ui_story_5022_50220202_81_dialog_content = "Fictício! É um ótimo título! É um desperdício não usá-lo mais!",
  ui_story_5022_50220202_82_dialog_content = "Vamos ver... Certo, então por que estamos sendo agraciados com a presença da Miss Sweet Devil no canal de comunicação?",
  ui_story_5022_50220202_83_dialog_content = "Você... Você está me tomando por um tolo, não é?!",
  ui_story_5022_50220202_84_dialog_content = "Não é esse o nome do time que você inventou? Senhorita—Doce—Demônio.",
  ui_story_5022_50220202_85_dialog_content = "Não ria quando você diz isso!",
  ui_story_5022_50220202_86_option_content = "Hehe, você me lisonjeia.",
  ui_story_5022_50220202_87_dialog_content = "Oh? Eu não esperava que você gostasse tanto de roleplay. Que fofo.",
  ui_story_5022_50220202_88_dialog_content = "Bem, então... Senhorita Doce Diabo, o que você quer do meu celestita?",
  ui_story_5022_50220202_89_dialog_content = "\"Minhas\"...?",
  ui_story_5022_50220202_90_dialog_content = "Não... Não ria sempre que você mencionar o nome que eu me esforcei tanto para criar!",
  ui_story_5022_50220202_91_dialog_content = "Só estou aqui para ver por que sua bucha de canhão é tão lenta!",
  ui_story_5022_50220202_92_dialog_content = "O nome do seu time não é Sweet Devil? Evoca uma imagem confusa...",
  ui_story_5022_50220202_93_dialog_content = "Ano passado foi Child of the Wilderness ou algo assim...",
  ui_story_5022_50220202_94_dialog_content = "Berserker Sinsa! Por que você está no carro daquela mulher...? Você traiu sua missão?!",
  ui_story_5022_50220202_95_dialog_content = "Isso é... é...",
  ui_story_5022_50220202_96_dialog_content = "Hehehe. Eu sei, você está apenas fingindo ser enganado por ela, mas na verdade está esperando por uma oportunidade para me ajudar a parar o progresso dela...",
  ui_story_5022_50220202_97_dialog_content = "Eu aprecio seus esforços, mas pretendo lutar contra ela de forma justa!",
  ui_story_5022_50220202_98_dialog_content = "Parece que o caos da linha de partida não foi suficiente para acabar com você.",
  ui_story_5022_50220202_99_dialog_content = "Embora seja surpreendente que apenas algumas pequenas bombas tenham causado tanto tumulto...",
  ui_story_5022_50220202_100_dialog_content = "Não, o tailgating aconteceu principalmente porque um certo careca puxou um lançador de mísseis!",
  ui_story_5022_50220202_101_dialog_content = "Ohohoho! Treme, Celestita!",
  ui_story_5022_50220202_102_dialog_content = "Ela não está ouvindo nada.",
  ui_story_5022_50220202_103_dialog_content = "Eu hospedo o poder de um deus demônio dentro de mim... Eu sou o diabo! Eu sou a ameaça! Incompreendido por todos no mundo...",
  ui_story_5022_50220202_104_dialog_content = "...No entanto, há o espírito de um guerreiro bondoso dentro de mim!",
  ui_story_5022_50220202_105_dialog_content = "Ela está agindo como se não estivesse ouvindo, mas claramente acabou de consertar o buraco na trama de sua história...",
  ui_story_5022_50220202_106_dialog_content = "Assim... eu farei você ver a derrota, Azure.",
  ui_story_5022_50220202_107_dialog_content = "Também conhecido como Absolute Zero Witch, lacaio de um dos quatro Reis Celestiais, o Rei Demônio!",
  ui_story_5022_50220202_108_dialog_content = "Quem no mundo é o Rei Demônio e os outros três... Quer saber, eu não quero saber.",
  ui_story_5022_50220202_109_dialog_content = "Eu tenho que admitir, eu prefiro Absolute Zero Witch a Sexy Wildcat.",
  ui_story_5022_50220202_110_dialog_content = "Desde o primeiro ano que ganhei o Blazing Rally...",
  ui_story_5022_50220202_111_dialog_content = "Os tolos compararam meu recorde com o seu, dizendo que se você não tivesse saído dos trilhos, talvez eu nunca tivesse chance de vencer.",
  ui_story_5022_50220202_112_dialog_content = "E você está sempre fazendo missões perigosas dizendo que quer treinar sua força, fazendo Roy se preocupe com você!",
  ui_story_5022_50220202_113_dialog_content = "Não há mais palavras precisam ser ditas. Nossas vidas já foram tecidas pela Mão do Destino.",
  ui_story_5022_50220202_114_dialog_content = "Piloto das lendas, é melhor você não me decepcionar.",
  ui_story_5022_50220202_115_dialog_content = "Ela até acrescentou um floreio extra no final...",
  ui_story_5022_50220202_116_dialog_content = "É divertido ver alguém se esforçar tanto, não é? Apesar disso, ela não tem o que é preciso para ser impertinente.",
  ui_story_5022_50220202_117_dialog_content = "Mas como corredora, ela é uma adversária que não deve ser subestimada.",
  ui_story_5022_50220202_118_dialog_content = "Você ouviu o vento no fundo da transmissão dela? Houve interferências, mas tenho certeza.",
  ui_story_5022_50220202_119_dialog_content = "Zeta saiu na frente de todos os outros e já está no Deserto do Ar Quente.",
  ui_story_5022_50220202_120_dialog_content = "Como o antagonista designado para seu protagonista, vou ter que melhorar meu jogo.",
  ui_story_5022_50220301_1_dialog_content = "*Bocejo* Onde estamos?",
  ui_story_5022_50220301_2_dialog_content = "Ah! Já não estamos no Deserto do Ar Quente?",
  ui_story_5022_50220301_3_dialog_content = "Eu tenho alguns vermes de areia secos aqui. Quer um pouco? Eu vou comê-los se você não quiser.",
  ui_story_5022_50220301_4_dialog_content = "Vocês sabem que isso não é um piquenique, certo?",
  ui_story_5022_50220301_5_dialog_content = "Heheh, eu estava tão ansiosa por hoje que não dormi nada a noite passada!",
  ui_story_5022_50220301_6_dialog_content = "Entre a condução rápida e firme de Azure e o zumbido de Jomu, fiquei com tanto sono...",
  ui_story_5022_50220301_7_dialog_content = "Falando nisso, Jomu deveria ser o locutor, mas é apenas um anúncio atrás do outro e nada sobre a corrida real!",
  ui_story_5022_50220301_8_dialog_content = "Os pontos de partida são diferentes, mas todos os competidores passam pelo posto de controle no Deserto do Ar Quente a caminho da estação de serviço no Vulcão Dragon Breath.",
  ui_story_5022_50220301_9_dialog_content = "Em seguida, eles passam pelo Blazing Tooth Canyon, para finalmente chegar à extremidade da Noite Eterna.",
  ui_story_5022_50220301_10_dialog_content = "Como o nome indica, é uma pista para o fim do mundo.",
  ui_story_5022_50220301_11_dialog_content = "O fim do mundo...",
  ui_story_5022_50220301_12_dialog_content = "O tempo parece bom hoje, então não devemos encontrar tempestades de areia. A última vez que corremos, a areia estava nos atingindo no rosto...",
  ui_story_5022_50220301_13_dialog_content = "Há tempestades de areia? Isso soa muito arriscado...",
  ui_story_5022_50220301_14_dialog_content = "Não se preocupe, mesmo se você for arrastado para o céu, sempre há uma saída!",
  ui_story_5022_50220301_15_dialog_content = "Hum. Devemos encontrar outros concorrentes em breve.",
  ui_story_5022_50220301_16_dialog_content = "Ah! Olhar, PlayerName, olhar!",
  ui_story_5022_50220301_17_dialog_content = "Isso...",
  ui_story_5022_50220301_18_dialog_content = "Cuidado!",
  ui_story_5022_50220301_19_dialog_content = "Tsk, tsk. ainda bem honcho Sinsa foi rápido e te puxou de volta.",
  ui_story_5022_50220301_20_dialog_content = "Você sabe que isso não é um piquenique, certo, PlayerName?",
  ui_story_5022_50220301_21_dialog_content = "Foi o Moinho de Vento das Sombras de Clover que quase cortou um pedaço do meu cabelo?",
  ui_story_5022_50220301_22_dialog_content = "Ei, isso é perigoso! Você tem que pagar se me fizer perder alguma das minhas penas!",
  ui_story_5022_50220301_23_dialog_content = "U-hum, g-caras... Não briguem... Movimentar-se é perigoso...",
  ui_story_5022_50220301_24_dialog_content = "Waaaah! Eu sou muito melhor com uma moto em comparação com isso ...",
  ui_story_5022_50220301_25_dialog_content = "Aquele urso começou.",
  ui_story_5022_50220301_26_dialog_content = "Não me use como bode expiatório!",
  ui_story_5022_50220301_27_dialog_content = "<size=45>Claro que não recebi uma comissão para vir a este lugar quente para participar desta corrida e dizer a Kuma para emboscar você para aumentar minhas chances de ganhar!</size>",
  ui_story_5022_50220301_28_dialog_content = "Pengy, não acostumado, a mentir.",
  ui_story_5022_50220301_29_dialog_content = "Trabalhe comigo, parceiro! Você sabe o que eu tenho que passar apenas para ganhar a vida?",
  ui_story_5022_50220301_30_dialog_content = "Parece que o Sr. Pengy tem seu trabalho cortado para ele...",
  ui_story_5022_50220301_31_dialog_content = "Maggie, olhos na estrada. Desconfie de encostas de areia.",
  ui_story_5022_50220301_32_dialog_content = "Ah! Uma abertura!",
  ui_story_5022_50220301_33_dialog_content = "... Eu quero gritar até ficar rouco, mas essa garota estranhamente calma ...",
  ui_story_5022_50220301_34_dialog_content = "Cale-se!!! Pare de perturbar meu sono! Quer comer balas?!",
  ui_story_5022_50220301_35_dialog_content = "A-Uma emboscada?! Prove o poder dessas conchas! Ártico-",
  ui_story_5022_50220301_36_dialog_content = "Desviando a atenção, projéteis falsos e tudo explodido. Tão rápido.",
  ui_story_5022_50220301_37_dialog_content = "B-Antes que eu pudesse usar Luminatics, você...",
  ui_story_5022_50220301_38_dialog_content = "Huh? Não é esta senhorita Kafka?!",
  ui_story_5022_50220301_39_dialog_content = "O que, são vocês dois... Então vocês finalmente decidiram se juntar à Rediesel Wrench?",
  ui_story_5022_50220301_40_dialog_content = "Woof?",
  ui_story_5022_50220301_41_dialog_content = "Não pense tão pouco de nós. Ao contrário deste crocodilo aqui, não nos juntamos a vocês apenas para uma piscina ruim e três refeições por dia.",
  ui_story_5022_50220301_42_dialog_content = "Ei, não pense que não posso te expulsar do carro só porque estou dirigindo. Ou você quer ser transformado em um travesseiro macio?",
  ui_story_5022_50220301_43_dialog_content = "Sim! Vocês gostam muito dessa piscina, certo?",
  ui_story_5022_50220301_44_dialog_content = "De fato, passamos muito tempo nos refrescando na piscina do Oasis, atualizando fofocas e notícias via Rediesel Wrench.",
  ui_story_5022_50220301_45_dialog_content = "Perder Kafka também nos alimenta com lanches de vez em quando, mas...",
  ui_story_5022_50220301_46_dialog_content = "Minhas asas de liberdade nunca serão compradas por essas pequenas sutilezas!",
  ui_story_5022_50220301_47_dialog_content = "Ainda tenho dor de cabeça de ficar acordado até tarde para o trabalho. Não tenho tempo para suas bobagens. Olhe aqui.",
  ui_story_5022_50220301_48_dialog_content = "Suas conchas eram apenas uma tática de diversão. Essas latas de arenque, no entanto, são a coisa real.",
  ui_story_5022_50220301_49_dialog_content = "!!!",
  ui_story_5022_50220301_50_dialog_content = "Eu vou jogá-los.",
  ui_story_5022_50220301_51_dialog_content = "W-Nós temos isso—",
  ui_story_5022_50220301_X51_dialog_content = "Eu também—",
  ui_story_5022_50220301_X52_dialog_content = "Aaaahhhh!!",
  ui_story_5022_50220301_X53_dialog_content = "Pengy! Segure-se em mim!",
  ui_story_5022_50220301_52_dialog_content = "Aquele pinguim estúpido não teve que pular de um carro em alta velocidade apenas por algumas latas...",
  ui_story_5022_50220301_53_dialog_content = "Kuma estava tentando salvá-lo e caiu também... Eles rolaram para tão longe que não consigo mais vê-los.",
  ui_story_5022_50220301_54_dialog_content = "Devem ser as asas da liberdade de que eles estavam falando... Realmente, ninguém os derrota em palhaçadas.",
  ui_story_5022_50220301_55_dialog_content = "Tudo bem, seus dois companheiros de equipe estão caindo na areia, Sork. Eles praticamente desistiram.",
  ui_story_5022_50220301_56_dialog_content = "Aquelas latas de peixe não foram desperdiçadas. Eu sei que estamos visando a mesma coisa.",
  ui_story_5022_50220301_57_dialog_content = "O confronto é inevitável.",
  ui_story_5022_50220301_58_dialog_content = "Uau!",
  ui_story_5022_50220301_59_dialog_content = "Eu não entendo... Eu realmente não entendo.",
  ui_story_5022_50220301_60_dialog_content = "Por que... Por que as pelúcias que Roy torna apenas por diversão tão popular?",
  ui_story_5022_50220301_61_dialog_content = "Alguns colecionadores até contratam Bounty Hunters a preços absurdos apenas para colocar as mãos em um.",
  ui_story_5022_50220301_62_dialog_content = "Porque pode haver um coelho desta vez. Você não pode perder os coelhos.",
  ui_story_5022_50220301_63_dialog_content = "Bunnybear Plushes não são páreo para sua textura fofa. Você está garantido uma boa noite de sono abraçando um.",
  ui_story_5022_50220301_64_dialog_content = "Au, au!",
  ui_story_5022_50220301_65_dialog_content = "Não importa como eles se pareçam... ou de que materiais são feitos... Sempre parece uma carícia suave...",
  ui_story_5022_50220301_66_dialog_content = "Materiais simples, mas feitos com delicadeza e requinte. Faz uma espreguiçadeira perfeita no ninho.",
  ui_story_5022_50220301_67_dialog_content = "Bekk... Até você é fã!?",
  ui_story_5022_50220301_68_dialog_content = "Kafka está certo, pirralho! Essa batalha é inevitável.",
  ui_story_5022_50220301_69_dialog_content = "É uma oportunidade rara. Já que estamos nisso, por que não descobrir quem é o melhor atirador do que Rediesel Wrench?",
  ui_story_5022_50220301_70_dialog_content = "Não há onde se esconder! Franz, vá!",
  ui_story_5022_50220301_71_dialog_content = "Chilro! Bekk furioso!",
  ui_story_5022_50220301_72_dialog_content = "Minha vez! M23 Alto Explosivo!",
  ui_story_5022_50220301_73_dialog_content = "Parece bastante animado por lá... Não deveríamos fazer algo a respeito?",
  ui_story_5022_50220301_74_dialog_content = "Está bem. Bater uns nos outros também faz parte da corrida.",
  ui_story_5022_50220301_75_dialog_content = "Familiarizar-se com as habilidades um do outro permitirá que eles trabalhem melhor juntos na batalha.",
  ui_story_5022_50220301_76_dialog_content = "Não sabia que era tão profundo...",
  ui_story_5022_50220301_77_dialog_content = "Ah, eu acabei de encontrar essa explicação aleatoriamente. Eu impressiono até a mim mesma!",
  ui_story_5022_50220301_78_dialog_content = "Não podemos nos distanciar deles e dar a volta por cima?",
  ui_story_5022_50220301_79_dialog_content = "Não é que não possamos, mas esta área está cheia de vermes de areia gigantes.",
  ui_story_5022_50220301_80_dialog_content = "Se nos desviarmos do caminho, provavelmente acabaremos como petiscos de minhocas, carro e tudo. Ou pior, a areia movediça nos engoliria.",
  ui_story_5022_50220301_81_dialog_content = "Mas mesmo a rota designada nos leva através de seus campos de caça...",
  ui_story_5022_50220301_82_dialog_content = "A propósito, ouvi dizer que havia concorrentes que trouxeram seus próprios vermes gigantes domados em anos anteriores.",
  ui_story_5022_50220301_83_dialog_content = "Está certo. Eles se saíram bem, para minha surpresa, mas eu ainda ganhei no final.",
  ui_story_5022_50220301_84_dialog_content = "Uau! Há uma ogiva gigante vindo nesta direção! Eu me pergunto de que cor será sua explosão...",
  ui_story_5022_50220301_85_dialog_content = "Tsk... Que bando de crianças, espalhando seus brinquedos assim.",
  ui_story_5022_50220301_86_dialog_content = "Você está seriamente chamando os explosivos de \"brinquedos\"?!",
  ui_story_5022_50220301_87_dialog_content = "Brinquedos que machucam ao pisar. Os dois atiradores parecem mais profissionais, mas a maneira como eles seguram suas armas poderia ser mais...",
  ui_story_5022_50220301_88_dialog_content = "Azure! Vez! Vire agora!",
  ui_story_5022_50220301_89_dialog_content = "<color=#e8d9bb>BUM!</color>",
  ui_story_5022_50220301_90_dialog_content = "Ah, apenas um amarelo normal. Entediante.",
  ui_story_5022_50220301_91_dialog_content = "Ufa, isso foi perto... Que onda de choque...",
  ui_story_5022_50220301_92_dialog_content = "Você se divertiu o suficiente? Se vamos nos mexer, encontrei uma boa rota.",
  ui_story_5022_50220301_93_dialog_content = "tendo saudades Azure aqui me faz sentir segura. E aquela virada linda agora a pouco, nem precisei avisar...",
  ui_story_5022_50220301_94_dialog_content = "Não não não não! O que ela chama de uma boa rota—",
  ui_story_5022_50220301_95_dialog_content = "Caelestite, você gosta de bruto?",
  ui_story_5022_50220301_96_dialog_content = "O quê?",
  ui_story_5022_50220301_97_dialog_content = "PlayerName, pressa! Segure-se em algo!",
  ui_story_5022_50220501_1_dialog_content = "(Eu estava sonhando?)",
  ui_story_5022_50220501_2_dialog_content = "(Sonhei que estávamos correndo em direção a uma enorme encosta de areia. O carro explodiu no ar, e o tempo parecia ter parado.)",
  ui_story_5022_50220501_3_dialog_content = "(Ao nosso redor havia eclipsitas espreitando nas sombras dos pedregulhos. Todos eles olharam para cima, e eu encontrei o olhar de centenas de pares de olhos.)",
  ui_story_5022_50220501_4_dialog_content = "(Os Eclipsitas foram rapidamente derrotados, mas então as dunas de areia começaram a se separar...)",
  ui_story_5022_50220501_5_dialog_content = "(E algo apareceu do chão... uma boca cheia de dentes?)",
  ui_story_5022_50220501_6_dialog_content = "Isso foi... um sonho?",
  ui_story_5022_50220501_7_dialog_content = "Foi real.",
  ui_story_5022_50220501_8_dialog_content = "Estamos indo bem rápido, então aquele verme da areia faminto é o problema da equipe de Kafka.",
  ui_story_5022_50220501_9_dialog_content = "Estarão bem?",
  ui_story_5022_50220501_10_dialog_content = "A propósito, isso é o que você chama de \"gostar mais áspero\"?!",
  ui_story_5022_50220501_11_dialog_content = "Ei! Vocês ainda estão vivos, meus ouvintes e competidores?",
  ui_story_5022_50220501_12_dialog_content = "Eu sou Jomu, seu anfitrião. O Blazing Rally está realmente esquentando agora! Matar ou ser morto, pessoal!",
  ui_story_5022_50220501_13_dialog_content = "Os vermes da areia gigantes são hóspedes ocasionais que gostam de aparecer abruptamente, e também podem ser encontrados no Deserto do Ar Quente!",
  ui_story_5022_50220501_14_dialog_content = "Quem sabe se teremos mais visitantes surpresa mais tarde na corrida?",
  ui_story_5022_50220501_15_dialog_content = "Por exemplo, o lendário dragão malvado de nove cabeças, seis garras e três asas!",
  ui_story_5022_50220501_16_dialog_content = "Você realmente vai dizer qualquer coisa para irritar a multidão. Você já anunciou algo importante?",
  ui_story_5022_50220501_17_dialog_content = "Odi da divisão de comunicação está coletando os sinais de desistência dos competidores devido aos ataques dos vermes da areia. Mas antes disso...",
  ui_story_5022_50220501_18_dialog_content = "Todos! O Eclipsite conhecido como Wicked Dragon é o mesmo que foi expulso pelo nosso comentarista convidado anos atrás!",
  ui_story_5022_50220501_19_dialog_content = "O que Roy tem a dizer sobre este velho amigo?",
  ui_story_5022_50220501_20_dialog_content = "Por que de repente... Bem, sim. Foi uma pena que não fomos capazes de matar o Eclipsite naquela época.",
  ui_story_5022_50220501_21_dialog_content = "A fortaleza havia sofrido uma emboscada dos Eclipsitas. Estávamos sem munição, e suas garras me perfuraram...",
  ui_story_5022_50220501_22_dialog_content = "Mas eu ainda gostaria de ter tentado mais naquela época.",
  ui_story_5022_50220501_23_dialog_content = "Perfurado através de você?!",
  ui_story_5022_50220501_24_dialog_content = "Ah, não foi nada. De qualquer forma, deixo a luta para os jovens hoje em dia.",
  ui_story_5022_50220501_25_dialog_content = "Dito isto, certas pessoas devem levar um pouco mais fácil. Mesmo que tenham o que é preciso, nem sempre devem tentar fazer as coisas por conta própria...",
  ui_story_5022_50220501_26_dialog_content = "Já que estamos aqui, por que não relaxar um pouco e curtir a corrida?",
  ui_story_5022_50220501_27_dialog_content = "... Então essa criatura realmente existe? Eu pensei que era apenas algo das histórias de Zeta, como o deus do mal...",
  ui_story_5022_50220501_28_dialog_content = "Você assustado? Quer um abraço?",
  ui_story_5022_50220501_29_option_content = "Não estou!",
  ui_story_5022_50220501_30_dialog_content = "É assim mesmo? Sua falsa bravata também é fofa.",
  ui_story_5022_50220501_31_option_content = "Sim por favor!",
  ui_story_5022_50220501_32_dialog_content = "Oh? Eu amo um garoto honesto. Infelizmente, estou ocupado agora.",
  ui_story_5022_50220501_33_dialog_content = "Já se foi há quantos anos? Não é à toa que a história ficou tão rebuscada.",
  ui_story_5022_50220501_34_dialog_content = "E agora aparece no mesmo ano em que eu volto... É muita coincidência, não?",
  ui_story_5022_50220501_35_dialog_content = "Mas existiu e ainda existe...",
  ui_story_5022_50220501_36_dialog_content = "... Vou corrigir isso.",
  ui_story_5022_50220501_37_dialog_content = "(Seu olhar é mais aterrorizante do que um dragão de nove cabeças...)",
  ui_story_5022_50220501_38_dialog_content = "(Algo aconteceu naquela época...?)",
  ui_story_5022_50220501_39_dialog_content = "Em seguida, eu tenho um anúncio importante! De verdade dessa vez!",
  ui_story_5022_50220501_40_dialog_content = "Primeiro, confirmamos os sinais luminosos dos competidores que desistiram.",
  ui_story_5022_50220501_41_dialog_content = "O Lepidoz logo chegará ao local de destino para pegar todos os seus medrosos, então fique quieto!",
  ui_story_5022_50220501_42_dialog_content = "O mais surpreendente é que esta é a primeira vez que tivemos tão poucas lesões até agora na corrida.",
  ui_story_5022_50220501_43_dialog_content = "Assim, vamos apimentar as coisas revelando o misterioso prêmio deste ano...",
  ui_story_5022_50220501_44_dialog_content = "<size=45>\"Faça um desejo de Eve\"!</size>",
  ui_story_5022_50220501_45_dialog_content = "O quê?",
  ui_story_5022_50220501_46_dialog_content = "Isso mesmo! Chaves Rediesel Eve vai fazer qualquer desejo seu se tornar realidade!",
  ui_story_5022_50220501_47_dialog_content = "O vencedor desejará ver o sorriso da dama ou emprestará o poder da Necroide Dark Star?",
  ui_story_5022_50220501_48_dialog_content = "Estou ansioso para descobrir!",
  ui_story_5022_50220501_49_dialog_content = "Eve nem me avisou...",
  ui_story_5022_50220501_50_dialog_content = "Você teria objetado, não teria?",
  ui_story_5022_50220501_51_dialog_content = "Por que eu faria isso?",
  ui_story_5022_50220501_52_dialog_content = "Vê-la totalmente recuperada e disposta a recuperar todas as coisas que ela perdeu...",
  ui_story_5022_50220501_53_dialog_content = "E usando seu poder para ajudar a todos... eu não poderia estar mais feliz.",
  ui_story_5022_50220501_54_dialog_content = "Oh sério? Você sabe que é \"qualquer desejo\", certo?",
  ui_story_5022_50220501_55_dialog_content = "Por exemplo, e se alguém quiser se casar com ela?",
  ui_story_5022_50220501_56_dialog_content = "...Ah?",
  ui_story_5022_50220501_57_option_content = "Essa é uma possibilidade",
  ui_story_5022_50220501_58_dialog_content = "Eve é adorável e gentil. Qualquer um iria querer protegê-la.",
  ui_story_5022_50220501_59_dialog_content = "Qualquer um teria a sorte de acompanhá-la pelo resto da vida...",
  ui_story_5022_50220501_60_dialog_content = "O que diabos você está pensando!?",
  ui_story_5022_50220501_61_dialog_content = "N-Nada!",
  ui_story_5022_50220501_62_option_content = "eu duvido",
  ui_story_5022_50220501_63_dialog_content = "O que? Você não acha que nosso Eve é bom o suficiente, é isso?",
  ui_story_5022_50220501_64_dialog_content = "Claro que ela é!",
  ui_story_5022_50220501_65_dialog_content = "Se alguém que realmente a amasse, a valorizasse e a protegesse com sua vida realmente aparecesse...",
  ui_story_5022_50220501_66_dialog_content = "O que fazer? Essa pequena piada tem Sinsa todos enrolados em consternação!",
  ui_story_5022_50220501_67_dialog_content = "É tudo culpa sua, PlayerName. Diga algo!",
  ui_story_5022_50220501_68_dialog_content = "Minha culpa!?",
  ui_story_5022_50220501_69_dialog_content = "Ei você! Fora do caminho! Estou indo a toda velocidade aqui!",
  ui_story_5022_50220501_70_dialog_content = "Senão eu vou mandar você voando!",
  ui_story_5022_50220501_71_dialog_content = "Tecnicamente falando, é \"Brock está sentado no carro que Fleur está dirigindo a toda velocidade.\"",
  ui_story_5022_50220501_72_dialog_content = "Ei, você realmente vai cair no mar se continuar inclinando seu corpo para fora da janela assim!",
  ui_story_5022_50220501_73_dialog_content = "Oh garoto, aí vem o problema...",
  ui_story_5022_50220501_74_dialog_content = "Oooooh! Não é isso PlayerName!?",
  ui_story_5022_50220501_75_dialog_content = "Você está um passo mais perto de se tornar um jovem de sangue quente e viril juntando-se ao Blazing Rally! Mas é claro, você ainda não é páreo para mim!",
  ui_story_5022_50220501_76_dialog_content = "Deixe-me ver... Seus companheiros de equipe estão Joanie Boom e.... Senhorita Azure!?",
  ui_story_5022_50220501_77_dialog_content = "Muito tempo sem ver, Brock. Parece que você engordou um pouco desde a última vez que nos vimos.",
  ui_story_5022_50220501_78_dialog_content = "Nossa, você continua linda como sempre...",
  ui_story_5022_50220501_79_dialog_content = "Ah, quero dizer o-claro! Já sou o segundo em comando da Rediesel Wrench!",
  ui_story_5022_50220501_80_dialog_content = "Eu sou o homem mais popular em Rediesel Wrench, mas ainda treino todos os dias! Eu nunca folga!",
  ui_story_5022_50220501_81_dialog_content = "Da mesma forma, mesmo que eu esteja enfrentando você neste rally, ainda triunfarei e conquistarei o primeiro lugar!",
  ui_story_5022_50220501_82_dialog_content = "Afinal, o grande prêmio estava destinado a mim.",
  ui_story_5022_50220501_83_dialog_content = "O grande prêmio...?",
  ui_story_5022_50220501_84_dialog_content = "Sinsa?! O que você está fazendo aqui?",
  ui_story_5022_50220501_85_dialog_content = "Alguém mais fraco do que eu é capaz de proteger minha irmã? Teste... Certo. Eu devo testar você.",
  ui_story_5022_50220501_86_dialog_content = "Por que você está murmurando para si mesmo? Hmph, é porque eu disse que sou o segundo em comando...?",
  ui_story_5022_50220501_87_dialog_content = "Por que você está abrindo a porta... Ah, vamos lá! Eu não deveria ter me gabado, mas você não precisa ficar tão chateado!",
  ui_story_5022_50220501_88_dialog_content = "Perder Azure, o que é isso atrás Brock e o carro de Fleur?",
  ui_story_5022_50220501_89_dialog_content = "Qualquer que seja! Se você quer uma luta, eu te dou uma luta!",
  ui_story_5022_50220501_90_dialog_content = "Eu vou vencê-lo em nosso duelo 873 e eliminar seu time no processo!",
  ui_story_5022_50220501_91_dialog_content = "Espere, não é hora de brigar... Eclipses chegando!",
  ui_story_5022_50220502_1_dialog_content = "Não acabamos de derrotar uma onda deles? Há muitos deles!",
  ui_story_5022_50220502_2_dialog_content = "Uau! Olha a poeira que eles levantaram! É como uma tempestade de areia!",
  ui_story_5022_50220502_3_dialog_content = "Mesmo que a areia esteja obstruindo parcialmente minha visão, ainda posso sentir os Eclipsitos se reunindo tanto à nossa frente quanto atrás de nós.",
  ui_story_5022_50220502_4_dialog_content = "Essa é a habilidade especial de sua espécie? Muito legal, Celestita.",
  ui_story_5022_50220502_5_dialog_content = "não parece Sinsa e Brock vão parar...",
  ui_story_5022_50220502_6_dialog_content = "Huh? Quando eles subiram no carro?",
  ui_story_5022_50220502_7_dialog_content = "Bem, obviamente. Nenhuma hora é a hora errada para uma luta entre o Rediesel Wrench!",
  ui_story_5022_50220502_8_dialog_content = "Ha, jovens de sangue quente... Eles nunca são capazes de segurar seus cavalos.",
  ui_story_5022_50220502_9_dialog_content = "Talvez eu realmente devesse relaxar e me divertir um pouco...",
  ui_story_5022_50220502_10_dialog_content = "Eu vou lidar com os Eclipsites na parte de trás. Celestita, assuma o volante.",
  ui_story_5022_50220502_11_dialog_content = "Conte comigo! Vamos, vamos explodi-los bem alto!",
  ui_story_5022_50220502_12_dialog_content = "Eu? Mas eu não sei dirigir...",
  ui_story_5022_50220502_13_dialog_content = "Ei, não solte o volante assim!",
  ui_story_5022_50220502_14_dialog_content = "Hehe, mal posso esperar. Então, por onde começar?",
  ui_story_5022_50220502_15_dialog_content = "Deixe-me devastar todos vocês!",
  ui_story_5022_50220502_16_dialog_content = "Perder Azure, o que eu deveria...",
  ui_story_5022_50220502_17_dialog_content = "Hum? Não diga que acabou. Estamos apenas começando.",
  ui_story_5022_50220502_18_dialog_content = "(Acalme-se... Acalme-se! Há armas e explosões, mas apenas acalme-se!)",
  ui_story_5022_50220502_19_dialog_content = "(Use seu instinto, gire o volante e encontre uma maneira de atravessá-los...!)",
  ui_story_5022_50220502_20_dialog_content = "O que você está esperando, PlayerName! Aperte o gás, vamos!",
  ui_story_5022_50220502_21_dialog_content = "Não se esqueça que eu sou um novato! Qual é o acelerador... esse?!",
  ui_story_5022_50220502_22_dialog_content = "Fleur, vamos acelerar também!",
  ui_story_5022_50220502_23_dialog_content = "Uau. Eu subi no telhado só para parecer legal, mas isso realmente é alto...",
  ui_story_5022_50220502_24_dialog_content = "Agora!",
  ui_story_5022_50220502_25_dialog_content = "Brock, é melhor—",
  ui_story_5022_50220502_26_dialog_content = "-Comportar-se!",
  ui_story_5022_50220502_27_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5022_50220502_28_dialog_content = "Aff...",
  ui_story_5022_50220502_29_dialog_content = "Ei, Brock, se você se esquivar, o capô da Powerball será amassado.",
  ui_story_5022_50220502_30_dialog_content = "Coitadinho. Doeu, não foi? Gostaria de saber se tenho peças suficientes para repará-lo.",
  ui_story_5022_50220502_31_dialog_content = "Olá? Eu ainda estou aqui, seu mecânico geek!",
  ui_story_5022_50220502_32_dialog_content = "E eu não me esquivei! Isso faz parte da minha estratégia! Agora estou dando tudo o que tenho!",
  ui_story_5022_50220502_33_dialog_content = "Você deve estar bem se ainda é capaz de gritar assim.",
  ui_story_5022_50220502_34_dialog_content = "Perdemos o controle do carro, vamos direto para aquela pedra.",
  ui_story_5022_50220502_35_dialog_content = "Hã?",
  ui_story_5022_50220502_36_dialog_content = "Sinsa, importa-se de dar uma mão já que decidiu pegar carona conosco?",
  ui_story_5022_50220502_37_dialog_content = "Conseguimos!",
  ui_story_5022_50220502_38_dialog_content = "Não há mais Eclipsites depois de nós... Azure cuidar de todos aqueles Eclipsites?!",
  ui_story_5022_50220502_39_dialog_content = "Ei, eu ajudei! Eu também quero elogios!",
  ui_story_5022_50220502_40_dialog_content = "Só que isso não é nada que valha a pena se vangloriar. Os fracos não duram no deserto.",
  ui_story_5022_50220502_41_dialog_content = "No entanto, você é mais confiável do que eu esperava, Celestita. Isso foi muito bom para uma primeira vez.",
  ui_story_5022_50220502_42_dialog_content = "Sim! Quer considerar se inscrever como um concorrente formal da próxima vez...?",
  ui_story_5022_50220502_43_dialog_content = "Espere, se você vai competir de qualquer maneira, por que não ir all in e desafiar o recorde do Azure?",
  ui_story_5022_50220502_44_option_content = "Agora estou interessado",
  ui_story_5022_50220502_45_dialog_content = "Ah, que emocionante. Mas você precisará de mais treinamento para ser um oponente satisfatório para mim.",
  ui_story_5022_50220502_46_dialog_content = "(Ela parece feliz...)",
  ui_story_5022_50220502_47_option_content = "eu não sou tão bom",
  ui_story_5022_50220502_48_dialog_content = "Tímidos, somos? Contanto que você esteja disposto, estou disposto a lhe ensinar qualquer coisa.",
  ui_story_5022_50220502_49_dialog_content = "(Tão perto!)",
  ui_story_5022_50220502_50_dialog_content = "B-A propósito, não estamos esquecendo de algo?",
  ui_story_5022_50220502_51_dialog_content = "*Cof, cof*",
  ui_story_5022_50220502_52_dialog_content = "Embora Sinsa conseguiu parar o carro, vai nos custar muito tempo para consertar todo esse estrago.",
  ui_story_5022_50220502_53_dialog_content = "Espere, você ainda não está perdendo? Seu carro está literalmente fumegando.",
  ui_story_5022_50220502_54_dialog_content = "Nunca subestime um técnico. Estou com o objetivo de fazer mechs gigantes no futuro. Consertar um carro não é nada.",
  ui_story_5022_50220502_55_dialog_content = "Além disso, a maneira como você saltou do topo daquele carro me deu uma nova inspiração!",
  ui_story_5022_50220502_56_dialog_content = "Colocar um sistema de propulsão vertical no mecha pode ser uma boa ideia...",
  ui_story_5022_50220502_57_dialog_content = "Você realmente gosta de robôs... Para ser honesto, isso soa bem legal.",
  ui_story_5022_50220502_58_dialog_content = "Mais uma coisa...",
  ui_story_5022_50220502_59_dialog_content = "O quê?",
  ui_story_5022_50220502_60_dialog_content = "Olhe para lá.",
  ui_story_5022_50220502_61_dialog_content = "<size=45>Sinsa! Vamos deixar você para trás se não se mexer!</size>",
  ui_story_5022_50220502_62_dialog_content = "Ei! Espere!",
  ui_story_5022_50220502_63_dialog_content = "Uau, ele está correndo a pé e alcançando um carro em movimento. Isso é Sinsa para você!",
  ui_story_5022_50220502_64_dialog_content = "Eu sou o homem mais rápido em Rediesel Wrench!",
  ui_story_5022_50220502_65_dialog_content = "E eu vou vencer o duelo 874 para assumir a posição de primeiro em comando!",
  ui_story_5022_50220502_66_dialog_content = "Da próxima vez, com certeza vou me exibir na frente da senhorita Azure!",
  ui_story_5022_50220502_67_dialog_content = "Hahaha! Esse é o espírito!",
  ui_story_5022_50220502_68_dialog_content = "No entanto, estamos presos no meio do deserto, então...",
  ui_story_5022_50220502_69_dialog_content = "Passe-me aquela chave de fenda verde, sim? Pense nisso como dar o primeiro passo em seu próximo duelo.",
  ui_story_5022_50220601_1_dialog_content = "Explodir o passeio de um oponente... É assim que o Blazing Rally deveria ser? Imagino como estão os três...",
  ui_story_5022_50220601_2_dialog_content = "Você está sentindo um pouco do apelo dos carros de corrida agora?",
  ui_story_5022_50220601_3_dialog_content = "Eu pensei que isso tudo era apenas um jogo bobo para você e você não estava levando isso tão a sério...",
  ui_story_5022_50220601_4_dialog_content = "Mas você está claramente se divertindo!",
  ui_story_5022_50220601_5_dialog_content = "Como dama, considero etiqueta adaptar-me ao ardor dos meus pretendentes.",
  ui_story_5022_50220601_6_dialog_content = "Você tem razão. Este é um jogo, mas não é para ser jogado.",
  ui_story_5022_50220601_7_dialog_content = "Você parecia realmente interessado nisso enquanto dirigia. Tem certeza que não quer continuar?",
  ui_story_5022_50220601_8_dialog_content = "Hã, bom...",
  ui_story_5022_50220601_9_dialog_content = "Oh, vamos lá, recuando já? Você não sabe como se divertir em tudo!",
  ui_story_5022_50220601_10_dialog_content = "No entanto, mesmo assim, você definitivamente ficará empolgado em breve. Heheh!",
  ui_story_5022_50220601_11_dialog_content = "...Como assim?",
  ui_story_5022_50220601_12_dialog_content = "Porque... ufa, isso foi perto. Vamos chegar ao estágio do vulcão em seguida.",
  ui_story_5022_50220601_13_dialog_content = "Nossa!",
  ui_story_5022_50220601_14_dialog_content = "Ah é você, Sinsa. Achei que uma pedra caída tivesse caído sobre o carro. Pessoas normais entram em carros pulando pelas janelas?",
  ui_story_5022_50220601_15_dialog_content = "Pfft, acho que você pegou.",
  ui_story_5022_50220601_16_dialog_content = "Você acabou de zombar de mim?",
  ui_story_5022_50220601_17_dialog_content = "eu não acho senhorita Azure pretendia sair Sinsa atrás...",
  ui_story_5022_50220601_18_dialog_content = "Você é muito ingênuo, ela definitivamente estava meio séria sobre isso! Ainda bem que sou um corredor rápido!",
  ui_story_5022_50220601_19_dialog_content = "Espere, por que eu sinto a atmosfera esquentando?",
  ui_story_5022_50220601_20_dialog_content = "Entramos na segunda parte do rali, o <color=#FFB400>Vulcão Sopro de Dragão</color>. Temos que passar por este vulcão.",
  ui_story_5022_50220601_21_dialog_content = "Você está brincando comigo? Que tipo de pista é essa!?",
  ui_story_5022_50220601_22_dialog_content = "Não passar pelo vulcão é o caminho mais curto para o Dente Flamejante, mas...",
  ui_story_5022_50220601_23_dialog_content = "Eu não sonharia em não deixar você se divertir quando você acabou de aprender a beleza das corridas.",
  ui_story_5022_50220601_24_dialog_content = "Somos praticamente camaradas agora, então você pode ter o volante sempre que quiser tentar.",
  ui_story_5022_50220601_25_dialog_content = "N-Não, obrigado! Ainda tenho caminhos a percorrer!",
  ui_story_5022_50220601_26_dialog_content = "Não seja tão humilde, PlayerName.",
  ui_story_5022_50220601_27_dialog_content = "Você é bom em jogos e um piloto natural. Imagine isso.",
  ui_story_5022_50220601_28_dialog_content = "(Ah, falando em jogos...)",
  ui_story_5022_50220601_29_dialog_content = "(Me pergunto como Vice está fazendo.)",
  ui_story_5022_50220601_30_dialog_content = "(Estávamos sempre juntos, experimentando todas aquelas aventuras maravilhosas e perigosas um com o outro.)",
  ui_story_5022_50220601_31_dialog_content = "(...Se ao menos ela estivesse aqui.)",
  ui_story_5022_50220601_32_dialog_content = "Ackkkk! Para para para! Desculpe, Roy!",
  ui_story_5022_50220601_33_dialog_content = "Eu saio por cinco segundos e você decide começar a falar. Você esqueceu as cláusulas adicionais que mencionei tantas vezes?",
  ui_story_5022_50220601_34_dialog_content = "Roy, vamos! Eu apenas escondi parte da verdade para melhor motivá-los... Ai! Minha orelha!",
  ui_story_5022_50220601_35_dialog_content = "Desculpem rapazes. Deixe-me esclarecer uma coisa: O anfitrião se reserva o direito de determinar os parâmetros do grande prêmio.",
  ui_story_5022_50220601_36_dialog_content = "Apenas um desejo pode ser concedido. Se houver divergências entre a equipe, por favor, resolvam entre vocês sem recorrer à violência.",
  ui_story_5022_50220601_37_dialog_content = "Espero que todos façam o seu melhor. May a vitória do melhor competidor, e quem quer que seja, recomendo ponderar cuidadosamente sobre o que você deseja.",
  ui_story_5022_50220601_38_dialog_content = "E não puxe nada, porque eu mesmo vou quebrar as pernas de qualquer trapaceiro. Todos vocês ouviram isso?",
  ui_story_5022_50220601_39_dialog_content = "N-Agora, vamos colocar todos em dia sobre como está indo a corrida.",
  ui_story_5022_50220601_40_dialog_content = "Primeiro temos Zeta, nosso Sweet Devil, o primeiro a chegar à estação de serviço ao pé do vulcão.",
  ui_story_5022_50220601_41_dialog_content = "O status do resto das equipes seguirá em breve após este pequeno comercial—",
  ui_story_5022_50220601_42_dialog_content = "Você quer saborear algo gourmet sob as flores de cerejeira...",
  ui_story_5022_50220601_43_dialog_content = "Doce Diesel! Barbara! Uau!",
  ui_story_5022_50220601_44_dialog_content = "Hum, estou ouvindo um barulho de fundo...",
  ui_story_5022_50220601_45_dialog_content = "♪ Bênçãos minhas em ventos fortuitos para você ♪",
  ui_story_5022_50220601_46_dialog_content = "Você quer experimentar... o mais supremo dos sabores?",
  ui_story_5022_50220601_47_dialog_content = "♪ Você acena com a mão para mim... Estou sempre aqui esperando... ♪",
  ui_story_5022_50220601_48_dialog_content = "Então venha experimentar... Delicioso! Kaniya Ramen!",
  ui_story_5022_50220601_49_dialog_content = "*tosse* Droga...",
  ui_story_5022_50220601_50_dialog_content = "♪ La la la! La la la! Cante comigo! ♪",
  ui_story_5022_50220601_51_dialog_content = "La la la! La la la!",
  ui_story_5022_50220601_52_dialog_content = "A música está dominando o comercial real...",
  ui_story_5022_50220601_53_dialog_content = "Ugh, tudo bem. Diesel Sweety Barbara está realizando um show de 300 músicas no comboio ao lado do Lepidoz...",
  ui_story_5022_50220601_54_dialog_content = "Como uma das equipes de entretenimento da equipe de logística, ela...",
  ui_story_5022_50220601_55_dialog_content = "Ela não se importa em como eu quase tive minhas orelhas arrancadas no estúdio agora mesmo e ela está apenas começando seu trabalho em seu horário agendado sem uma preocupação no mundo!",
  ui_story_5022_50220601_56_dialog_content = "Enfim, vamos voltar nossa atenção para este grande...",
  ui_story_5022_50220601_57_dialog_content = "Tudo acaba agora!",
  ui_story_5022_50220601_58_dialog_content = "Eca... Regina? Eu não sabia que ela estaria aqui!",
  ui_story_5022_50220601_59_dialog_content = "Jomu, você realmente suga todo mundo.",
  ui_story_5022_50220601_60_dialog_content = "A neutralidade é boa para os negócios. Importa-se de guardar essa serra?",
  ui_story_5022_50220601_61_dialog_content = "Eu não vou deixar seus gritos horríveis estragarem os ouvidos de todos, Barbara!",
  ui_story_5022_50220601_62_dialog_content = "Eu vou esmagá-lo com minha música abrasadora!",
  ui_story_5022_50220601_63_dialog_content = "Regina, você acha que eu tenho medo de você?",
  ui_story_5022_50220601_64_dialog_content = "Barbara! Barbara!",
  ui_story_5022_50220601_65_dialog_content = "Tempestade Solar! Tempestade Solar!",
  ui_story_5022_50220601_66_dialog_content = "♪ La la la! Sua sorte, minha sorte! Vamos dar as mãos! ♪",
  ui_story_5022_50220601_67_dialog_content = "Porra, ela me venceu! Gente, vamos arrasar!",
  ui_story_5022_50220601_68_dialog_content = "♪ Rugido! Rugido! Quem pode nos salvar desse impasse!? ♪",
  ui_story_5022_50220601_69_dialog_content = "Caralho! Desligue a estação! Meu cérebro está prestes a explodir!",
  ui_story_5022_50220601_70_dialog_content = "Oh, isso é tudo o que você pode aguentar, Caelestite?",
  ui_story_5022_50220601_71_dialog_content = "De acordo com os costumes do Blazing Rally, as coisas boas ainda estão por vir.",
  ui_story_5022_50220601_72_dialog_content = "Enquanto os pilotos correm para se superar, o duelo de Diesel Sweety e Solar Storm chega ao clímax!",
  ui_story_5022_50220601_73_dialog_content = "Como você pode ouvir, Diesel Sweety escolheu uma música alegre. Suas doces notas altas podem quebrar taças de vinho!",
  ui_story_5022_50220601_74_dialog_content = "Quanto ao Solar Storm, sua música está alcançando seu refrão sensacionalista!",
  ui_story_5022_50220601_75_dialog_content = "Como ela vai escolher entregar essas notas estimulantes? Vamos descobrir...",
  ui_story_5022_50220601_76_dialog_content = "Então é assim! Ela vai... vai...",
  ui_story_5022_50220601_77_dialog_content = "Solar Storm não destruiu a guitarra por um toque dramático. Em vez disso, ela jogou no chão!",
  ui_story_5022_50220601_78_dialog_content = "Solar Storm deixou o palco!",
  ui_story_5022_50220601_79_dialog_content = "Tempestade Solar... Ela saltou para o troféu que obteve na perseguição a Lumopolis! Um dirigível!",
  ui_story_5022_50220601_80_dialog_content = "Solar Storm pegou o dirigível... e está indo para a parede de pedra!",
  ui_story_5022_50220601_81_dialog_content = "Hmph! Pudim frito! <size=45>Tenha um gosto de música real!</size>",
  ui_story_5022_50220601_82_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5022_50220601_83_dialog_content = "Uma explosão?!",
  ui_story_5022_50220601_84_dialog_content = "Onde está o Lepidoz? Não deveria nos afetar...",
  ui_story_5022_50220601_85_dialog_content = "<color=#e8d9bb>Ah... Ah!</color>",
  ui_story_5022_50220601_86_dialog_content = "Bem, isso não é uma coisa certa a dizer.",
  ui_story_5022_50220601_87_dialog_content = "Que som é esse?",
  ui_story_5022_50220601_88_dialog_content = "A... a parede do penhasco à esquerda está desmoronando!",
  ui_story_5022_50220601_89_dialog_content = "Fique calmo. Apenas fique à frente do colapso e ficaremos bem.",
  ui_story_5022_50220601_90_dialog_content = "Porque você está assustado? Ainda é seguro à direita, não é?",
  ui_story_5022_50220601_91_dialog_content = "Mas já estamos a todo vapor, e posso sentir...",
  ui_story_5022_50220601_92_dialog_content = "Está cheio de Eclipses por lá!",
  ui_story_5022_50220602_1_dialog_content = "Ei. Já pode abrir os olhos. PlayerName?",
  ui_story_5022_50220602_2_dialog_content = "O que deveríamos fazer? Parece que você está um pouco em estado de choque.",
  ui_story_5022_50220602_3_dialog_content = "Você ainda está muito verde. Você vai se acostumar com isso quando você experimentar mais.",
  ui_story_5022_50220602_4_dialog_content = "...Sem brincadeiras!",
  ui_story_5022_50220602_5_dialog_content = "Aqui vamos nós! Mas não fizemos nada. Que milagre médico!",
  ui_story_5022_50220602_6_dialog_content = "Mais disto? É um milagre eu não estar morto!",
  ui_story_5022_50220602_7_dialog_content = "Algo tão pequeno dificilmente é um milagre.",
  ui_story_5022_50220602_8_dialog_content = "Vou explicar, já que reservo um pouco de paciência para fofuras.",
  ui_story_5022_50220602_9_dialog_content = "Abra os olhos e olhe para a estrada com cuidado. Este lado é o penhasco, e aquele lado é a parede de pedra.",
  ui_story_5022_50220602_10_dialog_content = "Direita. Eu vejo.",
  ui_story_5022_50220602_11_dialog_content = "Este lugar está perto da borda da Noite Eterna. Os Eclipsitos costumam se esconder na sombra da parede rochosa para minimizar os custos de energia.",
  ui_story_5022_50220602_12_dialog_content = "Ah, isso faz sentido.",
  ui_story_5022_50220602_13_dialog_content = "Ou seja, desde que encontremos o ângulo certo, podemos usar Eclipsites como almofadas de impacto.",
  ui_story_5022_50220602_14_dialog_content = "Agora eu entendo...",
  ui_story_5022_50220602_15_dialog_content = "NÃO!",
  ui_story_5022_50220602_16_dialog_content = "Usar Eclipsites como almofadas está além do senso comum!",
  ui_story_5022_50220602_17_dialog_content = "PlayerName, não pense. Sinta, sinta com o coração.",
  ui_story_5022_50220602_18_dialog_content = "Isso mesmo! E confie na senhorita Azure, ela tem isso!",
  ui_story_5022_50220602_19_dialog_content = "Ugh... Eu sou o único questionando as coisas... Isso é tão ruim...",
  ui_story_5022_50220602_20_dialog_content = "Vice...",
  ui_story_5022_50220602_21_dialog_content = "Vice... Preciso de você aqui...",
  ui_story_5022_50220602_22_dialog_content = "(Se eu tivesse me desculpado com ela naquela época...)",
  ui_story_5022_50220602_23_dialog_content = "<color=#e8d9bb>Barulho... Barulho...</color>",
  ui_story_5022_50220602_24_dialog_content = "Celestita? Celestita? Você está aí?",
  ui_story_5022_50220602_25_dialog_content = "De novo?!",
  ui_story_5022_50220602_26_dialog_content = "O-o que aconteceu com você? Você comeu alguma coisa suja do chão? Ou o calor fritou seu cérebro?",
  ui_story_5022_50220602_27_dialog_content = "Hum, quero dizer... e aí, Zeta?",
  ui_story_5022_50220602_28_dialog_content = "E aí? Você é lento. Muito devagar! Vocês ainda estão perto do vulcão?",
  ui_story_5022_50220602_29_dialog_content = "Esta não é uma luta digna! É um lado obliterando o outro!",
  ui_story_5022_50220602_30_dialog_content = "Então eu presumo que a senhorita Sweet Devil já alcançou a linha de chegada?",
  ui_story_5022_50220602_31_dialog_content = "Hehehe, já saí do Lago Magma. Não esperava isso, não é!?",
  ui_story_5022_50220602_32_dialog_content = "Eu também obtive o Amuleto de Gelo para resistir ao calor de Tiny One, o mestre de armas dos guerreiros, no posto de gasolina!",
  ui_story_5022_50220602_33_dialog_content = "*suspira*",
  ui_story_5022_50220602_34_dialog_content = "O que é esse som...?",
  ui_story_5022_50220602_35_dialog_content = "Miss Sweet Devil é tão impressionante que me faz tremer positivamente!",
  ui_story_5022_50220602_36_dialog_content = "Fingir que você não se importa não vai funcionar. Eu sou um piloto também, você não pode me enganar. Você deve estar ansioso para me alcançar.",
  ui_story_5022_50220602_37_dialog_content = "Infelizmente, você esteve fora do jogo por muito tempo e perdeu sua vantagem!",
  ui_story_5022_50220602_38_dialog_content = "Mais importante, o medo da morte e da derrota o devorou de dentro para fora!",
  ui_story_5022_50220602_39_dialog_content = "O piloto em você queimou, nem mesmo as cinzas permanecem!",
  ui_story_5022_50220602_40_dialog_content = "Eu serei o único a derrotar o dragão perverso. Eu serei o campeão da corrida também!",
  ui_story_5022_50220602_41_dialog_content = "Testemunhe minha vitória!",
  ui_story_5022_50220602_42_dialog_content = "Impressionante, eu não gaguejei uma vez e não pulei nenhuma linha...!",
  ui_story_5022_50220602_43_dialog_content = "...Você deve verificar se suas comunicações estão desligadas antes de sair do personagem...",
  ui_story_5022_50220602_44_dialog_content = "Huh, ela deve ter praticado dizer isso diante de um espelho. A entrega foi muito mais suave do que sua provocação da última vez.",
  ui_story_5022_50220602_45_dialog_content = "Sinsa também correu contra Zeta antes?",
  ui_story_5022_50220602_46_dialog_content = "Ela ficou em segundo lugar da última vez e me desafiou no palco.",
  ui_story_5022_50220602_47_dialog_content = "Eu realmente não entendi o que ela estava dizendo porque ela estava tendo um colapso.",
  ui_story_5022_50220602_48_dialog_content = "Felizmente para mim, Roy puxou ela de cima de mim...",
  ui_story_5022_50220602_49_dialog_content = "Ainda assim, isso foi uma zombaria bastante brutal... Mesmo Azure não teve retorno.",
  ui_story_5022_50220602_50_dialog_content = "Perder Azure...?",
  ui_story_5022_50220602_51_dialog_content = "A batalha de músicas de Solar Storm e Diesel Sweety foi momentaneamente interrompida.",
  ui_story_5022_50220602_52_dialog_content = "Agora, vamos voltar nossa atenção para a corrida.",
  ui_story_5022_50220602_53_dialog_content = "Estou animado em anunciar que os competidores que alcançaram o Vulcão Dragon Breath, a segunda etapa da corrida...",
  ui_story_5022_50220602_54_dialog_content = "<size=45>É poucos em números!</size>",
  ui_story_5022_50220602_55_dialog_content = "OK tudo bem. Isso não é algo que vale a pena gritar. O que realmente vale a pena mencionar é que...",
  ui_story_5022_50220602_56_dialog_content = "Alguns competidores ficaram tão atraídos pelos comerciais de Kaniya Ramen e Octobro Shaved Ice que desistiram do jogo para satisfazer suas barrigas!",
  ui_story_5022_50220602_57_dialog_content = "Ah, não precisa se decepcionar!",
  ui_story_5022_50220602_58_dialog_content = "Registros anteriores indicam que apenas os melhores conseguem atravessar o Deserto do Ar Quente.",
  ui_story_5022_50220602_59_dialog_content = "Os competidores precisam navegar pelo ambiente hostil e pela cooperação da equipe, que são desafios incríveis por conta própria.",
  ui_story_5022_50220602_60_dialog_content = "Você ainda se lembra de como descobrimos essa rota incrível puramente por acidente porque nos perdemos?",
  ui_story_5022_50220602_61_dialog_content = "Eu realmente pensei que ia morrer durante a operação de busca e salvamento! Hahaha!",
  ui_story_5022_50220602_62_dialog_content = "Lembro que alguém sugeriu usar algumas tábuas de sucata retiradas dos carros para deslizar pela queda de magma...",
  ui_story_5022_50220602_63_dialog_content = "Magma cai!?",
  ui_story_5022_50220602_64_dialog_content = "Hum... Não. Não consigo lembrar. Mas também havia um competidor que tentou congelar todo o Lago Magma...",
  ui_story_5022_50220602_65_dialog_content = "E um competidor que cortou o carro de um oponente em seis pedaços com uma faca, mas de alguma forma o motorista saiu apenas com o ego machucado...",
  ui_story_5022_50220602_66_dialog_content = "Infelizmente, esses dois concorrentes usaram nomes falsos e raramente participam.",
  ui_story_5022_50220602_67_dialog_content = "Oh, como gostaríamos de vê-los novamente, mas eu discordo.",
  ui_story_5022_50220602_68_dialog_content = "Também notamos um aumento incomum na atividade de Eclipsites desta vez.",
  ui_story_5022_50220602_69_dialog_content = "Eclipsites regulares não representam uma ameaça para nossos pilotos experientes...",
  ui_story_5022_50220602_70_dialog_content = "Mas! The Wicked Dragon Hakudoma é uma história diferente!",
  ui_story_5022_50220602_71_dialog_content = "Se realmente aparecer, deveríamos lançar alguns souvenirs de edição limitada do Wicked Dragon para lucrar!",
  ui_story_5022_50220602_72_dialog_content = "Por que alguém iria querer isso...?",
  ui_story_5022_50220602_73_dialog_content = "Odi da Logística Equipe 3 está monitorando a região atual através da rede de comunicação pré-instalada no Lepidoz.",
  ui_story_5022_50220602_74_dialog_content = "Até agora, não há sinais de grandes Eclipsitos.",
  ui_story_5022_50220602_75_dialog_content = "Que reconfortante, mas decepcionante! Agora, um pequeno intervalo comercial! Crunchy Munchy Crunch, um pacote serve três refeições...",
  ui_story_5022_50220602_76_dialog_content = "...Não?",
  ui_story_5022_50220602_77_dialog_content = "(Porque Azure parece meio... desapontado?)",
  ui_story_5022_50220602_78_dialog_content = "Perder Azure, você está esperando que Wicked Dragon Hakudoma apareça?",
  ui_story_5022_50220602_79_dialog_content = "É tão óbvio?",
  ui_story_5022_50220602_80_dialog_content = "Caelestite, você faria bem em não pegar meu cérebro.",
  ui_story_5022_50220602_81_dialog_content = "No entanto, já que você se saiu muito bem quando estávamos lutando contra os outros competidores... Eu vou te agradar só dessa vez.",
  ui_story_5022_50220602_82_dialog_content = "Esta faixa em particular significa algo especial para mim.",
  ui_story_5022_50220602_83_dialog_content = "Foi aqui que aprendi a conduzir e participei no meu primeiro Blazing Rally, onde estabeleci novos recordes vezes sem conta.",
  ui_story_5022_50220602_84_dialog_content = "Minhas melhores e piores lembranças vivem neste lugar.",
  ui_story_5022_50220602_85_dialog_content = "Eu experimentei meu pior fracasso aqui e fiz um inimigo que jurei matar.",
  ui_story_5022_50220602_86_dialog_content = "Um dia, vou quebrar seu crânio, esmagar sua espinha e transformá-lo em cinzas sob meus pés.",
  ui_story_5022_50220602_87_dialog_content = "Eu esperava que hoje seria o dia.",
  ui_story_5022_50220602_88_dialog_content = "Não pode simplesmente morrer e desaparecer antes que eu tenha a chance de arrancar suas entranhas.",
  ui_story_5022_50220602_89_dialog_content = "Que? Eu assustei você?",
  ui_story_5022_50220602_90_dialog_content = "Em vez...",
  ui_story_5022_50220602_91_dialog_content = "É mais que eu finalmente vejo um vislumbre de seu verdadeiro caráter.",
  ui_story_5022_50220602_92_dialog_content = "Você pode ser burro e covarde, mas com certeza sabe como agradar.",
  ui_story_5022_50220602_93_dialog_content = "Quantos corações você derreteu com essas palavras floridas?",
  ui_story_5022_50220602_94_dialog_content = "Eu só estava dizendo a verdade...",
  ui_story_5022_50220602_95_dialog_content = "Mas, por que você insiste tanto em lutar contra esse Eclipsite em particular?",
  ui_story_5022_50220602_96_dialog_content = "Você realmente gosta de uma história, não é, Caelestite?",
  ui_story_5022_50220602_97_dialog_content = "Quer dizer, ele se foi há mais de uma década.",
  ui_story_5022_50220602_98_dialog_content = "Talvez eu devesse me preocupar mais com as exigências malucas que Zeta fará se vencer.",
  ui_story_5022_50220602_99_dialog_content = "Ela pode fazer isso? Isso faz parte do duelo?",
  ui_story_5022_50220602_100_dialog_content = "É com Zeta que estamos lidando aqui. Ela não vai facilitar as coisas para você.",
  ui_story_5022_50220602_101_dialog_content = "Ei, Caelestite, não diga isso como se não tivesse nada a ver com você.",
  ui_story_5022_50220602_102_dialog_content = "Somos companheiros. Aconteça o que acontecer, enfrentaremos tudo juntos, não é?",
  ui_story_5022_50220602_103_dialog_content = "Hã?",
  ui_story_5022_50220602_104_dialog_content = "Acho que esta é a minha parada aqui...",
  ui_story_5022_50220602_105_dialog_content = "Ah. Não entre em pânico ainda.|\nO jogo acabou de começar.",
  ui_story_5022_50220802_1_dialog_content = "Finalmente, a estação de manutenção! Estou exausto, todos aqueles Eclipsites foram uma verdadeira dor...",
  ui_story_5022_50220802_2_dialog_content = "Perder Azure, você está finalmente aqui! Estacione seu carro aqui, por favor...",
  ui_story_5022_50220802_3_dialog_content = "Você, verifique se há peças que precisam ser substituídas!",
  ui_story_5022_50220802_4_dialog_content = "Quanto aos pneus... Você! Isso mesmo, você! Tire os pneus!",
  ui_story_5022_50220802_5_dialog_content = "E você, levante suas bundas e vá em frente!",
  ui_story_5022_50220802_6_dialog_content = "Sim, senhor!",
  ui_story_5022_50220802_7_dialog_content = "Bem feito, Tiny One. Você sabe como fazer as coisas.",
  ui_story_5022_50220802_8_dialog_content = "Hehehe.",
  ui_story_5022_50220802_9_dialog_content = "É uma pena que sua altura não corresponda à sua autoridade...",
  ui_story_5022_50220802_9X1_dialog_content = "<size=45>Ei ei! Pare com isso!</size>",
  ui_story_5022_50220802_10_dialog_content = "Por que você não para de comentar sobre minha altura e...",
  ui_story_5022_50220802_11_dialog_content = "Huh? PlayerName? Nunca pensei que veria você até aqui.",
  ui_story_5022_50220802_12_dialog_content = "Alguém tão fraco como você chegando tão longe... Estou impressionado.",
  ui_story_5022_50220802_13_dialog_content = "Isso não soa como um elogio...",
  ui_story_5022_50220802_14_dialog_content = "Não, espere. O que eu quis dizer é que você é muito baixo para sair por aí chamando as pessoas de fracas.",
  ui_story_5022_50220802_14X1_dialog_content = "<size=45>Ei! Pare com isso!</size>",
  ui_story_5022_50220802_15_dialog_content = "Ok, isso é o suficiente disso. O Magma Lake Life Enders está chegando. Essas curvas são a parte mais difícil da pista. Você está pronto para eles?",
  ui_story_5022_50220802_16_dialog_content = "Ai! Espere... Por que se chama Lago Magma?",
  ui_story_5022_50220802_17_dialog_content = "É apenas o que parece. Um lago de magma derretido.",
  ui_story_5022_50220802_18_dialog_content = "Quero dizer, essa parte era meio óbvia...",
  ui_story_5022_50220802_S18_dialog_content = "Ok, ok, estou ouvindo! Não me bata!",
  ui_story_5022_50220802_19_dialog_content = "A temperatura do magma é alta o suficiente para vaporizá-lo completamente se você cair nele.",
  ui_story_5022_50220802_20_dialog_content = "O apresentador forneceu aos competidores equipamentos para combater o calor e a fumaça tóxica, mas você ainda sentirá que está cuspindo fogo.",
  ui_story_5022_50220802_21_dialog_content = "Então... como vamos superar isso?",
  ui_story_5022_50220802_22_dialog_content = "Já está com medo? Você realmente não tem esperança... Aqui, pegue este saco de geléia de cacto.",
  ui_story_5022_50220802_23_dialog_content = "Então isso pode me ajudar a combater o calor? As plantas do deserto são incríveis...",
  ui_story_5022_50220802_24_dialog_content = "Nada do tipo.",
  ui_story_5022_50220802_25_dialog_content = "Hã?",
  ui_story_5022_50220802_26_dialog_content = "Só tem um gosto bom. Isso é tudo.",
  ui_story_5022_50220802_27_dialog_content = "Agora, vamos ouvir os relatos das equipes!",
  ui_story_5022_50220802_28_dialog_content = "Eu gostaria de poder chamar um intervalo comercial, mas nós simplesmente não temos tantos patrocinadores... Eu até comercializei meus próprios produtos...",
  ui_story_5022_50220802_29_dialog_content = "*suspira*",
  ui_story_5022_50220802_30_dialog_content = "Sweet Devil ainda tem a liderança. Azure, o vice-campeão, ainda está a alguma distância!",
  ui_story_5022_50220802_31_dialog_content = "Fogo Polar, Equipe Kafka, e outros competidores eliminados foram recolhidos pelo Lepidoz e estão passando por reparos.",
  ui_story_5022_50220802_32_dialog_content = "Se eu perdi alguém, a culpa é sua por ser tão difícil de encontrar. Tente mais!",
  ui_story_5022_50220802_33_dialog_content = "Cuspa o sangue e continue! Eu sei que você consegue! Não pare!",
  ui_story_5022_50220802_34_dialog_content = "Dando um excelente exemplo para o resto de vocês, My Super Dream Team foi reparado por Fleur e está de volta ao jogo!",
  ui_story_5022_50220802_35_dialog_content = "Se você não pode consertar seus passeios, por favor, espere para ser resgatado por Chainsaw Rick e Rabbie!",
  ui_story_5022_50220802_36_dialog_content = "Se nada mais, podemos pelo menos ajudá-lo a desenterrar os destroços da areia, então você não precisa se preocupar!",
  ui_story_5022_50220802_37_dialog_content = "(Tudo bem... Tem um gosto bom. Mas não vai combater o calor e não é Amulet of Frost...)",
  ui_story_5022_50220802_38_dialog_content = "Zeta é imparável nesta corrida. Ela demonstrou como é uma ótima motorista.",
  ui_story_5022_50220802_39_dialog_content = "Ela estudou o Dente Ardente cuidadosamente com antecedência, o que também a ajudou tremendamente!",
  ui_story_5022_50220802_40_dialog_content = "(Vou levar alguns de volta como lembrança para todos no Colossus.)",
  ui_story_5022_50220802_41_dialog_content = "O resultado desta corrida parece imutável... Hã? Perder Odi? O que está errado?",
  ui_story_5022_50220802_42_dialog_content = "<color=#e8d9bb>Barulho... Barulho...</color>",
  ui_story_5022_50220802_43_dialog_content = "Isso é Odi, superintendente de comunicações na Equipe de Logística 3.",
  ui_story_5022_50220802_44_dialog_content = "Todos, ouçam.",
  ui_story_5022_50220802_45_dialog_content = "Temos problemas.",
  ui_story_5022_50220901_1_dialog_content = "Detectamos um grande número de Eclipsitos entre o Vulcão Sopro do Dragão e Dente Flamejante.",
  ui_story_5022_50220901_2_dialog_content = "Eles estão levantando muita areia e poeira, o que os torna difíceis de rastrear...",
  ui_story_5022_50220901_3_dialog_content = "Mas depois de verificar a velocidade e o tamanho de um deles em relação aos registros históricos, acreditamos que estamos lidando com um Eclipsite do tipo Dragão.",
  ui_story_5022_50220901_4_dialog_content = "Está se movendo pela pista, mas estamos com dificuldade de entrar em contato com Zeta por causa da areia e poeira...",
  ui_story_5022_50220901_5_dialog_content = "Vou tentar restabelecer as comunicações com o pessoal da área. Vou mantê-lo atualizado sobre quaisquer desenvolvimentos.",
  ui_story_5022_50220901_6_dialog_content = "Cuidado lá fora, seus idiotas!",
  ui_story_5022_50220901_7_dialog_content = "É... Parece que um convidado surpresa apareceu durante as etapas finais do rali!",
  ui_story_5022_50220901_8_dialog_content = "É o lendário Eclipsite, o Wicked...",
  ui_story_5022_50220901_9_dialog_content = "Isto é uma emergência! Estou assumindo o comando!",
  ui_story_5022_50220901_10_dialog_content = "Atualmente, Zeta tem apenas um caminho pelo cânion à sua frente. Os Eclipsites provavelmente a alcançarão.",
  ui_story_5022_50220901_11_dialog_content = "...!!",
  ui_story_5022_50220901_12_dialog_content = "Ela não será capaz de lidar com eles sozinha. No entanto, esse garoto é um dos nossos melhores...",
  ui_story_5022_50220901_13_dialog_content = "Então, embora ela fique aterrorizada, ela deve ser capaz de aguentar um pouco.",
  ui_story_5022_50220901_14_dialog_content = "Os membros da equipe de logística na área de Blazing Tooth serão enviados para suporte imediato.",
  ui_story_5022_50220901_15_dialog_content = "Vamos precisar de tempo para chegar lá em veículos regulares. Azure, você é o competidor mais próximo. Contamos com você.",
  ui_story_5022_50220901_16_dialog_content = "Assim que o Lepidoz chegar à área de comunicação, designarei equipes para enfrentar os Eclipsites. Aguardem outros pedidos.",
  ui_story_5022_50220901_17_dialog_content = "Roy parece tão calmo... Mas a situação está ruim, não está?",
  ui_story_5022_50220901_18_dialog_content = "Tiny One, você pode calcular a posição de Zeta com base em quando ela saiu do posto de gasolina?",
  ui_story_5022_50220901_19_dialog_content = "A julgar pela velocidade que ela estava indo, ela deveria estar bem perto da entrada do cânion.",
  ui_story_5022_50220901_20_dialog_content = "Vai demorar um pouco para chegar lá. Até você terá que desacelerar passando pelo Magma Lake Life Enders...",
  ui_story_5022_50220901_21_dialog_content = "Claro que não chegaremos a tempo pela rota regular.",
  ui_story_5022_50220901_22_dialog_content = "Droga, se eu tivesse seguido minha rota de patrulha ao longo do sopé do vulcão em vez da trilha...",
  ui_story_5022_50220901_23_dialog_content = "Bem, não há tempo para remorsos agora...",
  ui_story_5022_50220901_24_dialog_content = "Caelestite, já que você pode ver o fluxo de luz, você provavelmente pode criar uma rede sensorial com vários aurorianos, certo? Como você fez durante a batalha anterior?",
  ui_story_5022_50220901_25_dialog_content = "Claro... mas não vejo como isso nos ajudará a contornar o Lago Magma...",
  ui_story_5022_50220901_26_dialog_content = "Ah, eu acho que vai.",
  ui_story_5022_50220901_27_dialog_content = "Encontrei uma rota que vai acabar com você.",
  ui_story_5022_50220901_28_dialog_content = "Você está pronto, Celestita?",
  ui_story_5022_50220901_S28_dialog_content = "Eu acho, mas...",
  ui_story_5022_50220901_29_dialog_content = "Quantas vezes eu vi minha vida passar diante dos meus olhos agora...?",
  ui_story_5022_50220901_30_dialog_content = "Vou a todo vapor até o topo.",
  ui_story_5022_50220901_31_dialog_content = "Não há realmente nenhuma outra maneira - Ahhhhhhhhh!",
  ui_story_5022_50220901_32_dialog_content = "<anim type=Shake><size=45>E-estamos voando!</size></anim>",
  ui_story_5022_50220901_32X1_dialog_content = "(Jo-Jo-Jo-Joanie—)",
  ui_story_5022_50220901_33_dialog_content = "Sinsa, você acha que ela pensou nisso? será que vai dar certo?",
  ui_story_5022_50220901_34_dialog_content = "Em teoria, sim. A matemática é boa, mas...",
  ui_story_5022_50220901_35_dialog_content = "Chutando bombas para o ar, atirando nelas e usando as explosões para impulsionar o carro pelo Lago Magma?",
  ui_story_5022_50220901_36_dialog_content = "É ridículo por qualquer padrão!",
  ui_story_5022_50220901_37_dialog_content = "Olá, sou Azure e PlayerName estamos falando aqui. Vai funcionar!",
  ui_story_5022_50220901_38_dialog_content = "Ali estão eles! Olhe ali, acima do Lago Magma! Sheesh, eles são realmente altos, não são!",
  ui_story_5022_50220901_39_dialog_content = "Hehehe, esse plano é tão divertido que não pode falhar!",
  ui_story_5022_50220901_40_dialog_content = "Só porque você está se divertindo, você não precisa annpungar para todo mundo!",
  ui_story_5022_50220901_41_dialog_content = "Pare de me encarar! Se algo acontecer com eles, eu serei o primeiro a resgatá-los!",
  ui_story_5022_50220901_42_dialog_content = "Esperar! PlayerName está falando comigo telepaticamente!",
  ui_story_5022_50220901_43_dialog_content = "Rebatedor, a bola de beisebol... Não, a chave inglesa está pronta? Eu vou jogar as bombas!",
  ui_story_5022_50220901_44_dialog_content = "Eu tenho isso!",
  ui_story_5022_50220901_45_dialog_content = "(Agora Sinsa! Mova-o para o local que marquei—)",
  ui_story_5022_50220901_46_dialog_content = "Tudo bem, bombas de distância!",
  ui_story_5022_50220901_47_dialog_content = "bomba chegando, Azure! Preparar-",
  ui_story_5022_50220901_47X1_dialog_content = "<size=45>Incêndio!!</size>",
  ui_story_5022_50220901_47X2_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5022_50220901_48_dialog_content = "<color=#e8d9bb>BUM!</color>",
  ui_story_5022_50220901_49_dialog_content = "Funcionou! Só mais algumas vezes...",
  ui_story_5022_50220901_50_dialog_content = "(Tenho que manter o carro equilibrado. Se me mover um pouco para a direita... Ótimo!)",
  ui_story_5022_50220901_51_dialog_content = "(Está tudo bem. Mesmo que o pior aconteça...)",
  ui_story_5022_50220901_52_dialog_content = "Aaaah!",
  ui_story_5022_50220901_53_dialog_content = "PlayerName!",
  ui_story_5022_50220901_54_dialog_content = "(Não olhe para baixo... Não olhe, não olhe, não olhe para baixo!)",
  ui_story_5022_50220901_55_dialog_content = "Ei, se você realmente quer ficar longe de mim, eu entendo, mas este não é o melhor momento.",
  ui_story_5022_50220901_56_dialog_content = "Ou você quer que eu solte?",
  ui_story_5022_50220901_57_dialog_content = "Pare de me provocar, Azure... Eram...",
  ui_story_5022_50220901_58_dialog_content = "Hum...? Na verdade, não estamos caindo tão rápido...",
  ui_story_5022_50220901_59_dialog_content = "Você vê aquelas rochas de magma flutuantes?",
  ui_story_5022_50220901_60_dialog_content = "O vulcão Dragon Breath é único porque os objetos que se aproximam dele pairam a uma curta distância acima do solo.",
  ui_story_5022_50220901_61_dialog_content = "Nossa!",
  ui_story_5022_50220901_62_dialog_content = "Bonito, não é? No entanto, embora tenhamos deixado nossos dois passageiros para trás, ainda somos muito mais pesados do que aquelas rochas.",
  ui_story_5022_50220901_63_dialog_content = "Então, se você não voltar aqui e continuar...",
  ui_story_5022_50220901_64_dialog_content = "Você deveria ter dito isso antes!",
  ui_story_5022_50220901_65_dialog_content = "Última greve!",
  ui_story_5022_50220901_66_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5022_50220901_67_dialog_content = "Oh! Você viu aquilo! Eles chegaram ao outro lado do Lago Magma!",
  ui_story_5022_50220901_68_dialog_content = "Eles realmente fizeram isso. Agora, essa é uma rota que passa pelo Lago Magma que não foi tentada antes...",
  ui_story_5022_50220901_69_dialog_content = "Não temos tempo para pensar nisso agora! Aquele eclipse de alto nível...",
  ui_story_5022_50220901_70_dialog_content = "O que você está falando? A corrida ainda não acabou!",
  ui_story_5022_50220901_71_dialog_content = "Está certo. Acabamos de adicionar uma missão de busca e resgate envolvida em um desafio de chefe com um lado da caça ao Eclipsite!",
  ui_story_5022_50220901_72_dialog_content = "Imagino como será lutar contra aquela coisa de dragão... Estou ficando animado só de pensar nisso!",
  ui_story_5022_50220901_73_dialog_content = "Tiny One! Você precisa sair dessa oficina de vez em quando, ou seu cérebro vai enferrujar!",
  ui_story_5022_50220901_74_dialog_content = "Uma festa sem convidados surpresa não é festa!",
  ui_story_5022_50220901_75_dialog_content = "Apresse-se, ou tudo que você vai conseguir são sobras!",
  ui_story_5022_50220901_76_dialog_content = "Bem... Temos veículos de reserva na estação de manutenção...",
  ui_story_5022_50220901_77_dialog_content = "Conte comigo. Alguém tem que te impedir de fazer algo estúpido.",
  ui_story_5022_50220901_78_dialog_content = "Então, o que estamos esperando!? Hora de festejar!",
  ui_story_5022_50220901_79_dialog_content = "Destino: <color=#FFB400>Dente Ardente</color>!",
  ui_story_5022_50221001_1_dialog_content = "Humph... Eu não acredito... Nós realmente conseguimos!",
  ui_story_5022_50221001_2_dialog_content = "Não há nada que me surpreenda...",
  ui_story_5022_50221001_3_dialog_content = "Não, é melhor não dar azar... Ainda estou aqui com a Redesel Wrench.",
  ui_story_5022_50221001_4_dialog_content = "Ver? Você está aprendendo, PlayerName.",
  ui_story_5022_50221001_5_dialog_content = "(Perdeu Azure apenas... usar meu nome?)",
  ui_story_5022_50221001_6_dialog_content = "(Dito isso, quando ela me agarrou acima do Lago Magma, ela também...)",
  ui_story_5022_50221001_7_dialog_content = "Por que você está sorrindo?",
  ui_story_5022_50221001_8_dialog_content = "N-Nada! Eu só estava pensando que não há como Sinsa pode competir com você quando você está dando tudo de si!",
  ui_story_5022_50221001_9_dialog_content = "Bem, você está errado. Sinsa parou meu Colossus uma vez usando apenas uma mão. Isso era alguma coisa.",
  ui_story_5022_50221001_10_dialog_content = "Eu não sei como dizer, mas... eu diria que você é um veterinário adequado de Rediesel Wrench.",
  ui_story_5022_50221001_11_dialog_content = "Eu vou aceitar isso como um elogio. Essa corrida pode ficar um pouco louca às vezes, mas com certeza é viciante, não é!?",
  ui_story_5022_50221001_12_dialog_content = "Falando nisso, você também é meio louco.",
  ui_story_5022_50221001_13_dialog_content = "Lá atrás, você contava comigo para segurá-lo enquanto você tentava equilibrar o carro, certo?",
  ui_story_5022_50221001_14_dialog_content = "Bem, essa não era a aposta mais segura. Eu não sou um jogador de equipe. E se eu não tivesse chegado até você?",
  ui_story_5022_50221001_15_dialog_content = "Você poderia.",
  ui_story_5022_50221001_16_dialog_content = "Estou acostumado a dar ordens em uma batalha, então sei dessas coisas.",
  ui_story_5022_50221001_17_dialog_content = "Mesmo que você reclame sobre as pessoas que estão no seu caminho, você sempre presta atenção aos seus companheiros de equipe e sabe exatamente o que eles estão fazendo.",
  ui_story_5022_50221001_18_dialog_content = "Você não perde nada.",
  ui_story_5022_50221001_19_dialog_content = "Você me lisonjeia, PlayerName. Eu gosto disso.",
  ui_story_5022_50221001_20_dialog_content = "Ué, que tal isso. Acho que gosto de você.",
  ui_story_5022_50221001_21_dialog_content = "Ah, er...",
  ui_story_5022_50221001_22_dialog_content = "...",
  ui_story_5022_50221001_23_dialog_content = "Ainda há um caminho a percorrer antes de chegarmos à entrada do cânion. Hora de uma história.",
  ui_story_5022_50221001_24_dialog_content = "Você quer saber o que aconteceu entre mim e aquele Eclipse, certo? Está escrito em todo o seu rosto.",
  ui_story_5022_50221001_25_dialog_content = "...",
  ui_story_5022_50221001_26_dialog_content = "Isso me derrotou. Não tive chance contra isso...",
  ui_story_5022_50221001_27_dialog_content = "Se Roy não tivesse chegado lá quando ele chegou, eu não estaria aqui agora.",
  ui_story_5022_50221001_28_dialog_content = "...!",
  ui_story_5022_50221001_29_dialog_content = "Mesmo que ele brinque sobre isso o tempo todo e conte a história para as crianças como se fosse um conto de fadas...",
  ui_story_5022_50221001_30_dialog_content = "Nós dois sabemos, o que aconteceu naquele dia nos marcou para sempre.",
  ui_story_5022_50221001_31_dialog_content = "É difícil imaginar, certo? A Rediesel Wrench escapou por pouco de uma emboscada do Eclipsite há pouco mais de uma década.",
  ui_story_5022_50221001_32_dialog_content = "Multidões de monstros tentaram contornar as linhas de defesa da Illumina através do deserto... Aquele Eclipsite era um deles.",
  ui_story_5022_50221001_33_dialog_content = "Perdi minha casa e muitos dos meus amigos nessas batalhas.",
  ui_story_5022_50221001_34_dialog_content = "E desisti do rali.",
  ui_story_5022_50221001_35_dialog_content = "Treinar para a batalha e para a sobrevivência parecia mais importante do que os jogos.",
  ui_story_5022_50221001_36_dialog_content = "Sempre fui um lobo solitário porque não confio na minha capacidade de cuidar dos meus camaradas.",
  ui_story_5022_50221001_37_dialog_content = "Patético, não é? Mas não quero sentir aquele... desamparo nunca mais.",
  ui_story_5022_50221001_38_dialog_content = "Azure…",
  ui_story_5022_50221001_39_dialog_content = "Mesmo que eu tenha realizado uma exploração perigosa após a outra, ainda me preocupo por não ser bom o suficiente.",
  ui_story_5022_50221001_40_dialog_content = "Sou bom o suficiente para lutar contra nossos inimigos e proteger as pessoas que mais importam para mim?",
  ui_story_5022_50221001_41_dialog_content = "Se eu encontrar meu antigo inimigo novamente, será realmente diferente?",
  ui_story_5022_50221001_42_dialog_content = "Assim como o rali, embora eu tenha dito que desisti dele...",
  ui_story_5022_50221001_43_dialog_content = "Eu ainda termino minhas missões cedo apenas para voltar e assistir todas as vezes...",
  ui_story_5022_50221001_44_dialog_content = "Não sou tão confiável e capaz quanto você pensa que sou. Eu sou apenas um...",
  ui_story_5022_50221001_45_dialog_content = "Apenas um amador.",
  ui_story_5022_50221001_46_dialog_content = "Você não é nada disso.",
  ui_story_5022_50221001_47_dialog_content = "Não há nada de errado em desfrutar do que você ama.",
  ui_story_5022_50221001_48_dialog_content = "Isso pode soar estranho vindo de um estranho, mas...",
  ui_story_5022_50221001_49_dialog_content = "O princípio da Rediesel Wrench não é viver a vida ao máximo?",
  ui_story_5022_50221001_50_dialog_content = "Aqueles que conheço tratariam qualquer perigo como uma chance de se divertir.",
  ui_story_5022_50221001_51_dialog_content = "Agora que você diz... quase posso ver o rosto de Joanie radiante de excitação.",
  ui_story_5022_50221001_52_dialog_content = "E assim como eu e meus amigos confiamos um no outro, a Rediesel Wrench nunca deixaria você enfrentar seu inimigo sozinho.",
  ui_story_5022_50221001_53_dialog_content = "Quero dizer... Obviamente agora sou só eu, mas...",
  ui_story_5022_50221001_54_dialog_content = "Vou ajudá-lo no que puder, mesmo não sabendo usar Luminatics.",
  ui_story_5022_50221001_55_dialog_content = "Então, nas próximas batalhas, você pode contar comigo!",
  ui_story_5022_50221001_56_dialog_content = "PlayerName...",
  ui_story_5022_50221001_57_dialog_content = "Agora me sinto envergonhado por ter falado sobre o meu passado...",
  ui_story_5022_50221001_58_dialog_content = "Mas... eu sabia que estava de olho em você por um motivo. Voce é uma boa pessoa.",
  ui_story_5022_50221001_59_dialog_content = "Estamos quase na entrada do cânion. Zeta provavelmente está chorando como um bebê agora.",
  ui_story_5022_50221001_60_dialog_content = "Por falar nisso... Roy até fingiu ser uma princesa para as histórias de Zeta...",
  ui_story_5022_50221001_61_dialog_content = "Mas quando ela está em perigo mortal, ele acredita que ela pode se defender até chegarmos lá?",
  ui_story_5022_50221001_62_dialog_content = "Rediesel Wrench com certeza oferece um tipo selvagem de educação...",
  ui_story_5022_50221001_63_dialog_content = "É como ele disse, Zeta é um dos nossos melhores.",
  ui_story_5022_50221001_64_dialog_content = "Mas ainda não devemos fazê-la esperar muito. É melhor tirarmos esses Eclipsites e seguir em frente.",
  ui_story_5022_50221001_65_dialog_content = "Vamos mostrar a eles o que temos, PlayerName!",
  ui_story_5022_50221101_1_dialog_content = "Vê aquela massa negra de Eclipsites?",
  ui_story_5022_50221101_2_dialog_content = "Eca... Eles se movem como vermes quando estão amontoados assim. Repugnante...",
  ui_story_5022_50221101_3_dialog_content = "Vamos explodi-los bem alto! Eu estava procurando uma chance de calibrar minhas novas bombas. Mas, o dragão perverso é meu!",
  ui_story_5022_50221101_4_dialog_content = "Sem problemas. Aquele Eclipsite de alto nível não está entre eles.",
  ui_story_5022_50221101_5_dialog_content = "Deve ter seguido Zeta no desfiladeiro. É surpreendentemente rápido...",
  ui_story_5022_50221101_6_dialog_content = "O resto dos Eclipsitas parece estar se movendo em direção ao centro.",
  ui_story_5022_50221101_7_dialog_content = "Eles estão tentando desacelerar a senhorita Azure? É muito longe para dizer...",
  ui_story_5022_50221101_8_dialog_content = "<color=#e8d9bb>Craque... Craque...</color>",
  ui_story_5022_50221101_9_dialog_content = "Tiny One, você pode me ouvir?",
  ui_story_5022_50221101_10_dialog_content = "Roy! Eu te escuto! chefe Sinsa e Joanie Boom também estão aqui comigo. O que você precisa?",
  ui_story_5022_50221101_11_dialog_content = "Sinsa? Ele não deveria estar com Azure...?",
  ui_story_5022_50221101_12_dialog_content = "Esquece. É melhor assim... Você pode causar sérios estragos assim.",
  ui_story_5022_50221101_13_dialog_content = "Mova-se por trás deles, chame a atenção deles e destrua-os. precisamos dar Azure uma chance de romper.",
  ui_story_5022_50221101_14_dialog_content = "Que tal um plano, líder?",
  ui_story_5022_50221101_15_dialog_content = "Bem, deixe Azure seja o herói desta vez... Ela pode fazer esta festa - mas apenas esta!",
  ui_story_5022_50221101_16_dialog_content = "Eu sei que você já ouviu isso, e provavelmente não há nada para se preocupar com o líder estar aqui... Mas eu gostaria de lembrá-lo...",
  ui_story_5022_50221101_17_dialog_content = "Elimine os vermes da melancia primeiro para evitar picos. Proteja nosso passeio!",
  ui_story_5022_50221101_18_dialog_content = "E livre-se daqueles irritantes esfregões peludos que também podem curar outros Eclipsitas! Acabe com todos eles!",
  ui_story_5022_50221101_19_dialog_content = "Esses monstros do globo ocular que parecem ovos mal cozidos podem ser uma verdadeira dor, porque eles continuam convocando lacaios. Destrua-os assim que puder. Entendi?",
  ui_story_5022_50221101_20_dialog_content = "Err... O que mais...",
  ui_story_5022_50221101_21_dialog_content = "Mantenha distância dos Mega Punhos. E seja extremamente cauteloso com os Polvos Voadores - eles tentarão nos tirar de sincronia.",
  ui_story_5022_50221101_22_dialog_content = "... Roy, você acabou de suspirar? Corrija-me se disse algo errado.",
  ui_story_5022_50221101_23_dialog_content = "Não, não, você está fazendo um trabalho fabuloso. É que... É incrível como as crianças crescem rápido...",
  ui_story_5022_50221101_24_dialog_content = "Kafka e Sork irá acompanhá-lo em breve. Assuma o controle da batalha, líder. |\nDivirta-se.",
  ui_story_5022_50221101_25_dialog_content = "Aaaaaaahhh! Dane-se, Barbara, você arruinou meu show solo de novo!",
  ui_story_5022_50221101_26_dialog_content = "Graaaah!!",
  ui_story_5022_50221101_27_dialog_content = "Cale-se! Cair e ficar para baixo! Só Requiem!",
  ui_story_5022_50221101_28_dialog_content = "Oh? Seu concerto, não é? Desculpe-me, mas acho que todos estão aqui para mim!",
  ui_story_5022_50221101_29_dialog_content = "Preparar? Beijo doce!",
  ui_story_5022_50221101_30_dialog_content = "Oh sério? Quem na terra realmente gosta de suas canções de amor estúpidas?",
  ui_story_5022_50221101_31_dialog_content = "Eu diria que seus gritos implacáveis são um pouco mais difíceis para os ouvidos.",
  ui_story_5022_50221101_32_dialog_content = "Você está procurando uma luta?",
  ui_story_5022_50221101_33_dialog_content = "Se é isso que você quer, eu não teria coragem de dizer não!",
  ui_story_5022_50221101_34_dialog_content = "*Tosse* Desculpe interromper.",
  ui_story_5022_50221101_35_dialog_content = "Vocês dois se separaram de Lepidoz e contornaram o vulcão para atacar pelo deserto do norte. Você deve estar chegando nos Eclipsites, certo?",
  ui_story_5022_50221101_36_dialog_content = "Você é muito lento, Roy. Estamos em ação há algum tempo. Devemos queimar todos eles, certo?",
  ui_story_5022_50221101_37_dialog_content = "Psh... Eles são todos pequenos, é chato.",
  ui_story_5022_50221101_38_dialog_content = "Uma vez em uma lua azul, eu concordo com você.",
  ui_story_5022_50221101_39_dialog_content = "Mas vou completar qualquer missão que me derem, não importa quão trivial. Super ídolos têm ética de trabalho superior!",
  ui_story_5022_50221101_40_dialog_content = "Bem, sinto muito, mas manter o inimigo sob controle e impedir que mais Eclipsites inundem o cânion é realmente uma tarefa importante.",
  ui_story_5022_50221101_41_dialog_content = "Ei, como isso soa? Quem destruir mais Eclipsites pode fazer uma apresentação solo no próximo show do Fiery Support.",
  ui_story_5022_50221101_42_dialog_content = "!!!",
  ui_story_5022_50221101_43_dialog_content = "E o cantor pode escolher qualquer local, até Lepidoz ou o Oasis.",
  ui_story_5022_50221101_44_dialog_content = "Uau! Você tem certeza disso?",
  ui_story_5022_50221101_45_dialog_content = "Se eu escolher o Oasis, posso usar efeitos de luz fantásticos e sonhadores! Estou ficando animado só de pensar nisso…",
  ui_story_5022_50221101_46_dialog_content = "Emm... Mas um show em um Lepidoz comovente também é uma oportunidade rara...",
  ui_story_5022_50221101_47_dialog_content = "Ei! Regina! Não pule a arma!",
  ui_story_5022_50221101_48_dialog_content = "Ufa... Agora, o que vem a seguir...",
  ui_story_5022_50221101_49_dialog_content = "Azure, os Eclipsites estão começando a se dispersar. Nós seremos capazes de sair em breve!",
  ui_story_5022_50221101_50_dialog_content = "A ajuda veio da Chave Rediesel?",
  ui_story_5022_50221101_51_dialog_content = "Eclipsites não perderiam o interesse em nós assim. Para o inimigo se dispersar tão rápido... isso tem que ser trabalho de Roy.",
  ui_story_5022_50221101_52_dialog_content = "Hum, parece que recebemos uma mensagem.",
  ui_story_5022_50221101_53_dialog_content = "Oi...?",
  ui_story_5022_50221101_54_dialog_content = "Tchau!",
  ui_story_5022_50221101_55_dialog_content = "Wha...?",
  ui_story_5022_50221101_56_dialog_content = "Aguentar! Agora, isso é frio. E eu pensei que eu era como uma mãe para você!",
  ui_story_5022_50221101_57_dialog_content = "Vamos, você é muito velho para isso. Tenha algum respeito próprio.",
  ui_story_5022_50221101_58_dialog_content = "Tosse... Certo. Então...",
  ui_story_5022_50221101_59_dialog_content = "... Roy.",
  ui_story_5022_50221101_60_dialog_content = "Eu sei o que você vai dizer. Não se preocupe, eu mesmo já vi.",
  ui_story_5022_50221101_61_dialog_content = "A Chave Rediesel costumava temer os Eclipsitas porque foi derrotada por eles. Mas na última década, isso mudou...",
  ui_story_5022_50221101_62_dialog_content = "E eu também.",
  ui_story_5022_50221101_63_dialog_content = "Não é?",
  ui_story_5022_50221101_64_dialog_content = "Azure…",
  ui_story_5022_50221101_65_dialog_content = "A única maneira de sair dessa sombra assombrosa do passado é terminando isso sozinho.",
  ui_story_5022_50221101_66_dialog_content = "Então, se você tem algo a dizer, guarde para o meu retorno triunfante.",
  ui_story_5022_50221101_67_dialog_content = "… Eu vejo. Abrimos um caminho para você.",
  ui_story_5022_50221101_68_dialog_content = "Caçada feliz.",
  ui_story_5022_50221201_1_dialog_content = "<color=#e8d9bb>Há mais de dez anos</color>",
  ui_story_5022_50221201_2_dialog_content = "Gaar...",
  ui_story_5022_50221201_3_dialog_content = "Huff... Chiado... Isso não tem fim...",
  ui_story_5022_50221201_4_dialog_content = "Ghaaar...",
  ui_story_5022_50221201_5_dialog_content = "Parece que aquele idiota está planejando me esgotar antes de fazer seu movimento...",
  ui_story_5022_50221201_6_dialog_content = "(Retirar usando o carro claramente não vai funcionar... Mas se eu falhar, então todo mundo vai...)",
  ui_story_5022_50221201_7_dialog_content = "... O que? Diga isso de novo!",
  ui_story_5022_50221201_8_dialog_content = "Você me ouviu bem.",
  ui_story_5022_50221201_9_dialog_content = "O que quer dizer com o líder não está vindo, Roy? Olhe para mim!",
  ui_story_5022_50221201_10_dialog_content = "A crise está longe de terminar. Eles podem nos dar algum tempo com suas vidas, mas aqueles Eclipsitas que destruíram nossa base logo nos alcançarão.",
  ui_story_5022_50221201_11_dialog_content = "Um dos Eclipsites se parece com um dragão. Ele se move extremamente rápido. Vou tentar afastá-lo. Sinsa, pegar...",
  ui_story_5022_50221201_12_dialog_content = "Por que você voltou sozinho? Por que...",
  ui_story_5022_50221201_13_dialog_content = "Eu também queria ter sido eu quem morreu, Azure.",
  ui_story_5022_50221201_14_dialog_content = "Assim que passarmos por isso, você pode me bater o quanto quiser. Mas agora... Ei! Onde você está indo?",
  ui_story_5022_50221201_15_dialog_content = "(Eu disse algumas coisas bem ruins para ele lá atrás. Espero ter a chance de me desculpar...)",
  ui_story_5022_50221201_16_dialog_content = "(Eu deveria ser capaz de acertar por trás desta cobertura...)",
  ui_story_5022_50221201_17_dialog_content = "<color=#e8d9bb>Bang!!!</color>",
  ui_story_5022_50221201_18_dialog_content = "Ahh...!",
  ui_story_5022_50221201_19_dialog_content = "(Merda... Nem sequer penetrou na pele exterior!)",
  ui_story_5022_50221201_20_dialog_content = "(A arma... eu preciso pegar minha arma de volta...)",
  ui_story_5022_50221201_21_dialog_content = "Gah... Realmente dói...",
  ui_story_5022_50221201_22_dialog_content = "(Eu não posso... me mexer...)",
  ui_story_5022_50221201_23_dialog_content = "(Eu quebrei um osso quando bati na rocha mais cedo? Ou o rugido dele de alguma forma entorpeceu meus nervos?)",
  ui_story_5022_50221201_24_dialog_content = "(Concentre-se no presente. Ainda não posso desistir... não posso...)",
  ui_story_5022_50221201_25_dialog_content = "<anim type=Shake><size=45>Rugido!</size></anim>",
  ui_story_5022_50221201_26_dialog_content = "(Não... Minha consciência... Está desaparecendo...)",
  ui_story_5022_50221201_27_dialog_content = "(Os outros conseguiram escapar?)",
  ui_story_5022_50221201_28_dialog_content = "(Eu vou morrer aqui?)",
  ui_story_5022_50221201_29_dialog_content = "<color=#e8d9bb>*Rumble*</color>",
  ui_story_5022_50221201_30_dialog_content = "<size=45>Gaara, ahhhh!</size>",
  ui_story_5022_50221201_31_dialog_content = "(Isso foi... uma explosão?)",
  ui_story_5022_50221201_32_dialog_content = "Tosse... Ah-hahah... Parece que... cheguei bem na hora.",
  ui_story_5022_50221201_33_dialog_content = "Roy! Você...",
  ui_story_5022_50221201_34_dialog_content = "O que há com essa cara? Eu pensei... Hngh... Achei que você ficaria mais feliz em me ver.",
  ui_story_5022_50221201_35_dialog_content = "A situação está atualmente sob controle, mas nosso poder de fogo não consegue manter o inimigo abatido por muito tempo…",
  ui_story_5022_50221201_36_dialog_content = "Ah... Você está... *Tosse* Preocupado com isso...",
  ui_story_5022_50221201_37_dialog_content = "Ai... achei que não tinha força suficiente para te atacar...",
  ui_story_5022_50221201_38_dialog_content = "Sim, dói um pouco... Mas não é nada que uma boa noite de sono não resolva...",
  ui_story_5022_50221201_39_dialog_content = "Afinal, sou bastante sólido e resistente.",
  ui_story_5022_50221201_40_dialog_content = "Cale-se. Se você continuar falando, sua ferida...",
  ui_story_5022_50221201_41_dialog_content = "Os outros… Alcançaram a segurança. Havia algum tipo de lagarto...",
  ui_story_5022_50221201_42_dialog_content = "Mas eu mandei Sinsa para conferir... Então, não se preocupe...",
  ui_story_5022_50221201_43_dialog_content = "Dê-me mais alguns segundos... Deixe-me recuperar um pouco de força...",
  ui_story_5022_50221201_44_dialog_content = "Eu posso congelar a garra. Vai ficar quebradiço para que eu possa quebrá-lo!",
  ui_story_5022_50221201_45_dialog_content = "… Muito confiável.",
  ui_story_5022_50221201_46_dialog_content = "Não como eu, sem cérebro... O líder vai me repreender duramente, com certeza...",
  ui_story_5022_50221201_47_dialog_content = "...",
  ui_story_5022_50221201_48_dialog_content = "Ah... Não... Ele não vai... Quase esqueci... Ele já se foi...",
  ui_story_5022_50221201_49_dialog_content = "Já que nem o Eclipsite nem nós podemos nos mover no momento, eu... tosse... devo fazer uma reclamação.",
  ui_story_5022_50221201_50_dialog_content = "Você realmente acha que este é um bom momento para pregar?",
  ui_story_5022_50221201_51_dialog_content = "Não haverá nenhuma pregação. Mas quantas vezes eu já disse para você não sair por conta própria e tentar provar o quão corajoso você é?",
  ui_story_5022_50221201_52_dialog_content = "Eu te ensinei muito bem. Eu não poderia alcançá-lo em um carro se eu tentasse... Vou precisar praticar mais...",
  ui_story_5022_50221201_53_dialog_content = "O líder... ele me fez prometer manter você e a Chave Inglesa Rediesel a salvo. Aquele cara com certeza adorava mandar nas pessoas...",
  ui_story_5022_50221201_54_dialog_content = "Ele me disse... Heh... Que eu tinha que manter minha promessa por cem anos.",
  ui_story_5022_50221201_55_dialog_content = "Dói-me a cabeça só de pensar em transformar este grupo de idiotas e bandidos errantes em mestres do deserto.",
  ui_story_5022_50221201_56_dialog_content = "Claro, foram suas últimas palavras, mas... ele está pedindo muito.",
  ui_story_5022_50221201_57_dialog_content = "Então... vou precisar que você fique por aqui.",
  ui_story_5022_50221201_58_dialog_content = "Temos muito em nosso prato para morrer aqui.",
  ui_story_5022_50221201_59_dialog_content = "Você não precisa me dizer isso! Agora cale a boca, preciso me concentrar para controlar o alcance dos meus Luminatics.",
  ui_story_5022_50221201_60_dialog_content = "Hahah. Tosse... Parece que alguém descansou o suficiente.",
  ui_story_5022_50221201_61_dialog_content = "Vamos... Vá para casa.",
  ui_story_5022_50221201_62_dialog_content = "Vamos construir uma nova fortaleza... Em algum lugar com água e muitas árvores...",
  ui_story_5022_50221202_1_dialog_content = "Err... Senhorita Azure?",
  ui_story_5022_50221202_2_dialog_content = "Nada que uma boa noite de sono não resolva... Hah, ele ficou fora por mais de uma semana seguida...",
  ui_story_5022_50221202_3_dialog_content = "Quem exatamente estava tentando ser corajoso?",
  ui_story_5022_50221202_4_dialog_content = "... Perder Azure? Perder Azure?",
  ui_story_5022_50221202_5_dialog_content = "O que foi isso?",
  ui_story_5022_50221202_6_dialog_content = "Você parece distante. E você tem murmurado para si mesmo enquanto acelera... Você está bem?",
  ui_story_5022_50221202_7_dialog_content = "Eu só... Lembrei-me de algo do passado.",
  ui_story_5022_50221202_8_dialog_content = "Não se preocupe. Eu poderia dirigir esta pista com os olhos fechados.",
  ui_story_5022_50221202_8X_dialog_content = "Preferia que os mantivesse abertos...",
  ui_story_5022_50221202_9_dialog_content = "Eu posso sentir aquele Eclipse de Alto Nível. Está muito perto de nós.",
  ui_story_5022_50221202_10_dialog_content = "Seu Darkflow parece familiar. De uma forma muito inquietante…",
  ui_story_5022_50221202_11_dialog_content = "Entramos no cânion. A areia não afetará tanto nossos equipamentos de comunicação aqui... Talvez consigamos alcançar Zeta...",
  ui_story_5022_50221202_12_dialog_content = "<color=#e8d9bb>Craque... Craque...</color>",
  ui_story_5022_50221202_13_dialog_content = "Boo-hoo... Ahhhhhh!",
  ui_story_5022_50221202_14_dialog_content = "Alguém está lá? Eu preciso de ajuda...",
  ui_story_5022_50221202_15_dialog_content = "Zeta! Obrigado Senhor. Você está bem?",
  ui_story_5022_50221202_16_dialog_content = "A comunicação está de volta? Celestita! Isso é você?",
  ui_story_5022_50221202_17_dialog_content = "E-eu...",
  ui_story_5022_50221202_18_dialog_content = "Eu sou só! Uau!",
  ui_story_5022_50221202_19_dialog_content = "Isso é... muito alto.",
  ui_story_5022_50221202_20_dialog_content = "Eu sinto Muito! Eu queria... *Sniff*... Eu queria fazer amizade com todo mundo.",
  ui_story_5022_50221202_21_dialog_content = "Eu queria brincar com os outros... Eu *soluço* Só fiz confusão *cheirar* para que as pessoas me notassem...",
  ui_story_5022_50221202_22_dialog_content = "Waaah! Desculpe, Maggie... Estamos no mesmo time, mas eu preguei tantas peças em você...",
  ui_story_5022_50221202_23_dialog_content = "E e Tiny One, Kafka, Rabbie, Odi, Jomu, Clover, Chainsaw Ricke Sork...",
  ui_story_5022_50221202_24_option_content = "Isso é um monte de desculpas para fazer...",
  ui_story_5022_50221202_25_dialog_content = "Eu ainda não terminei! Há muitos mais na Chave Rediesel…",
  ui_story_5022_50221202_26_dialog_content = "Como o Feitiço Ardente, o Imperador da Tempestade, a Fênix do Crepúsculo, o Espectro da Guerra Caído... Waaah...",
  ui_story_5022_50221202_27_dialog_content = "(nunca ouvi falar dessas pessoas...)",
  ui_story_5022_50221202_28_option_content = "Zeta, acalme-se um minuto...",
  ui_story_5022_50221202_29_dialog_content = "Não!",
  ui_story_5022_50221202_30_dialog_content = "(Acho que vou deixá-la terminar...)",
  ui_story_5022_50221202_31_dialog_content = "*Soluço*... Azure...",
  ui_story_5022_50221202_32_dialog_content = "Vá em frente. Estou ouvindo.",
  ui_story_5022_50221202_33_dialog_content = "A única razão pela qual continuo causando problemas para você é porque estou com ciúmes.",
  ui_story_5022_50221202_34_dialog_content = "Você é tão bom em tudo. E Roy confia em você mais do que em qualquer outra pessoa...",
  ui_story_5022_50221202_35_dialog_content = "É por isso que eu sempre tento encontrar falhas com você...",
  ui_story_5022_50221202_36_dialog_content = "Debaixo da minha cama há uma caixa de lata. Ele contém todos os doces que colecionei ao longo dos anos.",
  ui_story_5022_50221202_37_dialog_content = "Azure... *Sniff*... Você pega e compartilha com todo mundo...",
  ui_story_5022_50221202_38_dialog_content = "Entendi. Algo mais?",
  ui_story_5022_50221202_39_dialog_content = "*Sniff* É uma armadilha, então tenha muito cuidado quando, ao removê-lo...",
  ui_story_5022_50221202_40_dialog_content = "Dê alguns doces extras para Maggie nas Canárias. E Roy porque ele sempre trabalha até tarde. E...",
  ui_story_5022_50221202_41_dialog_content = "Por favor, diga a todos que eu os amo... Waaah...",
  ui_story_5022_50221202_42_dialog_content = "Foram dezesseis lindos anos na Chave Rediesel...",
  ui_story_5022_50221202_43_dialog_content = "Por favor, não se esqueça de mim... Waaaaahhh!",
  ui_story_5022_50221202_44_dialog_content = "Você terminou?",
  ui_story_5022_50221202_45_dialog_content = "Sim...",
  ui_story_5022_50221202_46_dialog_content = "Eu não vou fazer isso.",
  ui_story_5022_50221202_47_dialog_content = "Hã?",
  ui_story_5022_50221202_48_dialog_content = "Todos esses pedidos, eles são demais. Eu não tenho tempo para isso. Melhor você fazer isso sozinho.",
  ui_story_5022_50221202_49_dialog_content = "Mas...",
  ui_story_5022_50221202_50_dialog_content = "Não se preocupe. Eu serei o herói...",
  ui_story_5022_50221202_51_dialog_content = "Na verdade, serei a vilã que, tocada pelos modos nobres do herói, abandona seus maus caminhos e volta ao caminho da virtude...",
  ui_story_5022_50221202_52_dialog_content = "Então, quando o herói enfrenta probabilidades insuperáveis, ela salta e derrota o dragão.",
  ui_story_5022_50221202_53_dialog_content = "… Eu te levo para casa, Zeta.",
  ui_story_5022_50221301_1_dialog_content = "Azure, Eu vejo isso! Lá!",
  ui_story_5022_50221301_2_dialog_content = "(Aquele Eclipsite de alto nível parece um modificado Nozard...)",
  ui_story_5022_50221301_3_dialog_content = "PlayerName, esperar pacientemente. Estou prestes a pisar no acelerador.",
  ui_story_5022_50221301_4_dialog_content = "<color=#e8d9bb>Caramba! Bang... Bang!</color>",
  ui_story_5022_50221301_5_dialog_content = "(Acabamos de passar por cima de um pequeno Eclipsite...)",
  ui_story_5022_50221301_6_dialog_content = "Isso não danifica o pára-choque dianteiro e o para-brisa?",
  ui_story_5022_50221301_7_dialog_content = "Não subestime Bullock 8. Ele não é como aqueles brinquedos que você vê na Illumina.",
  ui_story_5022_50221301_8_dialog_content = "Então pare de se preocupar com o meu carro. Pegue esses binóculos e verifique Zeta.",
  ui_story_5022_50221301_9_dialog_content = "Vejamos...",
  ui_story_5022_50221301_10_dialog_content = "O... O dragão pegou o carro dela, e Zeta ainda está lá dentro!",
  ui_story_5022_50221301_11_dialog_content = "Isso não soa bem. Precisamos nos apressar!",
  ui_story_5022_50221301_12_dialog_content = "Vamos.",
  ui_story_5022_50221301_13_dialog_content = "OK! Espere... Azure, por que estamos indo para trás?",
  ui_story_5022_50221301_14_dialog_content = "PlayerName, por mais que eu adorasse enfrentar esse Eclipsite de frente…",
  ui_story_5022_50221301_15_dialog_content = "Eu tenho um plano melhor.",
  ui_story_5022_50221301_16_dialog_content = "(Fique fora de vista e suba por pequenos caminhos até um ponto de comando na floresta...)",
  ui_story_5022_50221301_17_dialog_content = "Eu vejo. Deve ser assim que os atiradores fazem. Você realmente sabe o que está fazendo.",
  ui_story_5022_50221301_18_dialog_content = "Não poderia ter feito isso sozinho. Levaria muito mais tempo se não fosse pela sua capacidade de detectar Eclipsitos menores ao longo do caminho.",
  ui_story_5022_50221301_19_dialog_content = "… É assim que se sente trabalhar em equipe? Não muito pobre.",
  ui_story_5022_50221301_20_dialog_content = "Huh? O que é que foi isso? Deixe-me saber se eu posso ser de ajuda!",
  ui_story_5022_50221301_21_dialog_content = "Eu estava esperando você dizer isso. PlayerName, venha aqui e caia de joelhos.",
  ui_story_5022_50221301_22_dialog_content = "Espere... Isso é uma arma? Por que você está colocando isso no meu...",
  ui_story_5022_50221301_23_dialog_content = "Controle-se!",
  ui_story_5022_50221301_24_dialog_content = "… Excelente. A altura é simplesmente perfeita.",
  ui_story_5022_50221301_25_dialog_content = "Ficar parado. Não trema.",
  ui_story_5022_50221301_26_dialog_content = "Eu vou tentar...",
  ui_story_5022_50221301_27_dialog_content = "Heh... Incrível.",
  ui_story_5022_50221301_28_dialog_content = "Sonhei com esse momento milhares de vezes, mas quando imaginei nunca senti isso...",
  ui_story_5022_50221301_29_dialog_content = "Calmo.",
  ui_story_5022_50221301_30_dialog_content = "Você pode ver como o Zeta está se saindo através do seu escopo?",
  ui_story_5022_50221301_31_dialog_content = "É claro. Ela está pendurada na porta, jogando bombas...",
  ui_story_5022_50221301_32_dialog_content = "Enquanto lutava para voltar para o carro.",
  ui_story_5022_50221301_33_dialog_content = "Por que tenho a sensação de que você está se divertindo assistindo a isso...",
  ui_story_5022_50221301_34_dialog_content = "Não seja estúpido. Nós atiradores começamos nossa missão observando nossos arredores e prevendo o movimento do alvo.",
  ui_story_5022_50221301_35_dialog_content = "Mas você está certo. Eu não me importo com o show.",
  ui_story_5022_50221301_36_dialog_content = "Direção do vento, verificada. Velocidade do vento, verificada.",
  ui_story_5022_50221301_37_dialog_content = "Agora esperamos que o Eclipsite se vire e me dê seu olho…",
  ui_story_5022_50221301_38_dialog_content = "Perder Azure, já vi um Eclipsite de alto nível semelhante antes...",
  ui_story_5022_50221301_39_dialog_content = "Tivemos que explodir uma cidade subterrânea inteira de Illumina para matá-la.",
  ui_story_5022_50221301_40_dialog_content = "Você não confia em mim?",
  ui_story_5022_50221301_41_dialog_content = "... É verdade que eu não consegui matá-lo antes.",
  ui_story_5022_50221301_42_dialog_content = "Suas garras são afiadas e sua pele indestrutível.",
  ui_story_5022_50221301_43_dialog_content = "Meus amigos e eu derramamos sangue e sofremos por causa disso.",
  ui_story_5022_50221301_44_dialog_content = "Mas o passado é o passado... A Chave Rediesel não tem medo de nada.",
  ui_story_5022_50221301_45_dialog_content = "Nunca recusamos uma luta e sempre lutamos para vencer.",
  ui_story_5022_50221301_46_dialog_content = "Se não conseguirmos vencer, encontraremos uma oportunidade de nos vingar.",
  ui_story_5022_50221301_47_dialog_content = "... E essa oportunidade é agora!",
  ui_story_5022_50221301_48_dialog_content = "Bum!!",
  ui_story_5022_50221301_49_dialog_content = "!!!",
  ui_story_5022_50221301_50_dialog_content = "Funcionou? Eu vi a bala penetrar em seu olho...",
  ui_story_5022_50221301_51_dialog_content = "Não se mexa.",
  ui_story_5022_50221301_52_dialog_content = "T-Tá...",
  ui_story_5022_50221301_53_dialog_content = "... Não funcionou.",
  ui_story_5022_50221301_54_dialog_content = "O comportamento do alvo mudou, mas ainda está se movendo.",
  ui_story_5022_50221301_55_dialog_content = "No entanto, embora eu não saiba tanto sobre Eclipsites quanto Roy...",
  ui_story_5022_50221301_56_dialog_content = "Acho que perder os olhos contaria como um dia ruim para qualquer ser vivo.",
  ui_story_5022_50221301_57_dialog_content = "Heh. Ainda se movendo apesar de ter uma bala na cabeça... Mas isso só torna tudo mais interessante.",
  ui_story_5022_50221301_58_dialog_content = "<color=#e8d9bb>Bam! Bum, bum!</color>",
  ui_story_5022_50221301_59_dialog_content = "Woah, aquele flash ofuscante... E uma série de explosões... Isso foi Zeta?",
  ui_story_5022_50221301_60_dialog_content = "Sim. Ela escapou.",
  ui_story_5022_50221301_61_dialog_content = "O que fazemos agora? Recarregar a arma?",
  ui_story_5022_50221301_62_dialog_content = "Posso sentir outros Eclipses. Eles são atraídos aqui pelos tiros e explosões…",
  ui_story_5022_50221301_63_dialog_content = "Vamos, PlayerName.",
  ui_story_5022_50221301_64_dialog_content = "Vamos tirar aquela coisinha barulhenta de lá primeiro.",
  ui_story_5022_50221402_1_dialog_content = "Guaaah!",
  ui_story_5022_50221402_2_dialog_content = "Como é que ainda existem tantos Eclipsitas... Eles estão vindo do subsolo?",
  ui_story_5022_50221402_3_dialog_content = "Eles podem ter um covil em algum lugar neste desfiladeiro.",
  ui_story_5022_50221402_4_dialog_content = "Essa é uma peça importante de inteligência. No entanto, agora precisamos nos concentrar no inimigo.",
  ui_story_5022_50221402_5_dialog_content = "Ainda bem que está correndo loucamente depois de perder os olhos. Caso contrário, nunca seríamos capazes de nos juntar ao Zeta.",
  ui_story_5022_50221402_6_dialog_content = "*Soluços*... Azure...",
  ui_story_5022_50221402_7_dialog_content = "Zeta, tudo bem abraçar a pessoa que salvou sua vida.",
  ui_story_5022_50221402_8_dialog_content = "Mas não é legal deixar seu ranho em cima dela.",
  ui_story_5022_50221402_9_dialog_content = "O, o celestita então... Waaah...",
  ui_story_5022_50221402_10_option_content = "Tudo bem limpar ranho em mim?!",
  ui_story_5022_50221402_11_dialog_content = "Só mais um pouco!",
  ui_story_5022_50221402_12_dialog_content = "Eu sou, eu sou a heroína que vai salvar Astra. *Sniff* Eu não posso desistir ainda!",
  ui_story_5022_50221402_13_option_content = "Não tenha medo. Estamos aqui com você.",
  ui_story_5022_50221402_14_dialog_content = "*Soluço*",
  ui_story_5022_50221402_15_dialog_content = "Obrigado, Celestita...",
  ui_story_5022_50221402_16_dialog_content = "Estou bem agora.",
  ui_story_5022_50221402_17_dialog_content = "O Wicked Dragon Hakudoma apareceu no meio do meu confronto com Azure... É assim que o destino testa o escolhido...",
  ui_story_5022_50221402_18_dialog_content = "(Ela ainda está soluçando, mas parece estar se recuperando bem rápido...)",
  ui_story_5022_50221402_19_dialog_content = "Precisamos desgastá-lo. PlayerName, planeje uma rota.",
  ui_story_5022_50221402_20_dialog_content = "OK. Eu tenho esse.",
  ui_story_5022_50221402_21_dialog_content = "<color=#e8d9bb>Bang... Bang... Bang...</color>",
  ui_story_5022_50221402_22_dialog_content = "<color=#e8d9bb>Boom Boom Boom...</color>",
  ui_story_5022_50221402_23_dialog_content = "Bum!!",
  ui_story_5022_50221402_24_dialog_content = "(Nas operações anteriores, ela seguiu o caminho que tracei para nós, mas...)",
  ui_story_5022_50221402_25_dialog_content = "(Agora, Zeta descobriu rapidamente o padrão e está jogando bombas de doces em pontos difíceis para o dragão malvado se esquivar...)",
  ui_story_5022_50221402_26_dialog_content = "(E senhorita Azure está atirando em cada uma dessas bombas... O trabalho em equipe deles é simplesmente perfeito.)",
  ui_story_5022_50221402_27_dialog_content = "(Este Eclipse é diferente de qualquer outro que já encontrei.)",
  ui_story_5022_50221402_28_dialog_content = "Hmm... Se for semelhante a Nozard, deve ser capaz de manipular outros Eclipsites para atacar.",
  ui_story_5022_50221402_29_dialog_content = "Mas, por outro lado, parece e se move exatamente como os Vice e eu lidei no Corredor Sussurrante.",
  ui_story_5022_50221402_30_dialog_content = "Exceto que é mais resistente e com a pele mais grossa. É... É quase indestrutível.",
  ui_story_5022_50221402_31_dialog_content = "Se não podemos prever como ele vai agir e escolher seus alvos, isso pode ficar muito perigoso…",
  ui_story_5022_50221402_32_dialog_content = "PlayerName, Você tem um plano?",
  ui_story_5022_50221402_33_dialog_content = "… Parece que está seguindo um padrão quando está se esquivando de nossos ataques… Tipo…",
  ui_story_5022_50221402_34_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5022_50221402_35_dialog_content = "Pare de se distanciar, Caelestita! As garras do dragão malvado não são para decoração!",
  ui_story_5022_50221402_36_dialog_content = "Está tudo bem! Vou ficar de olho no celestita.",
  ui_story_5022_50221402_37_dialog_content = "... Eu entendi!",
  ui_story_5022_50221402_38_dialog_content = "Você me assustou! O que você descobriu?",
  ui_story_5022_50221402_39_dialog_content = "Esse núcleo vermelho.",
  ui_story_5022_50221402_40_dialog_content = "Azure, você notou isso também? Sim, está protegendo o núcleo em seu peito!",
  ui_story_5022_50221402_41_dialog_content = "Sim, acabei de confirmar com minha última foto.",
  ui_story_5022_50221402_42_dialog_content = "Desde que perdeu os olhos, tem confiado em seus instintos e na capacidade de sentir Lumina para evitar nossos golpes.",
  ui_story_5022_50221402_43_dialog_content = "Agora que temos seu ponto fraco... PlayerName! Zeta!",
  ui_story_5022_50221402_44_dialog_content = "Vamos moê-lo em pó!",
  ui_story_5022_50221501_1_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5022_50221501_2_dialog_content = "Graaoooooohhh!",
  ui_story_5022_50221501_3_dialog_content = "Embora conheçamos seu ponto fraco, o núcleo parece estar muito bem protegido. É quase impossível de quebrar.",
  ui_story_5022_50221501_4_dialog_content = "A bala da senhorita Azure não passou... O que devemos fazer?",
  ui_story_5022_50221501_5_dialog_content = "Bem... Se uma bala não funcionar, tentaremos dez. Se isso ainda não funcionar, vamos disparar uma centena deles, todos no mesmo local.",
  ui_story_5022_50221501_6_dialog_content = "Não seria muito satisfatório se o derrotássemos imediatamente.",
  ui_story_5022_50221501_7_dialog_content = "Ele... Ele está tentando escapar!",
  ui_story_5022_50221501_8_dialog_content = "Nem pense nisso!",
  ui_story_5022_50221501_9_dialog_content = "Nossos ataques feriram as asas do dragão perverso. Não será capaz de voar.",
  ui_story_5022_50221501_10_dialog_content = "Precisaremos de mais poder de fogo para limitar ainda mais seu movimento…",
  ui_story_5022_50221501_11_dialog_content = "Ó a bala!",
  ui_story_5022_50221501_12_dialog_content = "Azure, por aqui! Eu vou criar aberturas para você.",
  ui_story_5022_50221501_13_dialog_content = "Isso é Jona e os outros! Como eles chegaram tão alto? Nossa, que entrada!",
  ui_story_5022_50221501_14_dialog_content = "PlayerName, me siga. Vamos nos encontrar com eles.",
  ui_story_5022_50221501_15_dialog_content = "Ha, esta será a minha melhor performance até agora!",
  ui_story_5022_50221501_16_dialog_content = "De jeito nenhum! A última música é minha!",
  ui_story_5022_50221501_17_dialog_content = "Ah! Minha música terá transformado o inimigo em pó antes mesmo que você possa limpar a garganta!",
  ui_story_5022_50221501_18_dialog_content = "Certo, vocês dois, o palco é todo seu!",
  ui_story_5022_50221501_19_dialog_content = "Mas eu tenho que dizer, vocês dois são muito rápidos. Lepidoz e outros nem chegaram ainda.",
  ui_story_5022_50221501_20_dialog_content = "Você sabe como nosso lagarto é preguiçoso. E cresce uma atitude em viagens de longa distância.",
  ui_story_5022_50221501_21_dialog_content = "Roy sabe como persuadi-lo. Eles devem chegar aqui em breve.",
  ui_story_5022_50221501_22_dialog_content = "Bem, então eles vão perder toda a diversão de matar dragões. Agora que estou aqui, terminaremos em segundos!",
  ui_story_5022_50221501_23_dialog_content = "Hmph. Se você pode me acompanhar, isso é!",
  ui_story_5022_50221501_24_dialog_content = "Um guerreiro não permitirá que o mal escape! Agora, conte seus pecados!",
  ui_story_5022_50221501_25_dialog_content = "Mesmo se quisesse contar seus pecados, acho que ouviríamos apenas \"gaah\" e \"garr\".",
  ui_story_5022_50221501_26_dialog_content = "Está ficando quente aqui! Se você não se importa, eu dou uma batida com minha arma.",
  ui_story_5022_50221501_27_dialog_content = "Suspirar...",
  ui_story_5022_50221501_28_dialog_content = "Agora que todos estão aqui, não posso deixar de sentir que foi um pouco estúpido da minha parte tentar enfrentar o dragão sozinho.",
  ui_story_5022_50221501_29_dialog_content = "Argh...",
  ui_story_5022_50221501_30_dialog_content = "Desta vez, eu... quero dizer, nós...",
  ui_story_5022_50221501_31_dialog_content = "Não vai deixar você escapar vivo!",
  ui_story_5022_50221502_1_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5022_50221502_2_dialog_content = "<size=45>Graaaaaahhhh!</size>",
  ui_story_5022_50221502_3_dialog_content = "Acabou.",
  ui_story_5022_50221502_4_dialog_content = "Nós ganhamos? Eu usei todas as minhas bombas de doces, mas elas não pareciam fazer muito…",
  ui_story_5022_50221502_5_dialog_content = "Ufa... Nada mal, Azure. Visite o Squirming Sandworm quando encontrar tempo. É por minha conta.",
  ui_story_5022_50221502_6_dialog_content = "Parece que não haverá bis. O grande se transformou em cinzas assim que morreu.",
  ui_story_5022_50221502_7_dialog_content = "Para um show espetacular como esse, não me importo de estar na platéia pelo menos uma vez.",
  ui_story_5022_50221502_8_dialog_content = "Eles devem amarrar você e sua voz estridente aos assentos para sempre.",
  ui_story_5022_50221502_9_dialog_content = "O que você disse para mim? Estava ventando demais para ouvir.",
  ui_story_5022_50221502_10_dialog_content = "(Eles brigam e discutem, mas no fundo são muito próximos.)",
  ui_story_5022_50221502_11_dialog_content = "(Eu imagino o que Vice é até agora...)",
  ui_story_5022_50221502_12_dialog_content = "(Espere... sinto que estamos perdendo algo muito importante novamente...)",
  ui_story_5022_50221502_13_dialog_content = "<color=#e8d9bb>Bate, bate, bate...</color>",
  ui_story_5022_50221502_14_dialog_content = "Algo está se aproximando... Um carro?",
  ui_story_5022_50221502_15_dialog_content = "Ei! Por que todo mundo está saindo aqui?",
  ui_story_5022_50221502_16_dialog_content = "Aquele carro está fazendo alguns barulhos preocupantes... Mas pelo menos está se movendo.",
  ui_story_5022_50221502_17_dialog_content = "Ei todo mundo!",
  ui_story_5022_50221502_18_dialog_content = "Huh? Perdemos uma festa ou algo assim?",
  ui_story_5022_50221502_19_dialog_content = "Suspirar... Brock queria me ajudar a consertar o carro, mas quebrou o comunicador. Não recebemos nada desde...",
  ui_story_5022_50221502_20_dialog_content = "Eu lhe entreguei exatamente as chaves de fenda que você pediu!",
  ui_story_5022_50221502_21_dialog_content = "E posso dizer que você está muito orgulhoso disso...",
  ui_story_5022_50221502_22_dialog_content = "Enfim... Você não vai me vencer dessa vez, Zeta!",
  ui_story_5022_50221502_23_dialog_content = "...",
  ui_story_5022_50221502_24_dialog_content = "Esqueci que a corrida ainda continua!",
  ui_story_5022_50221502_25_dialog_content = "Bruxa do Zero Absoluto Azure!",
  ui_story_5022_50221502_26_dialog_content = "Não precisa gritar, guerreiro.",
  ui_story_5022_50221502_27_dialog_content = "Você derrotou o dragão antes que eu pudesse, mas o rally ainda não acabou!",
  ui_story_5022_50221502_28_dialog_content = "Eu... eu não vou esperar você pegar!",
  ui_story_5022_50221502_29_dialog_content = "<color=#e8d9bb>Bum... Bum! Estrondo...</color>",
  ui_story_5022_50221502_30_dialog_content = "O carro de Zeta de alguma forma sobreviveu às garras do dragão perverso…",
  ui_story_5022_50221502_31_dialog_content = "Não temos tempo para ficar parados e boquiabertos, PlayerName.",
  ui_story_5022_50221502_32_dialog_content = "Perder Azure?",
  ui_story_5022_50221502_33_dialog_content = "Você se juntaria a mim pelo resto da corrida e dirigiria comigo até o fim do mundo?",
  ui_story_5022_50221502_34_dialog_content = "É claro...",
  ui_story_5022_50221502_35_dialog_content = "Mas por que você está fazendo isso parecer estranho?",
  ui_story_5022_50221502_36_dialog_content = "Caros ouvintes, assim como comentei anteriormente durante esta emocionante batalha...",
  ui_story_5022_50221502_37_dialog_content = "Nossa!!!",
  ui_story_5022_50221502_38_dialog_content = "(Quase me esqueci desse comentarista de rádio super barulhento...)",
  ui_story_5022_50221502_39_dialog_content = "Equipe Azure e o Team Zeta deixou de lado velhas rancores e uniu forças com nossa equipe de eventos.",
  ui_story_5022_50221502_40_dialog_content = "Em uma incrível demonstração de habilidade, eles derrotaram o Wicked Dragon Hakudoma!",
  ui_story_5022_50221502_41_dialog_content = "Membros desarmados da Equipe de Logística 3 se esconderam em um canto e transmitiram toda a batalha.",
  ui_story_5022_50221502_42_dialog_content = "Não houve vítimas além do dragão, que foi bombardeado até o esquecimento. Parabéns, todos!",
  ui_story_5022_50221502_43_dialog_content = "Aposto que nossos competidores gostariam de ter ouvido meus comentários apaixonados durante a batalha!",
  ui_story_5022_50221502_44_dialog_content = "(Err... Na verdade não...)",
  ui_story_5022_50221502_45_dialog_content = "Mas não se preocupe. Eu ouço seu chamado!",
  ui_story_5022_50221502_46_dialog_content = "Vou recontar toda a história especialmente para você na festa de celebração mais tarde!",
  ui_story_5022_50221502_47_dialog_content = "Vou recontá-lo com tanto realismo e detalhes que será melhor do que entrar na batalha real. E por apenas 1.000 Nightium!",
  ui_story_5022_50221502_48_dialog_content = "Agora, nossos competidores estão de volta à competição, correndo em direção à linha de chegada no limite da Noite Eterna!",
  ui_story_5022_50221502_49_dialog_content = "Além do mais, Lepidoz finalmente se libertou da fenda e está indo na mesma direção!",
  ui_story_5022_50221502_49X_dialog_content = "Ele realmente precisa cuidar do que come...",
  ui_story_5022_50221502_50_dialog_content = "A corrida está entrando em sua fase final. Que outras surpresas nossos concorrentes têm para nós?",
  ui_story_5022_50221502_51_dialog_content = "Azure, olhar! À Frente!",
  ui_story_5022_50221502_52_dialog_content = "…Zeta! <size=45>Você não vai escapar desta vez! </size><size=40>... Você... </size><size=35>...Ah... </size><size=30>... Ai ... </size><size=25>... Ai ... </size><size=20>...</size>",
  ui_story_5022_50221502_53_dialog_content = "Er... Parece que o carro de Brock está descendo a colina...",
  ui_story_5022_50221502_54_dialog_content = "Na descida em ziguezague do Blazing Tooth, Sweet Devil e My Super Dream Team estão tendo uma batalha feroz!",
  ui_story_5022_50221502_55_dialog_content = "Zeta parecia virar à esquerda durante a curva à direita, mas na verdade ela estava se posicionando para a curva à esquerda logo depois!",
  ui_story_5022_50221502_56_dialog_content = "O resultado foi um drift absolutamente perfeito!",
  ui_story_5022_50221502_57_dialog_content = "Enganada por suas excelentes técnicas, a Powerball of My Super Dream Team saiu da estrada! Parece que vai precisar de algum trabalho de reparo sério.",
  ui_story_5022_50221502_58_dialog_content = "Enquanto isso, Azure está alcançando rapidamente...",
  ui_story_5022_50221502_59_dialog_content = "O para-brisa do carro dela está quebrado... É realmente seguro dirigir assim?",
  ui_story_5022_50221502_60_dialog_content = "Cuidado agora! Este é o Dragão de Areia, o Rainbow Chaser que você está falando!",
  ui_story_5022_50221502_61_dialog_content = "Que nome!",
  ui_story_5022_50221502_62_dialog_content = "Você está realmente acompanhando. A lenda faz jus à sua reputação...",
  ui_story_5022_50221502_63_dialog_content = "Vamos ver como você lida com isso!",
  ui_story_5022_50221502_64_dialog_content = "Uau, ela está acelerando!",
  ui_story_5022_50221502_65_dialog_content = "Você se move muito quando muda de marcha.",
  ui_story_5022_50221502_66_dialog_content = "O que... o que?",
  ui_story_5022_50221502_67_dialog_content = "Ouço. Não se distraia com os outros ou com quaisquer vantagens ou desvantagens que possa ter. Concentre-se em si mesmo.",
  ui_story_5022_50221502_68_dialog_content = "(Não consigo ver nada lá fora, mas acho que estão lado a lado!)",
  ui_story_5022_50221502_69_dialog_content = "O que você sabe? Não é como se você tivesse me batido antes...",
  ui_story_5022_50221502_70_dialog_content = "Ah. Fui bicampeão do Circuito Blazing Tooth antes mesmo de você nascer.",
  ui_story_5022_50221502_71_dialog_content = "Eu posso dizer exatamente quais truques estúpidos você está planejando fazer apenas ouvindo os comentários do rádio…",
  ui_story_5022_50221502_72_dialog_content = "... E eu sei como você planeja vencer a corrida.",
  ui_story_5022_50221502_73_dialog_content = "Você... Você tem me observado?",
  ui_story_5022_50221502_74_dialog_content = "Azure!",
  ui_story_5022_50221502_75_dialog_content = "Huh? Não gostou do que eu disse? Bem, prove que estou errado.",
  ui_story_5022_50221502_76_dialog_content = "Achei que o mais importante nessa corrida era te vencer...",
  ui_story_5022_50221502_77_dialog_content = "Mas como...",
  ui_story_5022_50221502_78_dialog_content = "Mesmo que eu não tenha derrotado você ainda...",
  ui_story_5022_50221502_79_dialog_content = "Eu me sinto feliz?",
  ui_story_5022_50221502_80_dialog_content = "Hum?",
  ui_story_5022_50221502_81_dialog_content = "Este circuito… Esta tentativa de recorde… Esta…",
  ui_story_5022_50221502_82_dialog_content = "Eu nunca fiz isso bem antes.",
  ui_story_5022_50221502_83_dialog_content = "Boo-hoo… Waaaah!",
  ui_story_5022_50221502_84_dialog_content = "Ela está chorando? Ainda bem que não há nada além de planícies de areia à frente…",
  ui_story_5022_50221502_85_dialog_content = "Heh, isso traz de volta memórias. Eu mesma já fui assim.",
  ui_story_5022_50221502_86_dialog_content = "Então percebi que vencer era menos recompensador do que trabalhar com meus rivais para forçar nossos limites.",
  ui_story_5022_50221502_87_dialog_content = "Eu tenho que admitir, você é um motorista bastante decente.",
  ui_story_5022_50221502_88_dialog_content = "Azure…",
  ui_story_5022_50221502_89_dialog_content = "No entanto, isso não significa que eu vou deixar você ganhar!",
  ui_story_5022_50221502_90_dialog_content = "Vou estabelecer um novo recorde para o Blazing Tooth.",
  ui_story_5022_50221502_91_dialog_content = "D-Não tenha tanta certeza sobre isso!",
  ui_story_5022_50221502_92_dialog_content = "Não se esqueça de compartilhar os doces que você guarda debaixo da cama e peça desculpas a todos quando perder!",
  ui_story_5022_50221502_93_dialog_content = "Esqueça que você já ouviu falar sobre isso! Sua bruxa!",
  ui_story_5022_50221502_94_dialog_content = "Ah, mas como eu poderia esquecer o pedido final de um guerreiro?",
  ui_story_5022_50221502_95_dialog_content = "Aaah! Eu não vou perder essa! Se eu te vencer, você terá que me levar em suas missões de agora em diante!",
  ui_story_5022_50221502_96_dialog_content = "(Até eu me emociono vendo essa troca...)",
  ui_story_5022_50221502_97_dialog_content = "(é isso que Sinsa chama a raça real? Acho que estou começando a entender o que ele quis dizer.)",
  ui_story_5022_50221502_98_dialog_content = "(Espere... Alguma coisa passou voando por cima?)",
  ui_story_5022_50221502_99_dialog_content = "É...",
  ui_story_5022_50221502_100_dialog_content = "Err?!?!",
  ui_story_5022_50221601_1_dialog_content = "ZzZzz... Ah!",
  ui_story_5022_50221601_2_dialog_content = "Tenho que ficar acordado para ver os pilotos cruzarem a linha de chegada…",
  ui_story_5022_50221601_3_dialog_content = "Você pode se apoiar no meu ombro se quiser dormir. E não se preocupe com a corrida.",
  ui_story_5022_50221601_4_dialog_content = "Posso não conseguir ver, mas sentirei o vento quando os carros se aproximarem.",
  ui_story_5022_50221601_5_dialog_content = "Dawn, ainda não há sinal deles? Está tão quente aqui, está me deixando com sono...",
  ui_story_5022_50221601_6_dialog_content = "Eu posso sentir uma vibração ao longe...",
  ui_story_5022_50221601_7_dialog_content = "Não, espere… Algo enorme está por vir…",
  ui_story_5022_50221601_8_dialog_content = "Do céu.",
  ui_story_5022_50221601_9_dialog_content = "Ah! Está chegando!",
  ui_story_5022_50221601_10_dialog_content = "Isso... Poderia ser...?",
  ui_story_5022_50221601_11_dialog_content = "Huh... Esta é a fita do arco-íris na linha de chegada. Por que está aqui? Alguém terminou a corrida?",
  ui_story_5022_50221601_12_dialog_content = "Esse veículo é enorme…. Não me lembro de ter visto algo assim na linha de partida.",
  ui_story_5022_50221601_13_dialog_content = "Ah... é PlayerNameé Soroz!",
  ui_story_5022_50221601_14_dialog_content = "Agora que você citou isso... Odi enviou uma mensagem dizendo que um Colossus entregou um formulário de inscrição no posto de controle no Hot Air Desert...",
  ui_story_5022_50221601_15_dialog_content = "Eu pensei que ela estava brincando.",
  ui_story_5022_50221601_16_dialog_content = "Venho por este meio anunciar que o vencedor do Blazing Rally é…",
  ui_story_5022_50221601_17_dialog_content = "<size=45>Soroz e seu piloto!</size>",
  ui_story_5022_50221601_18_dialog_content = "Agora, finalmente, prosseguiremos para a tão esperada cerimônia de premiação!",
  ui_story_5022_50221601_19_dialog_content = "O campeão de rali pode desejar Eve!",
  ui_story_5022_50221601_20_dialog_content = "A campeã, senhorita Vice, desejos de... um pacote de presente com maneiras de ensinar Sinsa uma lição!",
  ui_story_5022_50221601_21_dialog_content = "E agora?",
  ui_story_5022_50221601_22_dialog_content = "Vamos ouvir o discurso de aceitação da Miss Vice!",
  ui_story_5022_50221601_23_dialog_content = "Não deixe para trás uma nota que diz: \"Eu tenho PlayerName. Venha para o Deserto do Ar Quente se quiser vê-lo novamente...\"",
  ui_story_5022_50221601_24_dialog_content = "E então leve-o!",
  ui_story_5022_50221601_25_dialog_content = "Isso se chama sequestro!",
  ui_story_5022_50221601_26_dialog_content = "Após o discurso de aceitação, é a vez da nossa campeã Miss Vice para receber sua recompensa!",
  ui_story_5022_50221601_27_dialog_content = "Então, acho que isso significa que terei que ensinar uma lição ao meu irmão?",
  ui_story_5022_50221601_28_dialog_content = "Não, Eve, por favor...",
  ui_story_5022_50221601_29_dialog_content = "Aaaaaaargh!!",
  ui_story_5022_50221601_30_dialog_content = "Uau, eu não vi isso chegando.",
  ui_story_5022_50221601_31_dialog_content = "*Fungando* Posso aceitar que corremos para um empate, mas... De onde foi isso? Vice senhora vem?",
  ui_story_5022_50221601_32_dialog_content = "Ela tem sorte de ser amiga da Caelestita e que o rabo dela é tão legal…",
  ui_story_5022_50221601_33_dialog_content = "Caso contrário, eu já a teria desafiado para um duelo!",
  ui_story_5022_50221601_34_dialog_content = "Azure, como é que você está tão calmo? Você não está desapontado?",
  ui_story_5022_50221601_35_dialog_content = "Bem, ela não traiu, não é? Muito poucas pessoas são capazes de pilotar um Colossus. Eu diria que ela ganhou de forma justa.",
  ui_story_5022_50221601_36_dialog_content = "Além disso, é um prazer ver você pular para cima e para baixo como um pequeno gerbil irritado.",
  ui_story_5022_50221601_37_dialog_content = "O que você disse para mim?",
  ui_story_5022_50221601_38_dialog_content = "(eu nunca pensei que Vice voaria Soroz aqui...)",
  ui_story_5022_50221601_39_dialog_content = "PlayerName!",
  ui_story_5022_50221601_40_dialog_content = "Como você pôde sair com Sinsa sem me dizer?",
  ui_story_5022_50221601_41_dialog_content = "Ouvi tudo no rádio! Dirigindo um carro de corrida por um vulcão... Lutando contra um Eclipse de nove cabeças que parecia um dragão...",
  ui_story_5022_50221601_42_dialog_content = "A batalha acabou quando Soroz e eu chegamos ao desfiladeiro. Você tem ideia de como estávamos preocupados?",
  ui_story_5022_50221601_43_option_content = "Eu sinto Muito. Eu realmente sou!",
  ui_story_5022_50221601_44_dialog_content = "(Ela parece não se lembrar da nossa discussão...)",
  ui_story_5022_50221601_45_option_content = "Por favor me perdoe, Vice.",
  ui_story_5022_50221601_46_dialog_content = "Achei que você estava com raiva de mim...",
  ui_story_5022_50221601_47_dialog_content = "Prometo que sempre lhe direi aonde vou de agora em diante.",
  ui_story_5022_50221601_48_dialog_content = "Hum... Tudo bem. Eu vou te perdoar desta vez, mas só porque você parece realmente se arrepender!",
  ui_story_5022_50221601_49_dialog_content = "E para ser justo, o rali foi divertido e aquele vulcão foi espetacular.",
  ui_story_5022_50221601_50_dialog_content = "Flying Soroz pode ter dobrado um pouco as regras, mas a única regra no rali é que não há regras. Direita?",
  ui_story_5022_50221601_51_dialog_content = "Você deveria me convidar no ano que vem, eu sou um bom motorista de hovercar!",
  ui_story_5022_50221601_52_dialog_content = "Vice...",
  ui_story_5022_50221601_53_dialog_content = "Talvez devêssemos jogar juntos, isso poderia nos ajudar a ter um melhor desempenho na corrida.",
  ui_story_5022_50221601_54_dialog_content = "Vice!",
  ui_story_5022_50221601_55_dialog_content = "Óh, e PlayerName, não se esqueça do seu programa de treino. Vou lembrá-lo todos os dias como sempre!",
  ui_story_5022_50221601_56_dialog_content = "Err… eu não acho que seja…",
  ui_story_5022_50221601_57_dialog_content = "<color=#e8d9bb>Craque...</color>",
  ui_story_5022_50221601_58_dialog_content = "Ei a todos! Você está com saudades de mim?!",
  ui_story_5022_50221601_59_dialog_content = "O que foi isso?",
  ui_story_5022_50221601_60_dialog_content = "Está bem. É apenas o rádio. Também me deu um sobressalto quando a ouvi pela primeira vez.",
  ui_story_5022_50221601_61_dialog_content = "Jomu tem exibido comerciais o tempo todo. Ele nem mencionou que Soroz entrou na corrida...",
  ui_story_5022_50221601_62_dialog_content = "Aposto que alguns de nossos ouvintes devem estar reclamando que não mencionei a aparência de Vice na corrida!",
  ui_story_5022_50221601_63_dialog_content = "De fato, esta é a primeira vez que um Colossus se juntou ao Blazing Rally!",
  ui_story_5022_50221601_64_dialog_content = "Tosse… E para manter a corrida interessante, pode ser a última vez também.",
  ui_story_5022_50221601_65_dialog_content = "Eu só deixei de mencioná-lo para criar um pouco de suspense para nossos ouvintes!",
  ui_story_5022_50221601_66_dialog_content = "Obrigado por participar do nosso programa para o Blazing Rally deste ano. Até a próxima, e não se esqueça de preencher a pesquisa!",
  ui_story_5022_50221601_67_dialog_content = "Além disso, por favor, passe por minha loja. Temos…",
  ui_story_5022_50221601_68_dialog_content = "Ei, Jomu! Venha aqui. Tenho uma bacia inteira de tâmaras para você descascar.",
  ui_story_5022_50221601_69_dialog_content = "Roy, estou transmitindo!",
  ui_story_5022_50221601_70_dialog_content = "Excelente. Então diga a todos que parem de brincar e venham, a comida está pronta.",
  ui_story_5022_50221601_71_dialog_content = "Brock, não abra aquelas latas de proteína em pó. Eu não te disse... Ei, não, não jogue na boca! Fleur, pare ele!",
  ui_story_5022_50221601_72_dialog_content = "Tosse… Então, acho que todos vocês ouviram…",
  ui_story_5022_50221601_73_dialog_content = "É hora da festa de celebração!",
  ui_story_5022_50221601_74_dialog_content = "Tudo bem, vou terminar de lidar com meu irmão depois da comida.",
  ui_story_5022_50221601_75_dialog_content = "Tem mais?!",
  ui_story_5022_50221601_76_dialog_content = "Como é? Muito melhor do que antes, certo?",
  ui_story_5022_50221601_77_dialog_content = "É comestível. Normalmente, a única coisa que realmente vale a pena esperar é a sobremesa. O que estamos recebendo hoje?",
  ui_story_5022_50221601_78_dialog_content = "Pudim de Espinheiro Marinho, o seu favorito!",
  ui_story_5022_50221601_79_dialog_content = "Com purê de tâmaras? Eu gosto dele grosso e rico!",
  ui_story_5022_50221601_80_dialog_content = "Bem, isso depende se Jomu é feito descascá-los ainda.",
  ui_story_5022_50221601_81_dialog_content = "O que pensa, PlayerName? Foi um passeio muito bom, não foi?",
  ui_story_5022_50221601_82_dialog_content = "Com certeza superou minhas expectativas. Espere, o que… O que você acabou de me alimentar?!",
  ui_story_5022_50221601_83_dialog_content = "Tente. Espetinho de lagarto!",
  ui_story_5022_50221601_84_dialog_content = "Tem certeza que isso é comestível?",
  ui_story_5022_50221601_85_dialog_content = "Claro! Olhe para Azure!",
  ui_story_5022_50221601_86_dialog_content = "Eu não posso acreditar senhorita Azure está comendo isso... e de um jeito tão elegante...",
  ui_story_5022_50221601_87_dialog_content = "Isto também, PlayerName. Quer ter um gostinho?",
  ui_story_5022_50221601_88_dialog_content = "Este é o meu favorito Cascavel Assado com Queijo!",
  ui_story_5022_50221601_89_dialog_content = "Err... Obrigado, mas...",
  ui_story_5022_50221601_90_dialog_content = "Coma! Não seja tímido.",
  ui_story_5022_50221601_91_dialog_content = "Eu não estou realmente... eu... Oh...",
  ui_story_5022_50221601_92_dialog_content = "Estes são apenas os aperitivos. Ainda não chegamos aos pratos principais.",
  ui_story_5022_50221601_93_dialog_content = "Você foi levado às lágrimas por todos esses alimentos que nunca teve a sorte de experimentar antes? Pobre coisa…",
  ui_story_5022_50221601_94_dialog_content = "Por aqui. Eu tenho Ensopado de Ovo de Lagarto com Besouros!",
  ui_story_5022_50221601_95_dialog_content = "Hum! Marshmallow assado é tão gostoso! Devemos fazer isso de volta para casa também!",
  ui_story_5022_50221601_96_dialog_content = "Vice, você já teve o suficiente. Venha me ajudar...",
  ui_story_5022_50221601_97_dialog_content = "Azure?",
  ui_story_5022_50221601_98_dialog_content = "O que você está fazendo sentado aqui sozinho? A sobremesa não vai esperar por ninguém.",
  ui_story_5022_50221601_99_dialog_content = "Você conseguiu pegar alguns?",
  ui_story_5022_50221601_100_dialog_content = "É claro. Também roubei a porção da Zeta porque ela está muito ocupada exibindo sua boneca premiada.",
  ui_story_5022_50221601_101_dialog_content = "Você costumava sair logo após o comício e nunca participou de uma festa de comemoração. Agora você sabe o que perdeu todos esses anos!",
  ui_story_5022_50221601_102_dialog_content = "Huh. Não o empurre.",
  ui_story_5022_50221601_103_dialog_content = "Hahaha, nós nunca costumávamos nos deliciar com refeições e sobremesas luxuosas como essa. Chega de depender de lagartos assados para encher nossos estômagos!",
  ui_story_5022_50221601_104_dialog_content = "Acredito que mereço forçar um pouco.",
  ui_story_5022_50221601_105_dialog_content = "Você ainda tem o hábito de relembrar o passado como um velhote. Não venha correndo para mim quando os jovens começarem a se irritar com você.",
  ui_story_5022_50221601_106_dialog_content = "Uau, que frio! Por favor, ainda estou no auge da minha vida.",
  ui_story_5022_50221601_107_dialog_content = "...",
  ui_story_5022_50221601_108_dialog_content = "... Azure.",
  ui_story_5022_50221601_109_dialog_content = "Você acha que o desejo dele foi realizado?",
  ui_story_5022_50221601_110_dialog_content = "Por que você está perguntando de repente? Além disso, ninguém conhecia o ex-líder melhor do que você.",
  ui_story_5022_50221601_111_dialog_content = "Apenas me responda, por favor.",
  ui_story_5022_50221601_112_dialog_content = "...",
  ui_story_5022_50221601_113_dialog_content = "Tudo bem, deixe-me pensar.",
  ui_story_5022_50221601_114_dialog_content = "Nossa operação de coleta e eliminação de taxas de proteção está funcionando sem problemas. Estamos indo muito bem quando se trata de golpes com nossos inimigos e dentro de nossa gangue...",
  ui_story_5022_50221601_115_dialog_content = "Todos estão desfrutando dos prazeres da vida e surpreendentemente estamos todos bem alimentados e bem vestidos.",
  ui_story_5022_50221601_116_dialog_content = "Para um grupo desorganizado de pessoas que foram deixadas para trás ou abandonadas que decidiram se unir, direi que fizemos um bom trabalho.",
  ui_story_5022_50221601_117_dialog_content = "Para muitos de nós - inclusive eu - esta já é a coisa mais próxima de casa depois de tudo o que perdemos.",
  ui_story_5022_50221601_118_dialog_content = "Como ervas daninhas, uma vez fomos desenraizados, mas em uma terra estéril criamos raízes e crescemos além do controle.",
  ui_story_5022_50221601_119_dialog_content = "De nosso lugar no deserto, apagamos incêndios que os nobres nobres e poderosos não podem, e resolvemos os assuntos que estão além de seu alcance.",
  ui_story_5022_50221601_120_dialog_content = "Então eu diria que sim.",
  ui_story_5022_50221601_121_dialog_content = "... Agradeço.",
  ui_story_5022_50221601_122_dialog_content = "Apesar de nos comparar a ervas daninhas… Bem, acho que você tem razão.",
  ui_story_5022_50221601_123_dialog_content = "Vá encontrar jovens Sinsa se você quer ouvir alguém fazer poesia, isso não é comigo.",
  ui_story_5022_50221601_124_dialog_content = "Você ainda está chamando ele assim? Ele pode ser mais jovem do que nós, mas já é um líder capaz por direito próprio.",
  ui_story_5022_50221601_125_dialog_content = "Seriamente? Nosso líder capaz estava apenas choramingando para PlayerName pela fogueira.",
  ui_story_5022_50221601_126_dialog_content = "Ele estava reclamando como você ainda dá tapinhas na cabeça dele e o envergonha ao expor todos os erros bobos de quando ele era apenas um jovem gafanhoto verde.",
  ui_story_5022_50221601_127_dialog_content = "Hehe. Em suma, jovem Sinsa ainda não é tão confiável. Pelo menos suas habilidades de atuação ainda têm muito espaço para melhorias.",
  ui_story_5022_50221601_128_dialog_content = "Você o fez me seguir, não foi? Zeta me desafiou, e Sinsa e PlayerName entrou no meu carro...",
  ui_story_5022_50221601_129_dialog_content = "Não me diga que até a aparência do Colosso estava em seus cálculos?",
  ui_story_5022_50221601_130_dialog_content = "Ei, você sabe que eu não sou tão brilhante.",
  ui_story_5022_50221601_131_dialog_content = "A única coisa que eu realmente planejei era que você tivesse alguns companheiros este ano pela primeira vez.",
  ui_story_5022_50221601_132_dialog_content = "Eu queria te mostrar o quanto aqueles pequeninos e toda a Rediesel Wrench cresceram desde que você partiu sozinho.",
  ui_story_5022_50221601_133_dialog_content = "Então uma coisa levou a outra...",
  ui_story_5022_50221601_134_dialog_content = "Eu estava tão ansioso que quase vomitei quando você e o Caelestita voaram para fora do vulcão...",
  ui_story_5022_50221601_135_dialog_content = "Hum? Que estranho ouvir isso do homem que me ensinou a usar Eclipsites como almofada, e encostas de areia como cinto de aceleração, e manter minha velocidade nas curvas em declive!",
  ui_story_5022_50221601_136_dialog_content = "Ahaha. Verdadeiro…",
  ui_story_5022_50221601_137_dialog_content = "Aquele dragão foi uma surpresa total.",
  ui_story_5022_50221601_138_dialog_content = "Eu gostaria que o dragão perverso pudesse permanecer nas histórias apenas para Zeta.",
  ui_story_5022_50221601_139_dialog_content = "Embora novas experiências nos ajudem a crescer. Lesões são apenas uma parte do treinamento e um rito de passagem para os membros da Rediesel Wrench.",
  ui_story_5022_50221601_140_dialog_content = "Mas ela voltou sã e salva... Espere. Zeta poderia realmente ser a heroína escolhida?",
  ui_story_5022_50221601_141_dialog_content = "Nos contos de aventura, os pais do protagonista sempre morrem no começo, o que diz muito sobre o meu destino.",
  ui_story_5022_50221601_142_dialog_content = "Ai!",
  ui_story_5022_50221601_143_dialog_content = "Isso não é engraçado. Zeta chorava, e ela é barulhenta quando chora. Já sofri com isso duas vezes hoje.",
  ui_story_5022_50221601_144_dialog_content = "Quando vocês dois ficaram tão próximos? Nada mal... Que tal trazê-la na sua próxima missão?",
  ui_story_5022_50221601_145_dialog_content = "Nem pense nisso! Ela terá que me vencer no Blazing Tooth primeiro.",
  ui_story_5022_50221601_146_dialog_content = "Então você está no rali do ano que vem?",
  ui_story_5022_50221601_147_dialog_content = "… Hum. Eu acho.",
  ui_story_5022_50221601_148_dialog_content = "Excelente! As missões da equipe de Exploração são importantes. Mas todos nós precisamos relaxar um pouco de vez em quando e viver a vida ao máximo.",
  ui_story_5022_50221601_149_dialog_content = "Você não precisa me ensinar isso. Eu frequentemente...",
  ui_story_5022_50221601_150_dialog_content = "Encontrar com Jona beber até o estoque da taberna local antes de dirigir para a próxima cidade para beber mais? Eu realmente não posso chamar isso de um hobby saudável.",
  ui_story_5022_50221601_151_dialog_content = "Hã...",
  ui_story_5022_50221601_152_dialog_content = "É uma pequena melhoria, mas estou feliz que você está de volta aos trilhos.",
  ui_story_5022_50221601_153_dialog_content = "Você sempre gostou de ser durona...",
  ui_story_5022_50221601_154_dialog_content = "E de onde eu tirei isso? Ninguém menos que você!",
  ui_story_5022_50221601_155_dialog_content = "… Huh? É assim mesmo?",
  ui_story_5022_50221601_156_dialog_content = "Você é quem deveria estar sentado e deixar os jovens tomarem o reinado!",
  ui_story_5022_50221601_157_dialog_content = "<color=#e8d9bb>Bom... Bom!</color>",
  ui_story_5022_50221601_158_dialog_content = "...",
  ui_story_5022_50221601_159_dialog_content = "...",
  ui_story_5022_50221601_160_dialog_content = "Wahahaha! As faíscas explodiram no rosto de Regina! Olha, hahaha!",
  ui_story_5022_50221601_161_dialog_content = "Brock, seu rosto também está manchado.",
  ui_story_5022_50221601_162_dialog_content = "Barbara, Eu vou te matar!",
  ui_story_5022_50221601_163_dialog_content = "Uau! Esta bomba seria perfeita no palco. Você não acha, Tiny One?",
  ui_story_5022_50221601_164_dialog_content = "Sim, mas precisamos ajustar o raio de explosão. Deixe-me ver a estrutura interna...",
  ui_story_5022_50221601_165_dialog_content = "Você gosta, você gosta? Eu tenho mais da mesma série! Eles foram melhorados!",
  ui_story_5022_50221601_166_dialog_content = "Você só quer soltar fogos de artifício.",
  ui_story_5022_50221601_167_dialog_content = "Não é a maneira perfeita de terminar a festa de comemoração? Até Lepidoz está abanando o rabo.",
  ui_story_5022_50221601_168_dialog_content = "O que você estava dizendo? \"Deixe os jovens tomarem as rédeas\" ou algo assim?",
  ui_story_5022_50221601_169_dialog_content = "Nossa, esses pirralhos…",
  ui_story_5022_50221601_170_dialog_content = "Hahaha, não é uma coisa ruim para eles manterem sua juventude.",
  ui_story_5022_50221601_171_dialog_content = "Cae-les-tite! Foi você que comeu minha sobremesa?!",
  ui_story_5022_50221601_172_dialog_content = "Mesmo se você salvou minha vida, roubar a sobremesa de alguém não pode ser perdoado!",
  ui_story_5022_50221601_173_dialog_content = "Não fui eu! foi a senhorita Azure... Ela...",
  ui_story_5022_50221601_174_dialog_content = "Onde ela foi? Perder Azure!",
  ui_story_5022_50221601_175_dialog_content = "Oh meu Deus, parece que seu pequeno companheiro de equipe está com problemas. Você não vai intervir?",
  ui_story_5022_50221601_176_dialog_content = "Não subestime PlayerName.",
  ui_story_5022_50221601_177_dialog_content = "Há coisas interessantes ainda por vir para esse.",
  ui_story_5022_50221601_178_dialog_content = "A história do celestita não terminará com pudim.",
  ui_story_5022_50221601_179_dialog_content = "Eu acredito nisso.",
  ui_story_5022_50221601_180_dialog_content = "Sim, essa foi uma ótima frase que você acabou de dizer. Mas isso não muda o fato de que o celestita está sendo perseguido por sua causa.",
  ui_story_5022_50221601_181_dialog_content = "Azure! Roy!",
  ui_story_5022_50221601_182_dialog_content = "Venha aqui! É hora dos fogos de artifício!",
  ui_story_5022_50221601_183_dialog_content = "3——2——1——!"
}
return config
